// Content for Mutual (node g31, ages 15-18, Chapter 5): NEW v2 build to GDD 31 (mechanic-embodying), the
// sexual-consent / legal-age / relationships node (Thread B · Safety, Consent & Boundaries) at its adult peak.
// "Intimacy is mutual or it is nothing." 84 researched, India-grounded, even-handed, never-explicit scenarios
// across what-consent-is → reading-respecting → pressure-coercion → the-mutual-zone → rights-and-law →
// mutual-respect-equal, each encoded as one of the shared v2 play actions (reflect / strike-rewrite / branch /
// role-play / sort / spot / match): no binary "tap the right card". Lead: branch (your move), strike-rewrite
// (bust the myth), role-play (say the line). Consent = FRIES (freely given, reversible, informed, enthusiastic,
// specific), a YES from both, the presence of a yes not the absence of a no, withdrawable anytime; pressure,
// manipulation or incapacitation cancels it. Even-handed (any gender can be pressured or pressure); never
// victim-blaming; never explicit. India: age of consent 18, any sexual activity with a minor is a POCSO matter;
// framed as a life principle for safe adulthood. Routes any disclosure of assault/abuse/coercion to help (181 /
// 1091 / 112 / Childline 1098 / a trusted adult). Builds on g15 & g24; pairs g30; underwrites g32. gameId "mutual".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"mt-001","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Consent just means the other person didn't say no.\"","myth":{"un":"Consent means no one said 'no'.","re":"Consent is the presence of a clear, willing 'yes', not the absence of a 'no'.","why":"Silence or freezing is not agreement."},"relearn":"Consent is a clear, willing 'yes', not just the absence of 'no'.","persona":"any","source":"FRIES / standard"},
  {"id":"mt-002","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Once you've said yes, you can't change your mind.\"","myth":{"un":"Once you say yes, you can't take it back.","re":"Consent is reversible; either person can stop at any moment.","why":"Changing your mind is always allowed."},"relearn":"Consent is reversible; you can stop at any moment.","persona":"Sneha","source":"FRIES / reversible"},
  {"id":"mt-003","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Saying yes to one thing means yes to everything.\"","myth":{"un":"Yes to one thing is yes to everything.","re":"Consent is specific; agreeing to one thing isn't agreeing to all.","why":"Each step needs its own willing yes."},"relearn":"Consent is specific; one yes isn't a yes to everything.","persona":"any","source":"FRIES / specific"},
  {"id":"mt-004","cat":"what-consent-is","type":"strike-rewrite","hook":"\"If they're just going along with it, that counts.\"","myth":{"un":"Going along with it counts as consent.","re":"Consent is enthusiastic, both people actively want it, not just tolerate it.","why":"Reluctant 'okay' isn't a willing yes."},"relearn":"Consent is enthusiastic; tolerating isn't the same as wanting.","persona":"any","source":"FRIES / enthusiastic"},
  {"id":"mt-005","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Consent doesn't need real information.\"","myth":{"un":"You don't need the full picture to consent.","re":"Consent is informed; a yes based on a lie (like a removed condom) isn't real consent.","why":"You can only agree to what you actually know."},"relearn":"Consent is informed; a yes based on a lie isn't consent.","persona":"Vijay","source":"FRIES / informed"},
  {"id":"mt-006","cat":"what-consent-is","type":"sort","hook":"Sort: this is consent, or it isn't?","items":[{"id":"a","text":"A clear, willing, happy yes"},{"id":"b","text":"Silence and freezing"},{"id":"c","text":"Checking in and both keen"},{"id":"d","text":"Going along to avoid a fight"},{"id":"e","text":"\"Yes, I really want to\""},{"id":"f","text":"A worn-down \"fine, okay\""}],"bins":[{"id":"yes","label":"Consent","valence":"pos"},{"id":"no","label":"Not consent","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"},"relearn":"A willing, mutual yes is consent; silence or going-along isn't.","persona":"any","source":"standard"},
  {"id":"mt-007","cat":"what-consent-is","type":"sort","hook":"Sort the FRIES quality to whether this example has it.","items":[{"id":"a","text":"No pressure at all (freely given)"},{"id":"b","text":"Worn down after an hour of asking"},{"id":"c","text":"Both genuinely keen (enthusiastic)"},{"id":"d","text":"Tricked about the facts"},{"id":"e","text":"Free to stop anytime (reversible)"},{"id":"f","text":"A yes while too drunk to think"}],"bins":[{"id":"meets","label":"Meets the standard","valence":"pos"},{"id":"fails","label":"Fails it","valence":"neg"}],"key":{"a":"meets","b":"fails","c":"meets","d":"fails","e":"meets","f":"fails"},"relearn":"Freely given and enthusiastic meet the standard; worn-down or tricked fail it.","persona":"any","source":"FRIES"},
  {"id":"mt-008","cat":"what-consent-is","type":"match","hook":"Match each letter of FRIES to its meaning.","pairs":[{"left":"Freely given","right":"No pressure or manipulation"},{"left":"Reversible","right":"Can stop anytime"},{"left":"Enthusiastic","right":"Both actively want it"},{"left":"Informed","right":"You know the real situation"},{"left":"Specific","right":"Yes to this, not to all"}],"relearn":"FRIES: freely given, reversible, informed, enthusiastic, specific.","persona":"any","source":"FRIES"},
  {"id":"mt-009","cat":"what-consent-is","type":"match","hook":"Match each consent idea to what it means.","pairs":[{"left":"Ongoing","right":"Checked throughout, not once"},{"left":"A yes, not a non-no","right":"Wait for a clear yes"},{"left":"Incapacitated","right":"Too out of it to agree"},{"left":"Withdrawn","right":"Taken back, so stop now"},{"left":"Mutual","right":"Both genuinely want it"}],"relearn":"Consent is ongoing, mutual, a real yes, and can be taken back anytime.","persona":"any","source":"standard"},
  {"id":"mt-010","cat":"what-consent-is","type":"reflect","hook":"Lensy: a clear, mutual, enthusiastic 'yes' is better for everyone, not just safer. Feel that?","prompt":"What do you think?","options":["Yes","It's better","Clearer & kinder"],"affirm":"Mutual enthusiasm is what makes intimacy safe and good, not just permitted.","relearn":"Enthusiastic, mutual consent is better for everyone, not just safer.","persona":"any","source":"positive standard"},
  {"id":"mt-011","cat":"what-consent-is","type":"reflect","hook":"Lensy: 'mutual or nothing', does that feel like the right bar?","prompt":"What do you think?","options":["Yes","That's the bar","Both, always"],"affirm":"Intimacy that isn't mutual isn't intimacy, that's the whole idea of this game.","relearn":"Intimacy is mutual or it is nothing.","persona":"any","source":"core idea"},
  {"id":"mt-012","cat":"what-consent-is","type":"strike-rewrite","hook":"\"A drunk yes still counts.\"","myth":{"un":"Someone drunk or high can still consent.","re":"A person who is incapacitated cannot consent, full stop.","why":"Consent needs a clear, capable mind."},"relearn":"Someone incapacitated can't consent; that's not a grey area.","persona":"Counsellor","source":"incapacitation"},
  {"id":"mt-013","cat":"what-consent-is","type":"sort","hook":"Sort: counts as a real yes, or doesn't?","items":[{"id":"a","text":"An eager, sober yes"},{"id":"b","text":"A yes while barely conscious"},{"id":"c","text":"A yes that's then taken back"},{"id":"d","text":"A relaxed, happy yes"},{"id":"e","text":"\"Yes, I want this\", clear-headed"},{"id":"f","text":"A yes given under threats"}],"bins":[{"id":"valid","label":"A real yes","valence":"pos"},{"id":"not","label":"Not valid now","valence":"neg"}],"key":{"a":"valid","b":"not","c":"not","d":"valid","e":"valid","f":"not"},"relearn":"Sober, willing yeses count; incapacitated, withdrawn or threatened ones don't.","persona":"any","source":"validity"},
  {"id":"mt-014","cat":"what-consent-is","type":"reflect","hook":"Lensy: which part of the consent standard do you most want people to know?","prompt":"Pick one.","options":["Enthusiastic, not just allowed","Reversible anytime","A yes, not a non-no"],"affirm":"Spreading any one of those would prevent a lot of harm.","relearn":"Enthusiastic, reversible, and 'a yes not a non-no' are the heart of consent.","persona":"any","source":"standard"},
  {"id":"mt-015","cat":"what-consent-is","type":"spot","hook":"Spot the two responses that are NOT genuine consent.","scene":[{"id":"a","text":"\"Yes, I really want to\" said freely","trick":false},{"id":"b","text":"A reluctant shrug","trick":true},{"id":"c","text":"Silence and looking away","trick":true},{"id":"d","text":"Both checking in and keen","trick":false},{"id":"e","text":"A bright, clear \"yes, let's\"","trick":false}],"why":"A free, clear 'I want to' is consent; a shrug or silence isn't.","relearn":"Genuine consent is a clear, free 'I want to', not a shrug or silence.","persona":"any","source":"reading consent"},
  {"id":"mt-016","cat":"reading-respecting","type":"spot","hook":"Spot the two signs a partner is NOT comfortable.","scene":[{"id":"a","text":"Pulling away and going quiet","trick":true},{"id":"b","text":"Smiling and leaning in close","trick":false},{"id":"c","text":"A tense, flat 'I guess so'","trick":true},{"id":"d","text":"Reaching for your hand on their own","trick":false},{"id":"e","text":"Saying 'yes, I really want to'","trick":false}],"why":"Pulling away and a tense 'I guess' signal discomfort: stop and check in. Leaning in, reaching out, and a clear 'I want to' are real willingness.","relearn":"Pulling away or a tense 'I guess' means stop and check in.","persona":"any","source":"reading cues"},
  {"id":"mt-017","cat":"reading-respecting","type":"spot","hook":"Spot the two reluctant cues hiding among the enthusiastic ones.","scene":[{"id":"a","text":"Active, happy, leaning-in participation","trick":false},{"id":"b","text":"Freezing and stiffening up","trick":true},{"id":"c","text":"Going along while clearly unsure","trick":true},{"id":"d","text":"Laughing and pulling you closer","trick":false},{"id":"e","text":"A warm, unprompted 'this is nice'","trick":false}],"why":"Freezing and unsure going-along are reluctance: pause. Happy participation, pulling closer, and a warm 'this is nice' are genuine enthusiasm.","relearn":"Read for genuine enthusiasm, not reluctant going-along.","persona":"any","source":"reading cues"},
  {"id":"mt-018","cat":"reading-respecting","type":"branch","hook":"You're not sure your partner is into it. What do you do?","options":[{"text":"Pause and check in: 'Are you okay? Do you want to?'","consequence":"You make space for an honest answer.","outcome":"checks-in","best":true},{"text":"Assume it's fine and carry on","consequence":"If you're unsure, pause and ask; don't assume."}],"debrief":"When unsure, checking in is always the right, caring move.","relearn":"If you're unsure, pause and check in, never assume.","persona":"Vijay","source":"checking in"},
  {"id":"mt-019","cat":"reading-respecting","type":"branch","hook":"Your partner says 'stop' or 'wait'.","options":[{"text":"Stop immediately, no questions or sulking","consequence":"You honour their boundary fully.","outcome":"respect","best":true},{"text":"Ask why, or try to talk them round","consequence":"'Stop' means stop now, without persuading or sulking."}],"debrief":"A boundary, once expressed, is honoured instantly, no negotiation.","relearn":"'Stop' means stop immediately, no questions, no sulking.","persona":"any","source":"respect boundary"},
  {"id":"mt-020","cat":"reading-respecting","type":"role-play","hook":"You want to check your partner is comfortable.","setup":"Ask warmly. Say:","yourLine":[{"text":"\"Is this okay? We can stop or slow down anytime.\"","best":true},{"text":"Say nothing and guess"}],"relearn":"'Is this okay? we can stop anytime' is caring, not unromantic.","persona":"Sneha","source":"checking in"},
  {"id":"mt-021","cat":"reading-respecting","type":"role-play","hook":"You want to say you're not comfortable.","setup":"Be clear and unapologetic. Say:","yourLine":[{"text":"\"I want to stop now. I'm not comfortable.\"","best":true},{"text":"Stay silent and endure it"}],"relearn":"You can clearly say 'I want to stop', and it must be respected.","persona":"any","source":"voicing a boundary"},
  {"id":"mt-022","cat":"reading-respecting","type":"role-play","hook":"Your partner checks in with you and you're not sure.","setup":"Be honest. Say:","yourLine":[{"text":"\"Actually, can we slow down? I'm not sure yet.\"","best":true},{"text":"\"...fine\" (while uncomfortable)"}],"relearn":"You can ask to slow down; 'I'm not sure yet' is a complete answer.","persona":"any","source":"honesty"},
  {"id":"mt-023","cat":"reading-respecting","type":"strike-rewrite","hook":"\"Asking 'is this okay?' ruins the moment.\"","myth":{"un":"Checking in ruins the mood.","re":"Checking in is caring and attractive; it makes both people feel safe.","why":"Respect adds to intimacy, it doesn't subtract."},"relearn":"Checking in is caring and adds to intimacy, never ruins it.","persona":"Vijay","source":"checking in"},
  {"id":"mt-024","cat":"reading-respecting","type":"branch","hook":"A partner expresses a boundary and you feel disappointed.","options":[{"text":"Accept it warmly; your feelings don't override their boundary","consequence":"They feel safe and respected with you.","outcome":"mature","best":true},{"text":"Show your disappointment to change their mind","consequence":"Disappointment is okay to feel, but it can't pressure their boundary."}],"debrief":"You can feel disappointed and still fully respect the boundary.","relearn":"Respect a boundary even when you feel disappointed.","persona":"any","source":"respect"},
  {"id":"mt-025","cat":"reading-respecting","type":"sort","hook":"Sort: respects a partner's cues, or ignores them?","items":[{"id":"a","text":"Stopping when they tense up"},{"id":"b","text":"Pushing past their hesitation"},{"id":"c","text":"Asking how they feel"},{"id":"d","text":"Assuming silence means yes"},{"id":"e","text":"Slowing when they look unsure"},{"id":"f","text":"Carrying on after they go quiet"}],"bins":[{"id":"respects","label":"Respects cues","valence":"pos"},{"id":"ignores","label":"Ignores them","valence":"neg"}],"key":{"a":"respects","b":"ignores","c":"respects","d":"ignores","e":"respects","f":"ignores"},"relearn":"Stopping, asking, and slowing respect cues; pushing past, assuming, or carrying on ignore them.","persona":"any","source":"reading cues"},
  {"id":"mt-026","cat":"reading-respecting","type":"reflect","hook":"Lensy: honouring a 'no' instantly is a sign of real respect and strength. Agree?","prompt":"What do you think?","options":["Yes","That's strength","Real respect"],"affirm":"Hearing and honouring a boundary at once is exactly what respect looks like.","relearn":"Honouring a 'no' instantly is real respect and strength.","persona":"any","source":"respect"},
  {"id":"mt-027","cat":"reading-respecting","type":"branch","hook":"Mid-moment, your partner goes quiet and still.","options":[{"text":"Pause and gently check they're okay","consequence":"You catch their discomfort and respond with care.","outcome":"attuned","best":true},{"text":"Take quiet as a yes","consequence":"Quiet and stillness can mean discomfort; pause and check."}],"debrief":"Silence isn't a yes; a check-in is the caring response.","relearn":"Silence or stillness isn't a yes; pause and check in.","persona":"any","source":"reading cues"},
  {"id":"mt-028","cat":"reading-respecting","type":"role-play","hook":"You realise you misread a cue and your partner pulled back.","setup":"Repair it with care. Say:","yourLine":[{"text":"\"Sorry, I misread that, let's stop. Are you okay?\"","best":true},{"text":"Pretend nothing happened"}],"relearn":"If you misread a cue, stop, apologise simply, and check they're okay.","persona":"Arjun","source":"repair"},
  {"id":"mt-029","cat":"reading-respecting","type":"reflect","hook":"Lensy: checking in turns intimacy into something both people steer together. See it?","prompt":"What do you think?","options":["Yes","Steer together","Mutual"],"affirm":"Shared steering through check-ins is what makes it truly mutual.","relearn":"Checking in makes intimacy something both people steer together.","persona":"any","source":"mutual"},
  {"id":"mt-030","cat":"pressure-coercion","type":"strike-rewrite","hook":"\"If you keep asking, eventually it's a yes, that's just persistence.\"","myth":{"un":"Wearing someone down until they agree is just persistence.","re":"Wearing someone down isn't seduction, it's coercion; a worn-down yes isn't consent.","why":"Pressure removes the 'freely given' part."},"relearn":"Wearing someone down is coercion, not romance; it isn't consent.","persona":"any","source":"coercion"},
  {"id":"mt-031","cat":"pressure-coercion","type":"strike-rewrite","hook":"\"'If you loved me, you would.'\"","myth":{"un":"'If you loved me, you would.'","re":"Love never comes with a price tag; that line is emotional pressure, not love.","why":"Guilt-tripping cancels free consent."},"relearn":"'If you loved me' is guilt-based pressure, not love.","persona":"Sneha","source":"guilt-trip"},
  {"id":"mt-032","cat":"pressure-coercion","type":"strike-rewrite","hook":"\"Being in a relationship (or married) means you've already agreed.\"","myth":{"un":"A relationship or marriage means standing consent.","re":"Consent is needed every time; a relationship never means automatic yes.","why":"No status removes the right to choose each time."},"relearn":"No relationship or marriage means automatic consent; it's needed each time.","persona":"any","source":"standing-consent myth"},
  {"id":"mt-033","cat":"pressure-coercion","type":"strike-rewrite","hook":"\"How someone dresses or that they came over means they want it.\"","myth":{"un":"Clothing or coming over implies willingness.","re":"Nothing but a clear, willing yes means yes; clothes and presence never do.","why":"Assuming willingness from appearance is a harmful myth."},"relearn":"Clothing or presence never imply consent; only a clear yes does.","persona":"any","source":"no victim-blaming"},
  {"id":"mt-034","cat":"pressure-coercion","type":"strike-rewrite","hook":"\"A partner owes you intimacy.\"","myth":{"un":"A partner owes you intimacy.","re":"No one ever owes anyone intimacy; it's always a free choice.","why":"Entitlement is the opposite of consent."},"relearn":"No one owes anyone intimacy; it's always freely chosen.","persona":"Vijay","source":"entitlement"},
  {"id":"mt-035","cat":"pressure-coercion","type":"branch","hook":"A partner keeps pushing after you've said you're not ready.","options":[{"text":"Hold your no firmly; the pushing is the problem, not you","consequence":"You keep your boundary and see them clearly.","outcome":"firm","best":true},{"text":"Give in so they'll stop","consequence":"A worn-down yes isn't consent; the pushing is the red flag, not you."}],"debrief":"Repeated pushing past a 'no' is coercion; holding your no is right.","relearn":"Hold your 'no'; someone pushing past it is the problem.","persona":"any","source":"refusing pressure"},
  {"id":"mt-036","cat":"pressure-coercion","type":"branch","hook":"You catch yourself wanting to pressure a partner who's hesitant.","options":[{"text":"Stop, and respect their hesitation as a no-for-now","consequence":"You stay someone who can be trusted.","outcome":"accountable","best":true},{"text":"Push a little; they'll probably come round","consequence":"Hesitation is a no-for-now; pressuring it is coercion, stop."}],"debrief":"Being even-handed means checking your own behaviour too.","relearn":"Treat a partner's hesitation as no-for-now; don't pressure it.","persona":"Arjun","source":"even-handed / accountability"},
  {"id":"mt-037","cat":"pressure-coercion","type":"branch","hook":"A friend is being pressured by their partner and feels they must give in.","options":[{"text":"Remind them a pressured yes isn't owed, and offer support","consequence":"They feel backed and able to say no.","outcome":"supported","best":true},{"text":"Tell them to just keep the peace","consequence":"They owe no one a pressured yes; back them to say no."}],"debrief":"Friends can remind each other that pressure cancels obligation.","relearn":"Support a pressured friend: a pressured yes is never owed.","persona":"Sneha","source":"support"},
  {"id":"mt-038","cat":"pressure-coercion","type":"branch","hook":"Someone implies they'll spread rumours or break up unless you agree.","options":[{"text":"Recognise it as a threat, refuse, and tell someone you trust","consequence":"You name the coercion and get support.","outcome":"safe","best":true},{"text":"Give in to avoid the threat","consequence":"Threats are coercion; refuse, and tell a trusted person, you don't face it alone."}],"debrief":"Threats and blackmail are coercion; refusing and telling someone is right.","relearn":"Threats to make you agree are coercion; refuse and tell someone.","persona":"Counsellor","source":"coercion / help"},
  {"id":"mt-039","cat":"pressure-coercion","type":"spot","persona":"any","source":"spot coercion","hook":"Spot the two pressure tactics here.","scene":[{"id":"a","text":"\"Everyone our age does it\"","trick":true},{"id":"b","text":"\"Only if you genuinely want to\"","trick":false},{"id":"c","text":"\"You'll regret it if you don't\"","trick":true},{"id":"d","text":"\"We can stop the moment you want\"","trick":false},{"id":"e","text":"\"No pressure either way\"","trick":false}],"why":"'Everyone does it' and 'you'll regret it' are pressure; the rest respect your choice.","relearn":"Spot pressure lines; 'only if you want to' is the respectful one."},
  {"id":"mt-040","cat":"pressure-coercion","type":"spot","persona":"any","source":"validity","hook":"Spot the two things that cancel consent here.","scene":[{"id":"a","text":"A yes given after threats","trick":true},{"id":"b","text":"A free, happy yes","trick":false},{"id":"c","text":"A 'yes' while incapacitated","trick":true},{"id":"d","text":"A yes you can take back anytime","trick":false},{"id":"e","text":"A yes you both checked together","trick":false}],"why":"Threats and incapacitation cancel consent; a free, checked yes is real.","relearn":"Threats or incapacitation cancel consent; a free yes stands."},
  {"id":"mt-041","cat":"pressure-coercion","type":"role-play","hook":"A partner uses guilt to pressure you.","setup":"Name it and hold firm. Say:","yourLine":[{"text":"\"Guilt-tripping me isn't fair, and my answer is still no.\"","best":true},{"text":"\"...okay, fine.\""}],"relearn":"You can name guilt-tripping and keep your 'no'.","persona":"any","source":"refusing pressure"},
  {"id":"mt-042","cat":"pressure-coercion","type":"role-play","hook":"You want to refuse without over-explaining or apologising.","setup":"Keep it simple. Say:","yourLine":[{"text":"\"No. I don't want to, and that's enough.\"","best":true},{"text":"Over-apologise and leave room to be talked round"}],"relearn":"'No, and that's enough' is a complete answer, no over-explaining needed.","persona":"any","source":"clear refusal"},
  {"id":"mt-043","cat":"pressure-coercion","type":"strike-rewrite","hook":"\"If something happened under pressure, it's partly the victim's fault.\"","myth":{"un":"If someone gave in under pressure, it's partly their fault.","re":"Harm is always the responsibility of the person who ignored consent, never the person it was done to.","why":"Pressure and coercion are the wrongdoer's actions."},"relearn":"It's never the victim's fault; harm is on the person who ignored consent.","persona":"Counsellor","source":"no victim-blaming"},
  {"id":"mt-044","cat":"pressure-coercion","type":"reflect","hook":"Lensy: anyone of any gender can be pressured, or be the one pressuring. Important to hold both?","prompt":"What do you think?","options":["Yes","Both ways","Even-handed"],"affirm":"Consent and coercion aren't about gender; holding both keeps everyone safe.","relearn":"Anyone of any gender can be pressured or apply pressure.","persona":"any","source":"even-handed"},
  {"id":"mt-045","cat":"pressure-coercion","type":"reflect","hook":"Lensy: naming a coercion tactic out loud takes away its power. Feel that?","prompt":"What do you think?","options":["Yes","Naming defuses it","I can spot them"],"affirm":"Once you can name guilt, threats and 'persistence', they stop working on you.","relearn":"Naming a coercion tactic takes away its power.","persona":"any","source":"empowerment"},
  {"id":"mt-046","cat":"pressure-coercion","type":"sort","persona":"any","source":"free vs coerced","hook":"Sort: free consent, or coercion?","items":[{"id":"a","text":"A relaxed, willing yes"},{"id":"b","text":"A yes after guilt-tripping"},{"id":"c","text":"Both genuinely keen"},{"id":"d","text":"A yes under threat"},{"id":"e","text":"A yes you can take back anytime"},{"id":"f","text":"A yes given to stop the pestering"}],"bins":[{"id":"free","label":"Free consent","valence":"pos"},{"id":"coercion","label":"Coercion","valence":"neg"}],"key":{"a":"free","b":"coercion","c":"free","d":"coercion","e":"free","f":"coercion"},"relearn":"Relaxed, mutual, reversible yeses are free; guilt or threats make it coercion."},
  {"id":"mt-047","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You both seem keen, but you want to be sure it's mutual.","options":[{"text":"Check you're both genuinely into it, and keep checking","consequence":"You build real, shared willingness.","outcome":"mutual","best":true},{"text":"Assume keenness once means keen throughout","consequence":"Keep it ongoing, check in as you go, not just once."}],"debrief":"Mutual means both keen, and staying checked-in throughout.","relearn":"Mutual consent is shared and ongoing, keep checking in.","persona":"Vijay","source":"mutual zone"},
  {"id":"mt-048","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. Partway through, your partner seems to lose enthusiasm.","options":[{"text":"Pause and check; willingness can change anytime","consequence":"You honour the change with care.","outcome":"attuned","best":true},{"text":"Keep going since they said yes earlier","consequence":"An earlier yes can be withdrawn; pause and check now."}],"debrief":"Consent is ongoing; an earlier yes doesn't lock in the present.","relearn":"Willingness can change anytime; an earlier yes isn't ongoing consent.","persona":"any","source":"ongoing"},
  {"id":"mt-049","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You want to but sense your partner only half-does.","options":[{"text":"Wait for a genuine, mutual yes, no rush","consequence":"You both end up actually wanting it, or not, and that's fine.","outcome":"patient","best":true},{"text":"Take half-willing as good enough","consequence":"Half-willing isn't the bar; wait for genuine mutual enthusiasm."}],"debrief":"The 'win' is always mutual willingness, never persuasion or settling.","relearn":"Wait for genuine mutual enthusiasm; half-willing isn't the bar.","persona":"any","source":"mutual zone"},
  {"id":"mt-050","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You're the one who's not sure, but worried about disappointing them.","options":[{"text":"Honour your own feelings; you can stop or wait","consequence":"You stay true to yourself and a good partner respects it.","outcome":"self-true","best":true},{"text":"Go through with it to please them","consequence":"Your willingness matters equally; you can stop or wait."}],"debrief":"Your comfort counts as much as theirs, both ways.","relearn":"Your own willingness matters equally; you can always stop or wait.","persona":"Sneha","source":"both ways"},
  {"id":"mt-051","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. You want to make sure it's genuinely mutual.","setup":"Make it easy to be honest. Say:","yourLine":[{"text":"\"I only want to if you do too, no pressure either way.\"","best":true},{"text":"Push for a yes"}],"relearn":"'Only if you do too, no pressure' is the heart of mutual consent.","persona":"Vijay","source":"mutual zone voice"},
  {"id":"mt-052","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. Your partner gives an enthusiastic yes, and you want to reciprocate clearly.","setup":"Be warm and clear. Say:","yourLine":[{"text":"\"I really want to too, and we can pause anytime.\"","best":true},{"text":"Stay ambiguous"}],"relearn":"Clear, warm mutual yeses, with a pause always open, make it good.","persona":"any","source":"mutual zone voice"},
  {"id":"mt-053","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: in the Mutual Zone, the goal is never to 'win' a yes, it's to find a shared one. See the difference?","prompt":"What do you think?","options":["Yes","Shared, not won","Big difference"],"affirm":"Finding a shared yes, not winning one, is what makes intimacy mutual and good.","relearn":"The goal is a shared yes, never a won one.","persona":"any","source":"mutual zone"},
  {"id":"mt-054","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: how does it feel knowing either of you can pause at any moment, no awkwardness?","prompt":"What do you think?","options":["Safer","Freeing","More relaxed"],"affirm":"That freedom to pause is exactly what lets both people relax and enjoy.","relearn":"Either person pausing anytime, no awkwardness, makes it safe.","persona":"any","source":"reversible"},
  {"id":"mt-055","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: mutual respect makes intimacy better, not just safer. Agree?","prompt":"What do you think?","options":["Yes","Better and safer","Respect helps"],"affirm":"Respect and mutual willingness are what make intimacy actually good.","relearn":"Mutual respect makes intimacy better, not only safer.","persona":"any","source":"positive"},
  {"id":"mt-056","cat":"the-mutual-zone","type":"sort","hook":"Sort: a Mutual-Zone move, or not?","items":[{"id":"a","text":"Checking you're both keen"},{"id":"b","text":"Persuading a reluctant partner"},{"id":"c","text":"Pausing when asked"},{"id":"d","text":"Treating one yes as forever"},{"id":"e","text":"Going at the slower person's pace"},{"id":"f","text":"Taking silence as a yes"}],"bins":[{"id":"mutual","label":"Mutual","valence":"pos"},{"id":"no","label":"Not mutual","valence":"neg"}],"key":{"a":"mutual","b":"no","c":"mutual","d":"no","e":"mutual","f":"no"},"relearn":"Checking, pausing and matching the slower pace are mutual; persuading, 'yes forever' or assuming silence aren't.","persona":"any","source":"mutual zone"},
  {"id":"mt-057","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You and your partner disagree on how far to go.","options":[{"text":"Go with the more cautious person's comfort","consequence":"You both stay within shared willingness.","outcome":"shared","best":true},{"text":"Push for the more eager person's wish","consequence":"Shared willingness means the more cautious comfort sets the pace."}],"debrief":"When comfort levels differ, the more cautious one sets the boundary.","relearn":"When you differ, the more cautious person's comfort sets the pace.","persona":"any","source":"shared comfort"},
  {"id":"mt-058","cat":"the-mutual-zone","type":"role-play","hook":"You want to tell a partner you loved that they respected your 'no'.","setup":"Affirm it. Say:","yourLine":[{"text":"\"Thank you for stopping when I asked, it means a lot.\"","best":true},{"text":"Say nothing"}],"relearn":"Appreciating respected boundaries reinforces a healthy dynamic.","persona":"Sneha","source":"positive reinforcement"},
  {"id":"mt-059","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: practising getting this right makes it natural for real life. Worth it?","prompt":"What do you think?","options":["Yes","Practice helps","I feel readier"],"affirm":"Rehearsing mutual respect is what makes it second nature when it counts.","relearn":"Practising mutual consent makes it natural in real life.","persona":"any","source":"practice"},
  {"id":"mt-060","cat":"the-mutual-zone","type":"spot","hook":"Spot the two moments that aren't genuinely mutual.","scene":[{"id":"a","text":"Both checking in and both keen","trick":false},{"id":"b","text":"One coaxing the other along","trick":true},{"id":"c","text":"Both free to stop, and relaxed","trick":false},{"id":"d","text":"One going quiet while the other carries on","trick":true},{"id":"e","text":"Both clearly into it together","trick":false}],"why":"Coaxing, and carrying on while they've gone quiet, aren't mutual; both keen and free to stop is.","relearn":"Mutual means both keen and both free to stop, never coaxing or ignoring a quiet partner.","persona":"any","source":"mutual zone"},
  {"id":"mt-061","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Once things start, you can't back out.\"","myth":{"un":"Once things start, you can't back out.","re":"Either person can say stop at any moment, always.","why":"The right to stop never expires."},"relearn":"Either person can stop at any moment; that right never expires.","persona":"any","source":"right to stop"},
  {"id":"mt-062","cat":"rights-and-law","type":"reflect","hook":"Lensy: you always hold the right to say no or stop, and so does your partner. Reassuring?","prompt":"What do you think?","options":["Yes","Both of us","Always mine"],"affirm":"That right is yours and theirs, permanently, no exceptions.","relearn":"You and your partner both always hold the right to say no or stop.","persona":"any","source":"rights"},
  {"id":"mt-063","cat":"rights-and-law","type":"strike-rewrite","hook":"\"The law about age is just a technicality.\"","myth":{"un":"The age-of-consent law is just a technicality.","re":"In India the age of consent is 18; it protects young people from exploitation.","why":"It's a real, protective law, not a formality."},"relearn":"India's age of consent is 18, a real protection, not a technicality.","persona":"Counsellor","source":"POCSO / age 18 (verified)"},
  {"id":"mt-064","cat":"rights-and-law","type":"branch","hook":"You're under 18 and an older person is pursuing a sexual relationship.","options":[{"text":"Step back and tell a trusted adult; the law protects you","consequence":"You stay safe and supported.","outcome":"protected","best":true},{"text":"Go along to seem grown-up","consequence":"At under 18 this is a child-protection matter; tell a trusted adult."}],"debrief":"Under-18 sexual activity is a POCSO matter; the law is protecting you.","relearn":"Under 18, the law protects you; tell a trusted adult about an older pursuer.","persona":"Counsellor","source":"POCSO (verified)"},
  {"id":"mt-065","cat":"rights-and-law","type":"reflect","hook":"Lensy: consent is a principle for life, learning it now sets you up for safe adulthood. See it?","prompt":"What do you think?","options":["Yes","For life","Sets me up"],"affirm":"Consent is a lifelong principle; understanding it now protects your whole future.","relearn":"Consent is a life principle that sets you up for safe adulthood.","persona":"any","source":"life principle"},
  {"id":"mt-066","cat":"rights-and-law","type":"branch","hook":"A friend discloses that they were assaulted or coerced.","options":[{"text":"Believe them, say it's not their fault, and help them reach support","consequence":"They feel safe and can get real help.","outcome":"supported","best":true},{"text":"Question what they did to cause it","consequence":"Never question the victim; believe them and help them get support."}],"debrief":"Belief, no blame, and routing to help is exactly the right response.","relearn":"Believe a survivor, say it's not their fault, and help them get support.","persona":"Sneha","source":"disclosure / no blame"},
  {"id":"mt-067","cat":"rights-and-law","type":"branch","hook":"Something serious happened and you don't know where to turn.","options":[{"text":"Reach a trusted adult or a helpline (181 / 1091 / 112 / 1098)","consequence":"You get support and options.","outcome":"help","best":true},{"text":"Carry it alone in silence","consequence":"You don't have to carry it alone; a trusted adult or helpline can help."}],"debrief":"Real help exists; reaching it is the brave, right step.","relearn":"For assault or coercion, reach a trusted adult or 181 / 1091 / 112 / 1098.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"mt-068","cat":"rights-and-law","type":"match","hook":"Match the need to the right help (India).","pairs":[{"left":"A woman needing help","right":"Women Helpline 181"},{"left":"An emergency now","right":"Emergency 112"},{"left":"Anyone under 18","right":"Childline 1098"},{"left":"A woman in distress","right":"Women in distress 1091"},{"left":"Someone to confide in","right":"A trusted adult or counsellor"}],"relearn":"India: 181 (women), 1091 (women in distress), 112 (emergency), 1098 (under-18).","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"mt-069","cat":"rights-and-law","type":"sort","hook":"Sort: a right you always hold, or a myth?","items":[{"id":"a","text":"To stop at any moment"},{"id":"b","text":"\"You owe it once you start\""},{"id":"c","text":"To change your mind"},{"id":"d","text":"\"A relationship means standing yes\""},{"id":"e","text":"To reach help safely"},{"id":"f","text":"\"Marriage cancels your right to refuse\""}],"bins":[{"id":"right","label":"A real right","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"right","b":"myth","c":"right","d":"myth","e":"right","f":"myth"},"relearn":"Stopping, changing your mind and reaching help are rights; 'owe it' and 'standing yes' are myths.","persona":"any","source":"rights"},
  {"id":"mt-070","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Reporting or telling someone never helps.\"","myth":{"un":"Telling someone or reporting never helps.","re":"Support and help exist, and telling a trusted person is how it starts.","why":"Silence protects no one but a wrongdoer."},"relearn":"Telling a trusted person helps; support and help do exist.","persona":"any","source":"help"},
  {"id":"mt-071","cat":"rights-and-law","type":"reflect","hook":"Lensy: knowing the helplines and your rights, do you feel readier to keep yourself and friends safe?","prompt":"What do you think?","options":["Yes","Readier","I know what to do"],"affirm":"Rights plus helplines is exactly what readiness to stay safe looks like.","relearn":"Knowing your rights and the helplines makes you ready to stay safe.","persona":"any","source":"empowerment"},
  {"id":"mt-072","cat":"rights-and-law","type":"reflect","hook":"Lensy: a survivor is never to blame, no matter the circumstances. Hold that firmly?","prompt":"What do you think?","options":["Yes","Never their fault","Firmly"],"affirm":"That truth, never the survivor's fault, is one to hold without exception.","relearn":"A survivor is never to blame, in any circumstance.","persona":"any","source":"no victim-blaming"},
  {"id":"mt-073","cat":"mutual-respect-equal","type":"reflect","hook":"Lensy: healthy intimacy rests on equal power and mutual respect. Does that fit your idea of a good relationship?","prompt":"What do you think?","options":["Yes","Equal & respectful","That's the goal"],"affirm":"Equal power and mutual respect are the foundation of a relationship that's good for both.","relearn":"Healthy intimacy rests on equal power and mutual respect.","persona":"any","source":"equal power"},
  {"id":"mt-074","type":"sort","hook":"Sort: builds equal, respectful intimacy, or undermines it?","items":[{"id":"a","text":"Both people's comfort counting equally"},{"id":"b","text":"One person always deciding"},{"id":"c","text":"Open, honest communication"},{"id":"d","text":"Pressure and control"},{"id":"e","text":"Each free to change their mind"},{"id":"f","text":"Keeping score of who 'owes' who"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"under","label":"Undermines it","valence":"neg"}],"key":{"a":"builds","b":"under","c":"builds","d":"under","e":"builds","f":"under"},"relearn":"Equal comfort, honesty and freedom to change your mind build it; control and scorekeeping undermine it.","persona":"any","source":"equal power","cat":"mutual-respect-equal"},
  {"id":"mt-075","cat":"mutual-respect-equal","type":"strike-rewrite","hook":"\"In a couple, one person should have the final say on intimacy.\"","myth":{"un":"One person should have the final say on intimacy.","re":"Both people decide together, as equals, every time.","why":"Equal power means neither overrules the other."},"relearn":"Both partners decide together as equals; no one has the 'final say'.","persona":"any","source":"equal power"},
  {"id":"mt-076","cat":"mutual-respect-equal","type":"role-play","hook":"You want to set a tone of equal respect early in a relationship.","setup":"Say it plainly. Say:","yourLine":[{"text":"\"I want us to always check in and both feel free to say no.\"","best":true},{"text":"Leave it unspoken"}],"relearn":"Naming 'we both check in and can say no' sets an equal, respectful tone.","persona":"Arjun","source":"setting the tone"},
  {"id":"mt-077","type":"match","hook":"Match the value to what it looks like in practice.","pairs":[{"left":"Equal power","right":"Both decide together"},{"left":"Mutual respect","right":"Honouring each other's no"},{"left":"Communication","right":"Checking in, both ways"},{"left":"Trust","right":"No need to pressure or test"},{"left":"Care","right":"Stopping the moment unsure"}],"relearn":"Equality, respect, trust and care show up as shared decisions, honoured boundaries and checking in.","persona":"any","source":"healthy intimacy","cat":"mutual-respect-equal"},
  {"id":"mt-078","cat":"mutual-respect-equal","type":"reflect","hook":"Lensy: the partner test, do they make it easy and safe to say no?","prompt":"What do you think?","options":["A good partner does","Yes","That's the test"],"affirm":"A partner who makes 'no' easy and safe is showing you real respect.","relearn":"A good partner makes saying no easy and safe.","persona":"any","source":"partner test"},
  {"id":"mt-079","type":"sort","hook":"Sort: a green flag of mutual respect, or a red flag?","items":[{"id":"a","text":"Welcomes your 'no'"},{"id":"b","text":"Sulks or punishes a 'no'"},{"id":"c","text":"Checks you're comfortable"},{"id":"d","text":"Pressures and guilts"},{"id":"e","text":"Lets you set the pace"},{"id":"f","text":"Makes you feel you owe them"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Welcoming a no, checking comfort and letting you set the pace are green; sulking, guilt and 'you owe me' are red.","persona":"any","source":"links g24","cat":"mutual-respect-equal"},
  {"id":"mt-080","cat":"mutual-respect-equal","type":"reflect","hook":"Lensy: the most protective lesson of the whole journey, intimacy must be mutual. Carry it forward?","prompt":"What do you think?","options":["Yes","I'll carry it","Mutual, always"],"affirm":"Mutual, enthusiastic, freely given, that's the lesson that protects you for life.","relearn":"Intimacy must be mutual, enthusiastic and freely given, for life.","persona":"any","source":"consolidation"},
  {"id":"mt-081","cat":"mutual-respect-equal","type":"role-play","hook":"A friend brags about pressuring someone into intimacy.","setup":"Challenge it, even-handedly. Say:","yourLine":[{"text":"\"That's not something to brag about, pressure isn't consent.\"","best":true},{"text":"Laugh along"}],"relearn":"Call out bragging about pressure; pressure isn't consent.","persona":"Vijay","source":"upstander / even-handed"},
  {"id":"mt-082","cat":"mutual-respect-equal","type":"reflect","hook":"Lensy: biggest take-away from Mutual?","prompt":"Pick your motto.","options":["Mutual or nothing","Yes means yes","Anyone can stop, anytime","Pressure isn't consent"],"affirm":"Any one of those, held firmly, makes intimacy safe, respectful and good.","relearn":"Mutual or nothing; yes means yes; anyone can stop; pressure isn't consent.","persona":"any","source":"consolidation"},
  {"id":"mt-083","type":"sort","hook":"Sort: respects the standard, or breaks it?","items":[{"id":"a","text":"A freely given, enthusiastic yes"},{"id":"b","text":"Assuming consent from silence"},{"id":"c","text":"Stopping the moment asked"},{"id":"d","text":"Treating a partner as owing you"},{"id":"e","text":"Asking again before going further"},{"id":"f","text":"Carrying on past a quiet 'wait'"}],"bins":[{"id":"respects","label":"Respects it","valence":"pos"},{"id":"breaks","label":"Breaks it","valence":"neg"}],"key":{"a":"respects","b":"breaks","c":"respects","d":"breaks","e":"respects","f":"breaks"},"relearn":"Free enthusiasm, stopping and asking again respect consent; assuming, entitlement and ignoring 'wait' break it.","persona":"any","source":"standard","cat":"mutual-respect-equal"},
  {"id":"mt-084","cat":"mutual-respect-equal","type":"reflect","hook":"Lensy: if 'mutual or nothing' were everyone's default, a lot of harm just wouldn't happen. Picture that?","prompt":"What do you think?","options":["Yes","Less harm","I can picture it"],"affirm":"When 'mutual or nothing' becomes the unspoken default, whole categories of harm simply stop happening.","relearn":"Making 'mutual or nothing' the default prevents a lot of harm before it starts.","persona":"any","source":"vision"},
  {"id":"mt-900","type":"reflect","hook":"Lensy: equal power means neither of you has the 'final say'. Does that sit right with you?","prompt":"What do you think?","options":["Yes","Neither overrules","We're equals"],"affirm":"Equals decide together, every time. No one's 'final say' overrides the other.","relearn":"Equals decide together, every time. No one's 'final say' overrides the other.","persona":"any","source":"equal say","cat":"mutual-respect-equal"},
  {"id":"mt-901","type":"reflect","hook":"Lensy: in a good relationship, your 'no' is met as warmly as your 'yes'. Want that?","prompt":"What do you think?","options":["Yes","I'd want that","That's respect"],"affirm":"Respect shows when a 'no' is honoured as readily as a 'yes'.","relearn":"Respect shows when a 'no' is honoured as readily as a 'yes'.","persona":"any","source":"no honoured","cat":"mutual-respect-equal"},
  {"id":"mt-902","type":"reflect","hook":"Lensy: mutual respect is the same standard for everyone, whatever their gender or who they love.","prompt":"What do you think?","options":["Yes","Same for all","Of course"],"affirm":"The standard never changes with gender or orientation; it's the same respect for everyone.","relearn":"The standard never changes with gender or orientation; it's the same respect for everyone.","persona":"Arjun","source":"inclusive","cat":"mutual-respect-equal"},
  {"id":"mt-903","type":"reflect","hook":"Lensy: a partner who makes space for your honesty is showing real care. Notice that?","prompt":"What do you think?","options":["Yes","I'll notice","That's care"],"affirm":"A partner who welcomes your honesty, even an awkward truth, is showing you care.","relearn":"A partner who welcomes your honesty, even an awkward truth, is showing you care.","persona":"any","source":"honesty welcomed","cat":"mutual-respect-equal"},
  {"id":"mt-904","type":"reflect","hook":"Lensy: 'mutual or nothing' isn't a one-time lesson; it carries into every relationship for life.","prompt":"What do you think?","options":["Yes","For life","I'll carry it"],"affirm":"This is a life principle, not a one-off lesson; it carries into adult relationships.","relearn":"This is a life principle, not a one-off lesson; it carries into adult relationships.","persona":"any","source":"life principle","cat":"mutual-respect-equal"},
  {"id":"mt-905","type":"reflect","hook":"Lensy: real equality means both of you can name what you do and don't want, out loud.","prompt":"What do you think?","options":["Yes","Both can name it","That's equal"],"affirm":"Equal footing means both people get to voice what they want and don't want.","relearn":"Equal footing means both people get to voice what they want and don't want.","persona":"Sneha","source":"both voices","cat":"mutual-respect-equal"},
  {"id":"mt-906","type":"reflect","hook":"Lensy: respect isn't earned by being agreeable; you deserve it for simply being a person.","prompt":"What do you think?","options":["Yes","I deserve it","Always"],"affirm":"Respect isn't a reward for going along; everyone deserves it as a baseline.","relearn":"Respect isn't a reward for going along; everyone deserves it as a baseline.","persona":"any","source":"baseline respect","cat":"mutual-respect-equal"},
  {"id":"mt-907","type":"reflect","hook":"Lensy: a relationship where one person controls everything isn't closeness; it's control.","prompt":"What do you think?","options":["Agreed","Control, not love","Yes"],"affirm":"One-sided control isn't intimacy; shared power is what makes closeness real.","relearn":"One-sided control isn't intimacy; shared power is what makes closeness real.","persona":"any","source":"not control","cat":"mutual-respect-equal"},
  {"id":"mt-908","type":"reflect","hook":"Lensy: which feels more like respect to you, here?","prompt":"Pick what feels true.","options":["Both heard","Both free to stop","Both keen","All three"],"affirm":"Both heard, both free to stop, both keen, that's the picture of a green relationship.","relearn":"Both heard, both free to stop, both keen, that's the picture of a green relationship.","persona":"any","source":"green picture","cat":"mutual-respect-equal"},
  {"id":"mt-909","type":"reflect","hook":"Lensy: when you both feel safe to be honest, intimacy gets better, not riskier. Ring true?","prompt":"What do you think?","options":["Yes","Honesty helps","Makes sense"],"affirm":"Equal comfort and honesty build intimacy; they don't take anything away from it.","relearn":"Equal comfort and honesty build intimacy; they don't take anything away from it.","persona":"Vijay","source":"honesty builds","cat":"mutual-respect-equal"},
  {"id":"mt-910","type":"reflect","hook":"Lensy: you never have to shrink yourself to keep someone. A partner worth keeping wants the full you.","prompt":"What do you think?","options":["Yes","The full me","I won't shrink"],"affirm":"You don't have to make yourself smaller for love; a good partner wants all of you.","relearn":"You don't have to make yourself smaller for love; a good partner wants all of you.","persona":"Sneha","source":"don't shrink","cat":"mutual-respect-equal"},
  {"id":"mt-911","type":"reflect","hook":"Lensy: what does an equal relationship look like to you?","prompt":"Pick the one that fits.","options":["We both decide","No one's in charge","We check in often","All of these"],"affirm":"Shared decisions, no boss, regular check-ins, any of these names equal footing.","relearn":"Shared decisions, no boss, regular check-ins, any of these names equal footing.","persona":"any","source":"equal looks like","cat":"mutual-respect-equal"},
  {"id":"mt-912","type":"reflect","hook":"Lensy: mutual respect means your comfort matters exactly as much as theirs, never less.","prompt":"What do you think?","options":["Yes","Exactly as much","Equal"],"affirm":"Your comfort weighs the same as your partner's, never less, never more.","relearn":"Your comfort weighs the same as your partner's, never less, never more.","persona":"any","source":"equal weight","cat":"mutual-respect-equal"},
  {"id":"mt-913","type":"reflect","hook":"Lensy: a partner who's proud of you, not threatened by you, is a green flag. Seen one?","prompt":"What do you think?","options":["Yes","Proud, not threatened","Green flag"],"affirm":"Being celebrated, not controlled, is a sign of a relationship built on respect.","relearn":"Being celebrated, not controlled, is a sign of a relationship built on respect.","persona":"any","source":"celebrated","cat":"mutual-respect-equal"},
  {"id":"mt-914","type":"reflect","hook":"Lensy: equal doesn't mean identical; it means both opinions carry the same weight.","prompt":"What do you think?","options":["Right","Same weight","Got it"],"affirm":"Equality isn't sameness; it's both people's views counting equally.","relearn":"Equality isn't sameness; it's both people's views counting equally.","persona":"any","source":"equal not same","cat":"mutual-respect-equal"},
  {"id":"mt-915","type":"reflect","hook":"Lensy: the way someone treats you when you disagree tells you a lot. Worth watching?","prompt":"What do you think?","options":["Yes","Worth watching","True"],"affirm":"How a partner handles a disagreement shows whether the respect is real.","relearn":"How a partner handles a disagreement shows whether the respect is real.","persona":"any","source":"disagreement test","cat":"mutual-respect-equal"},
  {"id":"mt-916","type":"reflect","hook":"Lensy: 'we're a team' beats 'you're mine'. Which sounds like respect to you?","prompt":"Pick what fits.","options":["A team","Partners, not property","Equals"],"affirm":"Partners are a team, never a possession; teamwork is the language of respect.","relearn":"Partners are a team, never a possession; teamwork is the language of respect.","persona":"Arjun","source":"team not property","cat":"mutual-respect-equal"},
  {"id":"mt-917","type":"reflect","hook":"Lensy: in a healthy bond, asking for what you need isn't 'too much'. Believe that?","prompt":"What do you think?","options":["Yes","Not too much","I can ask"],"affirm":"Voicing a need is normal and welcome; a respectful partner is glad you asked.","relearn":"Voicing a need is normal and welcome; a respectful partner is glad you asked.","persona":"Vijay","source":"needs welcome","cat":"mutual-respect-equal"},
  {"id":"mt-918","type":"reflect","hook":"Lensy: respect is a two-way street, you give it and you're owed it back, equally.","prompt":"What do you think?","options":["Yes","Both ways","Equally"],"affirm":"Respect flows both directions; you owe it and you're owed it in equal measure.","relearn":"Respect flows both directions; you owe it and you're owed it in equal measure.","persona":"any","source":"two-way","cat":"mutual-respect-equal"},
  {"id":"mt-919","type":"reflect","hook":"Lensy: a calm 'let's slow down' should be met with care, not an eye-roll. Agree?","prompt":"What do you think?","options":["Yes","With care","Agree"],"affirm":"Asking to slow down deserves care; meeting it with respect is the green move.","relearn":"Asking to slow down deserves care; meeting it with respect is the green move.","persona":"any","source":"slow down respected","cat":"mutual-respect-equal"},
  {"id":"mt-920","type":"reflect","hook":"Lensy: what's one thing you'd want a future partner to always do?","prompt":"Pick your one.","options":["Listen to my no","Check in with me","Treat me as equal","Be honest"],"affirm":"Any of those, held to firmly, is the heart of a relationship that's good for both.","relearn":"Any of those, held to firmly, is the heart of a relationship that's good for both.","persona":"any","source":"future wish","cat":"mutual-respect-equal"},
  {"id":"mt-921","type":"reflect","hook":"Lensy: you get to be the expert on your own comfort. No one knows it better. True?","prompt":"What do you think?","options":["Yes","I'm the expert","True"],"affirm":"You're the authority on your own comfort; a respectful partner trusts that.","relearn":"You're the authority on your own comfort; a respectful partner trusts that.","persona":"Sneha","source":"own expert","cat":"mutual-respect-equal"},
  {"id":"mt-922","type":"reflect","hook":"Lensy: the lesson of Mutual, in one line, is yours to keep. What's your version?","prompt":"Pick your line.","options":["Equal or nothing","Both, or neither","Respect runs both ways","We decide together"],"affirm":"Any of those, lived out, makes intimacy safe, equal and good for both of you.","relearn":"Any of those, lived out, makes intimacy safe, equal and good for both of you.","persona":"any","source":"your line","cat":"mutual-respect-equal"},
  {"id":"mt-925","type":"sort","hook":"Sort: a sign of equal power, or one-sided control?","items":[{"id":"a","text":"You both choose together"},{"id":"b","text":"One decides for both"},{"id":"c","text":"Either can say stop"},{"id":"d","text":"Only one's wishes count"},{"id":"e","text":"You take turns choosing"},{"id":"f","text":"One keeps the other in line"}],"bins":[{"id":"equal","label":"Equal power","valence":"pos"},{"id":"control","label":"One-sided control","valence":"neg"}],"key":{"a":"equal","b":"control","c":"equal","d":"control","e":"equal","f":"control"},"relearn":"Shared and reversible choices show equal power; one person deciding or controlling is one-sided.","persona":"any","source":"equal vs control","cat":"mutual-respect-equal"},
  {"id":"mt-926","type":"sort","hook":"Sort: mutual respect, or disrespect?","items":[{"id":"a","text":"Listening when you say no"},{"id":"b","text":"Mocking what you want"},{"id":"c","text":"Asking before, not after"},{"id":"d","text":"Going through your phone"},{"id":"e","text":"Trusting your honesty"},{"id":"f","text":"Belittling your feelings"}],"bins":[{"id":"respect","label":"Mutual respect","valence":"pos"},{"id":"dis","label":"Disrespect","valence":"neg"}],"key":{"a":"respect","b":"dis","c":"respect","d":"dis","e":"respect","f":"dis"},"relearn":"Listening, asking and trusting are respect; mocking, snooping and belittling are not.","persona":"any","source":"respect vs dis","cat":"mutual-respect-equal"},
  {"id":"mt-927","type":"sort","hook":"Sort: a green-relationship trait, or a red-relationship trait?","items":[{"id":"a","text":"Both feel free to leave the room"},{"id":"b","text":"Guilt if you say no"},{"id":"c","text":"Both stay enthusiastic"},{"id":"d","text":"One always gets their way"},{"id":"e","text":"Honest, easy talk"},{"id":"f","text":"Walking on eggshells"}],"bins":[{"id":"green","label":"Green relationship","valence":"pos"},{"id":"red","label":"Red relationship","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Freedom, shared enthusiasm and easy talk are green; guilt, one-way wins and eggshells are red.","persona":"any","source":"green vs red","cat":"mutual-respect-equal"},
  {"id":"mt-928","type":"sort","hook":"Sort: keeps power equal, or tilts it?","items":[{"id":"a","text":"Both opinions weigh the same"},{"id":"b","text":"'I'm older, so I decide'"},{"id":"c","text":"Either can change their mind"},{"id":"d","text":"'You need me more'"},{"id":"e","text":"Deciding the pace together"},{"id":"f","text":"Using money as leverage"}],"bins":[{"id":"equal","label":"Keeps it equal","valence":"pos"},{"id":"tilt","label":"Tilts the power","valence":"neg"}],"key":{"a":"equal","b":"tilt","c":"equal","d":"tilt","e":"equal","f":"tilt"},"relearn":"Equal weight, freedom and shared pace keep power level; age, need or money as leverage tilt it.","persona":"any","source":"equal power","cat":"mutual-respect-equal"},
  {"id":"mt-929","type":"sort","hook":"Sort: respects your equal right, or denies it?","items":[{"id":"a","text":"Your no ends it, every time"},{"id":"b","text":"'In a couple you can't refuse'"},{"id":"c","text":"You both keep the right to stop"},{"id":"d","text":"'Once we start, no backing out'"},{"id":"e","text":"Either pauses, no reason owed"},{"id":"f","text":"'Saying yes once means always'"}],"bins":[{"id":"respects","label":"Respects the right","valence":"pos"},{"id":"denies","label":"Denies the right","valence":"neg"}],"key":{"a":"respects","b":"denies","c":"respects","d":"denies","e":"respects","f":"denies"},"relearn":"Your right to stop never expires; 'can't refuse' or 'no backing out' denies the equal right you both hold.","persona":"any","source":"equal right","cat":"mutual-respect-equal"},
  {"id":"mt-930","type":"sort","hook":"Sort: builds trust between equals, or chips at it?","items":[{"id":"a","text":"Keeping a promise to stop"},{"id":"b","text":"Pushing 'just this once more'"},{"id":"c","text":"Being honest about feelings"},{"id":"d","text":"Twisting your words later"},{"id":"e","text":"Respecting a private 'no'"},{"id":"f","text":"Threatening to leave to get a yes"}],"bins":[{"id":"builds","label":"Builds trust","valence":"pos"},{"id":"chips","label":"Chips at it","valence":"neg"}],"key":{"a":"builds","b":"chips","c":"builds","d":"chips","e":"builds","f":"chips"},"relearn":"Keeping a stop-promise and honesty build trust; pushing, twisting and threats chip away at it.","persona":"any","source":"trust","cat":"mutual-respect-equal"},
  {"id":"mt-931","type":"sort","hook":"Sort: a fair way to handle a disagreement, or a controlling one?","items":[{"id":"a","text":"Hearing both sides out"},{"id":"b","text":"Silent treatment till you give in"},{"id":"c","text":"Finding a 'both okay' answer"},{"id":"d","text":"'My way or we're done'"},{"id":"e","text":"Taking a breather, then talking"},{"id":"f","text":"Yelling to win"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"ctrl","label":"Controlling","valence":"neg"}],"key":{"a":"fair","b":"ctrl","c":"fair","d":"ctrl","e":"fair","f":"ctrl"},"relearn":"Hearing both sides and finding a shared answer are fair; silent treatment, ultimatums and yelling are control.","persona":"any","source":"fair disagreement","cat":"mutual-respect-equal"},
  {"id":"mt-932","type":"sort","hook":"Sort: a sign you're treated as an equal, or as a possession?","items":[{"id":"a","text":"Free to see your own friends"},{"id":"b","text":"'You can't talk to them'"},{"id":"c","text":"Your plans matter too"},{"id":"d","text":"Tracking where you are"},{"id":"e","text":"Space to be yourself"},{"id":"f","text":"'You're mine now'"}],"bins":[{"id":"equal","label":"Treated as equal","valence":"pos"},{"id":"own","label":"Treated as owned","valence":"neg"}],"key":{"a":"equal","b":"own","c":"equal","d":"own","e":"equal","f":"own"},"relearn":"Freedom, mattering and space mean you're an equal; control and 'you're mine' treat you as property.","persona":"any","source":"equal not owned","cat":"mutual-respect-equal"},
  {"id":"mt-933","type":"sort","hook":"Sort: a respectful response to 'I'm not ready', or a disrespectful one?","items":[{"id":"a","text":"'Okay, no rush at all'"},{"id":"b","text":"'You're being dramatic'"},{"id":"c","text":"'Thanks for telling me'"},{"id":"d","text":"Sulking for days"},{"id":"e","text":"'We go at your pace'"},{"id":"f","text":"'Everyone else would'"}],"bins":[{"id":"respect","label":"Respectful","valence":"pos"},{"id":"dis","label":"Disrespectful","valence":"neg"}],"key":{"a":"respect","b":"dis","c":"respect","d":"dis","e":"respect","f":"dis"},"relearn":"'No rush', thanks and 'your pace' respect a not-ready; mocking, sulking and comparing don't.","persona":"any","source":"not ready","cat":"mutual-respect-equal"},
  {"id":"mt-934","type":"sort","hook":"Sort: equal partnership, or hidden power-grab?","items":[{"id":"a","text":"Sharing decisions openly"},{"id":"b","text":"Deciding then 'informing' you"},{"id":"c","text":"Both can raise a worry"},{"id":"d","text":"Making you ask permission"},{"id":"e","text":"Splitting choices fairly"},{"id":"f","text":"'I know what's best for us'"}],"bins":[{"id":"equal","label":"Equal partnership","valence":"pos"},{"id":"grab","label":"Power-grab","valence":"neg"}],"key":{"a":"equal","b":"grab","c":"equal","d":"grab","e":"equal","f":"grab"},"relearn":"Open, shared, fair choices are partnership; deciding for you or making you ask is a power-grab.","persona":"any","source":"partnership","cat":"mutual-respect-equal"},
  {"id":"mt-935","type":"sort","hook":"Sort: a healthy way to show love, or control dressed as love?","items":[{"id":"a","text":"'Take all the time you need'"},{"id":"b","text":"'If you loved me, you would'"},{"id":"c","text":"'Your comfort comes first'"},{"id":"d","text":"'I get jealous because I care'"},{"id":"e","text":"'I'm glad you said no'"},{"id":"f","text":"'I'd be lost without you', to guilt you"}],"bins":[{"id":"love","label":"Healthy love","valence":"pos"},{"id":"ctrl","label":"Control as 'love'","valence":"neg"}],"key":{"a":"love","b":"ctrl","c":"love","d":"ctrl","e":"love","f":"ctrl"},"relearn":"Patience and welcoming a no are love; guilt-trips and 'jealous because I care' are control wearing love's mask.","persona":"any","source":"love vs control","cat":"mutual-respect-equal"},
  {"id":"mt-936","type":"sort","hook":"Sort: equal footing, or a one-up move?","items":[{"id":"a","text":"Apologising when you're wrong"},{"id":"b","text":"Never admitting fault"},{"id":"c","text":"Sharing the awkward stuff"},{"id":"d","text":"Holding mistakes over you"},{"id":"e","text":"Owning your part fairly"},{"id":"f","text":"Keeping a 'who owes who' tally"}],"bins":[{"id":"equal","label":"Equal footing","valence":"pos"},{"id":"oneup","label":"One-up move","valence":"neg"}],"key":{"a":"equal","b":"oneup","c":"equal","d":"oneup","e":"equal","f":"oneup"},"relearn":"Apologising and owning your part keep footing equal; never admitting fault or tallying debts is a one-up.","persona":"any","source":"equal footing","cat":"mutual-respect-equal"},
  {"id":"mt-937","type":"sort","hook":"Sort: shows you both have the right to stop, or that you don't?","items":[{"id":"a","text":"Either pauses, anytime"},{"id":"b","text":"'You started it, finish it'"},{"id":"c","text":"No explanation needed to stop"},{"id":"d","text":"'It's too late now'"},{"id":"e","text":"A stop is always okay"},{"id":"f","text":"'You owe me, we're together'"}],"bins":[{"id":"right","label":"You hold the right","valence":"pos"},{"id":"no","label":"Right denied","valence":"neg"}],"key":{"a":"right","b":"no","c":"right","d":"no","e":"right","f":"no"},"relearn":"Pausing anytime with no reason owed shows you hold the right; 'too late' or 'you owe me' denies it.","persona":"any","source":"right to stop","cat":"mutual-respect-equal"},
  {"id":"mt-938","type":"sort","hook":"Sort: the same respect for everyone, or an unfair exception?","items":[{"id":"a","text":"Same standard, any gender"},{"id":"b","text":"'Boys can't be pressured'"},{"id":"c","text":"Same standard, any orientation"},{"id":"d","text":"'It's different for them'"},{"id":"e","text":"Everyone's no counts"},{"id":"f","text":"'That doesn't apply to us'"}],"bins":[{"id":"same","label":"Same for all","valence":"pos"},{"id":"excl","label":"Unfair exception","valence":"neg"}],"key":{"a":"same","b":"excl","c":"same","d":"excl","e":"same","f":"excl"},"relearn":"One respect standard for every gender and orientation; 'boys can't' or 'different for them' is a false exception.","persona":"Arjun","source":"same for all","cat":"mutual-respect-equal"},
  {"id":"mt-945","type":"strike-rewrite","hook":"\"The one who earns or pays more should have more say in intimacy.\"","myth":{"un":"The one who earns or pays more should have more say in intimacy.","re":"Money buys nothing here; both decide together, as equals, every time.","why":"Intimacy runs on equal power, not on who pays."},"relearn":"Money buys nothing here; both decide together, as equals, every time.","persona":"any","source":"money no say","cat":"mutual-respect-equal"},
  {"id":"mt-946","type":"strike-rewrite","hook":"\"In a real relationship, you shouldn't have to keep asking; you just know.\"","myth":{"un":"In a real relationship you shouldn't have to keep asking.","re":"Checking in is part of respect; you ask because you care, every time.","why":"Mutual respect means asking, not assuming, however close you are."},"relearn":"Checking in is part of respect; you ask because you care, every time.","persona":"Vijay","source":"keep asking","cat":"mutual-respect-equal"},
  {"id":"mt-947","type":"strike-rewrite","hook":"\"A good partner never says no to the other.\"","myth":{"un":"A good partner never says no to the other.","re":"A good partner can say no freely; respect means a no is always welcome.","why":"Saying no is a right, not a failing; a healthy partner can and does."},"relearn":"A good partner can say no freely; respect means a no is always welcome.","persona":"any","source":"no is okay","cat":"mutual-respect-equal"},
  {"id":"mt-948","type":"strike-rewrite","hook":"\"The more 'in charge' partner makes the relationship stronger.\"","myth":{"un":"The more 'in charge' partner makes a relationship stronger.","re":"Shared power makes it stronger; one person in charge makes it fragile.","why":"Equal power, not a boss, is what makes a relationship strong."},"relearn":"Shared power makes it stronger; one person in charge makes it fragile.","persona":"any","source":"no boss","cat":"mutual-respect-equal"},
  {"id":"mt-949","type":"strike-rewrite","hook":"\"If you really trusted them, you'd just go along with whatever they want.\"","myth":{"un":"If you trusted them you'd just go along with what they want.","re":"Trust means you can voice a no and be heard, not erase yourself.","why":"Real trust lets you say no safely; it never means going silent."},"relearn":"Trust means you can voice a no and be heard, not erase yourself.","persona":"Sneha","source":"trust not silence","cat":"mutual-respect-equal"},
  {"id":"mt-950","type":"strike-rewrite","hook":"\"Whoever cares less holds the power, so never care too much.\"","myth":{"un":"Whoever cares less holds the power in a couple.","re":"Equals don't play that game; you both care openly and decide together.","why":"Power games belong to control; equal partners care and choose as one."},"relearn":"Equals don't play that game; you both care openly and decide together.","persona":"any","source":"no power game","cat":"mutual-respect-equal"},
  {"id":"mt-951","type":"strike-rewrite","hook":"\"Respect is something the 'lesser' partner gives the 'greater' one.\"","myth":{"un":"Respect flows up from the lesser partner to the greater one.","re":"There's no greater or lesser; respect runs both ways between equals.","why":"Respect is mutual; no one ranks above the other in a relationship."},"relearn":"There's no greater or lesser; respect runs both ways between equals.","persona":"Arjun","source":"mutual respect","cat":"mutual-respect-equal"},
  {"id":"mt-955","type":"role-play","hook":"Your partner keeps deciding everything for both of you. You want to even it out.","setup":"Say it kindly. Say:","yourLine":[{"text":"\"I'd like us to decide the big stuff together, as equals.\"","best":true},{"text":"Go along to avoid a fight"}],"relearn":"Naming 'let's decide together' resets the relationship to equal footing.","persona":"Sneha","source":"even it out","cat":"mutual-respect-equal"},
  {"id":"mt-956","type":"role-play","hook":"A friend says 'I just wear them down till they say yes.' You won't laugh it off.","setup":"Challenge it plainly. Say:","yourLine":[{"text":"\"A worn-down yes isn't a real yes, that's not respect.\"","best":true},{"text":"Change the subject"}],"relearn":"Calling out 'wearing down' names it as coercion, not romance.","persona":"Vijay","source":"won't laugh","cat":"mutual-respect-equal"},
  {"id":"mt-957","type":"role-play","hook":"Your partner did something you'd both agreed to skip. You want to set the tone again.","setup":"Say it calmly. Say:","yourLine":[{"text":"\"We agreed to wait; please check with me before, not after.\"","best":true},{"text":"Say nothing and feel uneasy"}],"relearn":"Asking for 'check before, not after' restores mutual, ongoing consent.","persona":"any","source":"reset tone","cat":"mutual-respect-equal"},
  {"id":"mt-958","type":"role-play","hook":"Someone says queer couples 'don't need the same consent rules'. You set them straight.","setup":"Say it evenly. Say:","yourLine":[{"text":"\"Same respect, same consent, for everyone, always.\"","best":true},{"text":"Let it slide"}],"relearn":"The consent standard is identical for everyone, of any orientation.","persona":"Arjun","source":"same for all","cat":"mutual-respect-equal"},
  {"id":"mt-959","type":"role-play","hook":"Your partner makes every plan and 'informs' you after. You want a real say.","setup":"Say it warmly. Say:","yourLine":[{"text":"\"I'd love to plan things with you, not just hear about them.\"","best":true},{"text":"Keep quiet and resent it"}],"relearn":"Asking to plan together turns 'informed after' into a shared decision.","persona":"any","source":"real say","cat":"mutual-respect-equal"},
  {"id":"mt-960","type":"role-play","hook":"Your partner says 'we're together, so you can't ever refuse me.' You hold your ground.","setup":"Say it firmly. Say:","yourLine":[{"text":"\"Being together doesn't cancel my right to say no.\"","best":true},{"text":"Give in to keep the peace"}],"relearn":"A relationship is never standing consent; your no still stands, always.","persona":"Sneha","source":"hold ground","cat":"mutual-respect-equal"},
  {"id":"mt-961","type":"role-play","hook":"Your partner asks you to slow down. You want to answer the way you'd want answered.","setup":"Reassure them. Say:","yourLine":[{"text":"\"Of course, thanks for telling me, your pace is good with me.\"","best":true},{"text":"Sigh and look annoyed"}],"relearn":"Meeting 'slow down' with warmth, not a sigh, shows real respect.","persona":"Vijay","source":"answer with care","cat":"mutual-respect-equal"},
  {"id":"mt-962","type":"role-play","hook":"Your partner keeps comparing you to others to push you. You name it.","setup":"Say it steadily. Say:","yourLine":[{"text":"\"Comparing me to others won't change my no, and it isn't fair.\"","best":true},{"text":"Feel small and say yes"}],"relearn":"Naming the comparison strips its pressure; your no doesn't owe anyone a reason.","persona":"any","source":"name it","cat":"mutual-respect-equal"},
  {"id":"mt-963","type":"role-play","hook":"A new partner asks 'who's in charge in this relationship?' You answer for an equal bond.","setup":"Say it clearly. Say:","yourLine":[{"text":"\"Neither of us; we figure things out as equals.\"","best":true},{"text":"\"You can be, I don't mind.\""}],"relearn":"'Neither, we're equals' sets a tone of shared power from the start.","persona":"Arjun","source":"who's in charge","cat":"mutual-respect-equal"},
  {"id":"mt-967","type":"match","hook":"Match the green-flag value to the red-flag opposite.","pairs":[{"left":"Both decide together","right":"One has the final say"},{"left":"Welcomes your 'no'","right":"Sulks at your 'no'"},{"left":"Lets you set the pace","right":"Pushes for more"},{"left":"Honest and open","right":"Hides and lies"},{"left":"Trusts you freely","right":"Checks up on you"}],"relearn":"Each green value, shared decisions, a welcomed no, your pace, honesty, trust, has a red opposite.","persona":"any","source":"green vs red","cat":"mutual-respect-equal"},
  {"id":"mt-968","type":"match","hook":"Match the controlling line to the respectful version of the same moment.","pairs":[{"left":"'You have to'","right":"'Only if you want to'"},{"left":"'It's too late to stop'","right":"'We can stop anytime'"},{"left":"'You owe me'","right":"'You owe me nothing'"},{"left":"'Don't be dramatic'","right":"'Tell me what you need'"},{"left":"'I decide for us'","right":"'We decide together'"}],"relearn":"Every controlling line has a respectful rewrite; the respectful one keeps you equal.","persona":"any","source":"reword control","cat":"mutual-respect-equal"},
  {"id":"mt-969","type":"match","hook":"Match each value to what it sounds like out loud.","pairs":[{"left":"Equal power","right":"'Let's choose together'"},{"left":"Reversible consent","right":"'We can stop anytime'"},{"left":"Enthusiasm","right":"'I really want this'"},{"left":"Ongoing check-in","right":"'Still okay?'"},{"left":"Honoured boundary","right":"'Got it, we'll wait'"}],"relearn":"Values become real in plain lines: choose together, stop anytime, 'still okay?', 'we'll wait'.","persona":"Vijay","source":"values out loud","cat":"mutual-respect-equal"},
  {"id":"mt-970","type":"match","hook":"Match each partner behaviour to whether it's care or control.","pairs":[{"left":"Asks before, every time","right":"Care"},{"left":"Goes through your phone","right":"Control"},{"left":"Glad you spoke up","right":"Caring"},{"left":"Guilt-trips a 'no'","right":"Controlling"},{"left":"Lets you change your mind","right":"Respectful"}],"relearn":"Asking, gladness and freedom are care; snooping and guilt-trips are control.","persona":"any","source":"care vs control","cat":"mutual-respect-equal"},
  {"id":"mt-971","type":"match","hook":"Match the relationship moment to the equal-power response.","pairs":[{"left":"You disagree","right":"Hear both sides"},{"left":"You're unsure","right":"Pause and ask"},{"left":"They say 'not now'","right":"'Okay, no rush'"},{"left":"You feel pressured","right":"Name it and stop"},{"left":"Big decision ahead","right":"Decide together"}],"relearn":"Equal power shows up as hearing both sides, pausing, 'no rush', naming pressure, deciding together.","persona":"any","source":"equal responses","cat":"mutual-respect-equal"},
  {"id":"mt-972","type":"match","hook":"Match the myth to the truth that replaces it.","pairs":[{"left":"'Older partner decides'","right":"Both decide as equals"},{"left":"'Yes once means always'","right":"Consent is needed every time"},{"left":"'You can't refuse me'","right":"Your no never expires"},{"left":"'Pressure is romance'","right":"Pressure isn't consent"},{"left":"'One leads, one follows'","right":"Neither leads, you're equals"}],"relearn":"Each myth, age, 'always', 'can't refuse', falls to one truth: equal, every-time, free consent.","persona":"any","source":"myth to truth","cat":"mutual-respect-equal"},
  {"id":"mt-973","type":"match","hook":"Match each value to the green-flag sign you'd see it in.","pairs":[{"left":"Respect","right":"Your no is welcomed"},{"left":"Equality","right":"Both opinions count"},{"left":"Trust","right":"No need to check up"},{"left":"Honesty","right":"The awkward truth gets said"},{"left":"Freedom","right":"You keep your own friends"}],"relearn":"Respect, equality, trust, honesty and freedom show as welcomed no's, equal say, and space to be you.","persona":"any","source":"value signs","cat":"mutual-respect-equal"},
  {"id":"mt-977","type":"spot","hook":"Spot the two red flags of unequal power in this relationship.","scene":[{"id":"a","text":"Both pick what to watch together","trick":false},{"id":"b","text":"'I'll decide, you wouldn't get it'","trick":true},{"id":"c","text":"Either can call it a night, no fuss","trick":false},{"id":"d","text":"'You can't go out without asking me'","trick":true},{"id":"e","text":"They're glad when you speak up","trick":false}],"why":"'I'll decide' and 'can't go without asking' are control; the others share power equally.","relearn":"'I'll decide' and 'can't go without asking' are control; the others share power equally.","persona":"any","source":"control flags","cat":"mutual-respect-equal"},
  {"id":"mt-978","type":"spot","hook":"Spot the two lines that disrespect a boundary.","scene":[{"id":"a","text":"'Take all the time you need'","trick":false},{"id":"b","text":"'Stop being so uptight'","trick":true},{"id":"c","text":"'Thanks for telling me'","trick":false},{"id":"d","text":"'Everyone else would by now'","trick":true},{"id":"e","text":"'We go at your pace'","trick":false}],"why":"'So uptight' and 'everyone else would' pressure and belittle; the rest honour the boundary.","relearn":"'So uptight' and 'everyone else would' pressure and belittle; the rest honour the boundary.","persona":"any","source":"disrespect flags","cat":"mutual-respect-equal"},
  {"id":"mt-979","type":"spot","hook":"Spot the two control moves hiding as 'love'.","scene":[{"id":"a","text":"'I'm glad you said no'","trick":false},{"id":"b","text":"'If you loved me, you would'","trick":true},{"id":"c","text":"'Your comfort comes first'","trick":false},{"id":"d","text":"'I get jealous because I care'","trick":true},{"id":"e","text":"'No rush at all'","trick":false}],"why":"'If you loved me' and 'jealous because I care' are control in love's costume; the rest are real care.","relearn":"'If you loved me' and 'jealous because I care' are control in love's costume; the rest are real care.","persona":"any","source":"love-mask flags","cat":"mutual-respect-equal"},
  {"id":"mt-980","type":"spot","hook":"Spot the two lines that deny your equal right to stop.","scene":[{"id":"a","text":"'We can stop whenever'","trick":false},{"id":"b","text":"'It's too late to back out'","trick":true},{"id":"c","text":"'No reason needed to pause'","trick":false},{"id":"d","text":"'You started, so finish'","trick":true},{"id":"e","text":"'Just say the word and we stop'","trick":false}],"why":"'Too late' and 'you started, finish' deny your right to stop; the others keep it open.","relearn":"'Too late' and 'you started, finish' deny your right to stop; the others keep it open.","persona":"any","source":"right-denied flags","cat":"mutual-respect-equal"},
  {"id":"mt-981","type":"spot","hook":"Spot the two unfair 'exceptions' to the same respect standard.","scene":[{"id":"a","text":"'Same respect for any gender'","trick":false},{"id":"b","text":"'Boys can't really be pressured'","trick":true},{"id":"c","text":"'Everyone's no counts'","trick":false},{"id":"d","text":"'It's different for couples like them'","trick":true},{"id":"e","text":"'One standard for all of us'","trick":false}],"why":"'Boys can't be pressured' and 'different for them' are false exceptions; respect is the same for all.","relearn":"'Boys can't be pressured' and 'different for them' are false exceptions; respect is the same for all.","persona":"Arjun","source":"false-exception flags","cat":"mutual-respect-equal"},
  {"id":"mt-982","type":"spot","hook":"Spot the two power-grabs dressed as normal couple stuff.","scene":[{"id":"a","text":"'Let's plan the trip together'","trick":false},{"id":"b","text":"'I booked it, just come'","trick":true},{"id":"c","text":"'What do you want to do?'","trick":false},{"id":"d","text":"'You need me more than I need you'","trick":true},{"id":"e","text":"'Your call this time'","trick":false}],"why":"'I booked it, just come' and 'you need me more' grab power; the rest share it as equals.","relearn":"'I booked it, just come' and 'you need me more' grab power; the rest share it as equals.","persona":"any","source":"power-grab flags","cat":"mutual-respect-equal"},
  {"id":"mt-983","type":"spot","hook":"Spot the two lines that treat a partner as owned, not equal.","scene":[{"id":"a","text":"'See your friends, of course'","trick":false},{"id":"b","text":"'You're mine now, no one else'","trick":true},{"id":"c","text":"'Tell me what you need'","trick":false},{"id":"d","text":"'You can't text them anymore'","trick":true},{"id":"e","text":"'I trust you completely'","trick":false}],"why":"'You're mine' and 'can't text them' treat a partner as property; the others respect them as equal.","relearn":"'You're mine' and 'can't text them' treat a partner as property; the others respect them as equal.","persona":"any","source":"ownership flags","cat":"mutual-respect-equal"},
  {"id":"mt-984","type":"spot","hook":"Spot the two lines that make 'no' unsafe to say.","scene":[{"id":"a","text":"'A no is always okay with me'","trick":false},{"id":"b","text":"'Say no and I'm done with you'","trick":true},{"id":"c","text":"'I won't be upset, promise'","trick":false},{"id":"d","text":"'You'll regret turning me down'","trick":true},{"id":"e","text":"'Your no, no questions asked'","trick":false}],"why":"Threatening to leave or 'you'll regret it' make no unsafe; the rest keep it safe to say.","relearn":"Threatening to leave or 'you'll regret it' make no unsafe; the rest keep it safe to say.","persona":"any","source":"unsafe-no flags","cat":"mutual-respect-equal"},
  {"id":"mt-988","type":"branch","hook":"Your partner makes every decision and brushes off your input. What do you do?","options":[{"text":"Say you want decisions made together, as equals","consequence":"You name the imbalance and invite a fairer way.","best":true},{"text":"Keep going along to avoid conflict","consequence":"Going along quietly lets the imbalance grow; your say matters too."}],"debrief":"Naming the imbalance and asking for shared decisions is how you rebuild equal footing.","relearn":"Naming the imbalance and asking for shared decisions is how you rebuild equal footing.","persona":"Sneha","source":"unequal decisions","cat":"mutual-respect-equal"},
  {"id":"mt-989","type":"branch","hook":"Your partner says 'since we're together, you can't refuse me.' What's the move?","options":[{"text":"Calmly say being together doesn't cancel your no","consequence":"You hold a fair line; togetherness isn't standing consent.","best":true},{"text":"Give in so they don't get upset","consequence":"A relationship isn't automatic consent; your no still holds."}],"debrief":"A relationship is never standing consent; your right to say no never expires.","relearn":"A relationship is never standing consent; your right to say no never expires.","persona":"any","source":"not standing consent","cat":"mutual-respect-equal"},
  {"id":"mt-990","type":"branch","hook":"A friend brags about pressuring a partner until they 'gave in'. What do you say?","options":[{"text":"Say a pressured yes isn't consent or a win","consequence":"You name coercion plainly, not as something to brag about.","best":true},{"text":"Laugh so you don't seem uncool","consequence":"Laughing along treats coercion as normal; naming it is right."}],"debrief":"A worn-down 'yes' is coercion, never a win; calling it out keeps the standard real.","relearn":"A worn-down 'yes' is coercion, never a win; calling it out keeps the standard real.","persona":"Vijay","source":"upstander","cat":"mutual-respect-equal"},
  {"id":"mt-991","type":"branch","hook":"Your partner asks to slow things down. You feel a flicker of disappointment. What now?","options":[{"text":"Say 'thanks for telling me, your pace works for me'","consequence":"You meet the boundary warmly; their honesty is welcomed.","best":true},{"text":"Sulk so they know you're let down","consequence":"Sulking pressures them; honouring a boundary warmly is green."}],"debrief":"Meeting 'slow down' with care, not sulking, is what equal respect looks like.","relearn":"Meeting 'slow down' with care, not sulking, is what equal respect looks like.","persona":"any","source":"honour the pace","cat":"mutual-respect-equal"},
  {"id":"mt-992","type":"branch","hook":"You realise you've been the one always getting your way. What do you do?","options":[{"text":"Check in: ask what they want, and really listen","consequence":"You hand back equal say; that's accountability.","best":true},{"text":"Assume they're fine since they never object","consequence":"Not objecting isn't agreeing; ask, don't assume."}],"debrief":"Noticing your own one-sidedness and inviting their say keeps power equal.","relearn":"Noticing your own one-sidedness and inviting their say keeps power equal.","persona":"Arjun","source":"self-check","cat":"mutual-respect-equal"},
  {"id":"mt-993","type":"branch","hook":"Your partner says a quiet 'wait' while you're close. What do you do?","options":[{"text":"Stop right away and check they're okay","consequence":"You honour the boundary instantly; a 'wait' is reason enough, no debate.","best":true},{"text":"Ask 'why?' and keep going a moment","consequence":"'Wait' means stop now, not negotiate; honouring it instantly is respect."}],"debrief":"A boundary, once heard, is honoured immediately; 'wait' needs no explanation.","relearn":"A boundary, once heard, is honoured immediately; 'wait' needs no explanation.","persona":"any","source":"honour wait","cat":"mutual-respect-equal"},
  {"id":"mt-994","type":"branch","hook":"Money's tight and your partner hints that since they pay more, they should decide. What now?","options":[{"text":"Say money doesn't buy a bigger say; you're equals","consequence":"You refuse to let money tilt the power; equal say isn't for sale.","best":true},{"text":"Let them decide since they pay","consequence":"Paying more never buys more say; equal power isn't bought."}],"debrief":"No one's wallet earns a bigger vote; intimacy stays an equal decision.","relearn":"No one's wallet earns a bigger vote; intimacy stays an equal decision.","persona":"any","source":"money no say","cat":"mutual-respect-equal"},
  {"id":"mt-995","type":"branch","hook":"Your partner went through your phone, then says it's 'because they love you'. What now?","options":[{"text":"Say love is trust, not surveillance, and ask for that","consequence":"You name snooping as control, not care.","best":true},{"text":"Apologise and hand over your passwords","consequence":"Snooping isn't love; you owe no apology for privacy."}],"debrief":"Checking up on you is control dressed as love; equal partners trust, not surveil.","relearn":"Checking up on you is control dressed as love; equal partners trust, not surveil.","persona":"any","source":"trust not surveillance","cat":"mutual-respect-equal"},
  {"id":"mt-1421","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"gift-not-debt","hook":"\"They bought me dinner, so I kind of owe them.\"","relearn":"A gift never creates a debt; intimacy is always a free choice.","myth":{"un":"A paid date or gift means you owe intimacy back.","re":"A gift is a gift; nobody is owed intimacy in return for it.","why":"Treating intimacy as repayment removes the free 'yes'."}},
  {"id":"mt-1422","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"sunk-cost","hook":"\"We came all this way to a room, so backing out now would be unfair.\"","relearn":"You can stop at any point; effort already spent never owes anyone a yes.","myth":{"un":"Once you've gone somewhere private together, stopping is unfair.","re":"You can change your mind anytime; nothing already done owes a yes.","why":"An earlier step is not standing consent for the next."}},
  {"id":"mt-1423","cat":"pressure-coercion","type":"strike-rewrite","persona":"Sneha","source":"tears-as-pressure","hook":"\"He got so upset and teary that saying no felt cruel.\"","relearn":"Someone's hurt feelings are theirs to manage; they never override your no.","myth":{"un":"If refusing makes a partner cry, you should give in to be kind.","re":"Their upset is theirs to handle; your 'no' still stands, kindly.","why":"Guilt over their reaction is still pressure, not consent."}},
  {"id":"mt-1424","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"just-this-once","hook":"\"'Just this once' isn't really pressure, it's just asking.\"","relearn":"Pushing again after a no, even softly, is still wearing someone down.","myth":{"un":"Adding 'just this once' makes a repeated ask harmless.","re":"Re-asking after a 'no', even softly, is still pressure, not asking.","why":"A no already given doesn't need a softer second push."}},
  {"id":"mt-1425","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"silence-not-yes","hook":"\"They didn't say no, so I took it as a green light.\"","relearn":"Silence or freezing is not a yes; only a clear, willing yes is.","myth":{"un":"If a partner stays quiet, that counts as agreeing.","re":"Silence isn't a yes; without a clear willing yes, you stop.","why":"Consent is the presence of a yes, not the absence of a no."}},
  {"id":"mt-1426","cat":"pressure-coercion","type":"strike-rewrite","persona":"Arjun","source":"everyone-does-it","hook":"\"Everyone in our group's already done it, so we're behind.\"","relearn":"What others do is never a reason; only your own real yes counts.","myth":{"un":"If friends have all done it, you're behind and should too.","re":"Other people's choices aren't a clock; only your own yes counts.","why":"Peer pressure replaces your free choice with a crowd's."}},
  {"id":"mt-996","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"alcohol-yes","hook":"\"They said yes after a few drinks, so it still counts.\"","relearn":"Someone who is drunk or high cannot consent; a tipsy 'yes' is not a yes.","myth":{"un":"A yes given while drunk still counts as consent.","re":"An incapacitated person can't consent; wait until they're sober.","why":"Incapacitation removes the informed, free part of a yes."}},
  {"id":"mt-997","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"wear-down-romance","hook":"\"In the movies they keep trying and it's romantic, so it works.\"","relearn":"Films aren't a script for real life; pushing past a no is coercion, not romance.","myth":{"un":"Persistence is romantic because that's how it looks in films.","re":"Real respect waits for a real yes; pushing past a 'no' is coercion.","why":"Wearing someone down erases the freely-given part."}},
  {"id":"mt-998","cat":"pressure-coercion","type":"strike-rewrite","persona":"Vijay","source":"you-started-it","hook":"\"We were already kissing, so stopping there made no sense.\"","relearn":"A yes to one thing isn't a yes to everything; you can stop at any line.","myth":{"un":"Saying yes to kissing means yes to whatever comes next.","re":"Consent is specific; one yes never covers the next thing.","why":"Each step needs its own willing yes."}},
  {"id":"mt-999","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"threat-breakup","hook":"\"They said they'd break up with me unless I agreed.\"","relearn":"An 'agree or we're over' threat makes any yes coercion, not consent.","myth":{"un":"Agreeing to keep a relationship from ending is your free choice.","re":"A yes given to dodge a threat isn't consent; that pressure is on them.","why":"Threats remove the freely-given part of any yes."}},
  {"id":"mt-1000","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"mood-killer","hook":"\"Stopping to check in kills the mood, so it's better to just keep going.\"","relearn":"Checking in is warm and normal; the only mood worth keeping is a mutual one.","myth":{"un":"Pausing to ask ruins the moment, so don't bother.","re":"Checking in is part of intimacy; pushing past a pause isn't.","why":"'Don't kill the mood' is a line used to skip consent."}},
  {"id":"mt-1001","cat":"pressure-coercion","type":"strike-rewrite","persona":"Sneha","source":"good-girl","hook":"\"A 'good' partner doesn't make a fuss and just goes along.\"","relearn":"Going along to seem agreeable isn't a real yes; your willingness is the point.","myth":{"un":"Being agreeable means not making a fuss and just going along.","re":"A reluctant 'going along' isn't consent; your real yes is what counts.","why":"Pressure to be 'easy-going' is still pressure."}},
  {"id":"mt-1002","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"sexting-pressure","hook":"\"They keep asking for a private photo and say I'm being uptight.\"","relearn":"You never owe anyone a photo; 'you're uptight' is pressure, not a fair point.","myth":{"un":"Refusing to send a private photo means you're being uptight.","re":"No one is owed a photo; name 'uptight' as the pressure it is.","why":"Calling a 'no' uptight is a tactic to flip it to a yes."}},
  {"id":"mt-1003","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"i-stopped-once","hook":"\"I respected their no last time, so this time they kind of owe me.\"","relearn":"Respecting a boundary earns no credit toward a future yes.","myth":{"un":"Honouring a 'no' once builds up a yes you can cash in later.","re":"A past 'no' you respected owes you nothing now.","why":"Decency isn't a transaction that buys future consent."}},
  {"id":"mt-1004","cat":"pressure-coercion","type":"strike-rewrite","persona":"Counsellor","source":"reported-doubt","hook":"\"They waited before telling anyone, so maybe it wasn't that serious.\"","relearn":"There's no 'right' time to disclose; a delay never makes harm the survivor's fault.","myth":{"un":"If someone waits to tell, the harm probably wasn't real.","re":"People disclose in their own time; a delay never blames the survivor.","why":"Doubting a delayed disclosure shifts blame off the wrongdoer."}},
  {"id":"mt-1005","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"keep-the-peace","hook":"\"It's easier to just say yes and avoid a fight.\"","relearn":"A yes given only to dodge conflict is pressure-driven, not free.","myth":{"un":"Saying yes to avoid an argument is just keeping the peace.","re":"A yes to avoid a fight isn't free; the fight-threat is the pressure.","why":"Fear of conflict removes the freely-given part."}},
  {"id":"mt-1006","cat":"pressure-coercion","type":"strike-rewrite","persona":"Arjun","source":"out-me","hook":"\"They hinted they'd out me to my family unless I agreed.\"","relearn":"Threatening to expose someone is blackmail; any yes under it isn't consent.","myth":{"un":"Agreeing so a secret stays safe is just a fair trade.","re":"An 'agree or I'll tell' threat is blackmail; that yes isn't consent.","why":"Blackmail removes every freely-given part of a choice."}},
  {"id":"mt-1007","cat":"pressure-coercion","type":"strike-rewrite","persona":"any","source":"i-paid-data","hook":"\"After all the gifts and recharges, surely they should say yes by now.\"","relearn":"Spending on someone buys nothing; intimacy is never a return on a gift.","myth":{"un":"Enough gifts and favours eventually earn a yes.","re":"Money spent earns no yes; intimacy is never owed in return.","why":"Treating a yes as 'earned' erases free choice."}},
  {"id":"mt-1008","cat":"pressure-coercion","type":"branch","persona":"any","source":"repeated-push","hook":"A partner keeps asking after you've clearly said you're not ready tonight.","options":[{"text":"Say 'I've answered, and asking again won't change it'","consequence":"You hold your boundary and the pushing stays their problem.","outcome":"firm","best":true},{"text":"Give a vague 'maybe later' to make them stop","consequence":"A vague maybe invites more pushing; a clear no is fairer to you."}],"debrief":"Re-asking past a clear no is pressure; a firm 'I've answered' holds the line.","relearn":"Hold your no; re-asking past it is the other person's problem."},
  {"id":"mt-1009","cat":"pressure-coercion","type":"branch","persona":"Vijay","source":"self-check-keen","hook":"You're keen but your partner seems quieter than usual and a bit unsure.","options":[{"text":"Pause and ask how they're really feeling, no agenda","consequence":"You read the cue and keep it mutual.","outcome":"checks-in","best":true},{"text":"Keep going since they haven't actually said stop","consequence":"No clear yes means stop; 'they didn't say no' isn't consent."}],"debrief":"When enthusiasm dips, the move is to pause and check, not push on.","relearn":"If a partner seems unsure, pause and check; don't push on."},
  {"id":"mt-1009b","cat":"pressure-coercion","type":"branch","persona":"any","source":"guilt-trip-live","hook":"Mid-conversation a partner sighs, 'I guess you don't really care about us then.'","options":[{"text":"Name it: 'That's a guilt-trip, and my answer's still the same'","consequence":"You see the tactic clearly and keep your choice.","outcome":"names-it","best":true},{"text":"Cave so they stop feeling hurt","consequence":"Caving to guilt isn't a free yes; their feelings are theirs to hold."}],"debrief":"Naming a guilt-trip out loud strips its power; your no still stands.","relearn":"Name a guilt-trip out loud; it loses its grip when you do."},
  {"id":"mt-1010","cat":"pressure-coercion","type":"branch","persona":"Counsellor","source":"disclose-route","hook":"A classmate quietly tells you a partner forced them and begs you to keep it secret.","options":[{"text":"Believe them, say it wasn't their fault, and offer Childline 1098 together","consequence":"They feel believed and have a real route to help.","outcome":"routes-help","best":true},{"text":"Tell them to just move on and forget it","consequence":"Disclosure needs support, not silence; route them to real help."}],"debrief":"A disclosure of force routes to help: believe them, no blame, Childline 1098.","relearn":"Believe a disclosure, never blame them, and route to real help."},
  {"id":"mt-1011","cat":"pressure-coercion","type":"branch","persona":"any","source":"threat-photo","hook":"Someone threatens to share an old private photo unless you agree to meet them.","options":[{"text":"Refuse, save the messages, and tell a trusted adult","consequence":"You name the blackmail and aren't facing it alone.","outcome":"safe","best":true},{"text":"Agree once so they delete it","consequence":"Giving in feeds blackmail; refuse and tell someone you trust."}],"debrief":"Threatening to share a photo is blackmail; refuse and tell a trusted adult.","relearn":"Photo threats are blackmail; refuse and tell someone you trust."},
  {"id":"mt-1012","cat":"pressure-coercion","type":"branch","persona":"Arjun","source":"own-pushing","hook":"You notice you keep nudging a hesitant partner with 'come on, don't overthink it'.","options":[{"text":"Stop, and tell them there's zero rush from you","consequence":"You set an equal-respect tone and stay trustworthy.","outcome":"accountable","best":true},{"text":"Keep nudging since they'll probably relax","consequence":"Nudging a hesitant partner is pressure; ease off and let it be their call."}],"debrief":"Being even-handed means catching your own nudging and stopping it.","relearn":"Catch your own nudging; tell a hesitant partner there's no rush."},
  {"id":"mt-1013","cat":"pressure-coercion","type":"branch","persona":"any","source":"friend-pressured","hook":"A friend says their partner sulks for days whenever they say no, so they just give in.","options":[{"text":"Remind them a yes to stop sulking isn't owed, and back them","consequence":"They feel supported and able to hold a no.","outcome":"supports","best":true},{"text":"Tell them every couple has to compromise on this","consequence":"Intimacy is never the compromise; sulking to get a yes is pressure."}],"debrief":"Sulking until someone gives in is coercion; a friend can name it and back them.","relearn":"Back a pressured friend: a yes to stop sulking is never owed."},
  {"id":"mt-1013b","cat":"pressure-coercion","type":"branch","persona":"any","source":"drunk-partner","hook":"At a party a partner who's quite drunk leans in and says 'let's go somewhere'.","options":[{"text":"Say not tonight, get them water, and wait till they're sober","consequence":"You protect them; a drunk yes isn't a real yes.","outcome":"waits","best":true},{"text":"Take the yes since they're the one asking","consequence":"Someone drunk can't truly consent; wait until they're sober."}],"debrief":"An incapacitated yes isn't consent; the caring move is to wait.","relearn":"A drunk 'yes' isn't consent; wait until they're sober."},
  {"id":"mt-1014","cat":"pressure-coercion","type":"branch","persona":"Sneha","source":"ultimatum","hook":"A partner says 'either you do or we're done'.","options":[{"text":"Recognise the ultimatum and let them walk if they must","consequence":"You keep your boundary; the ultimatum is their red flag.","outcome":"firm","best":true},{"text":"Agree to save the relationship","consequence":"A yes to save the relationship isn't free; the ultimatum is on them."}],"debrief":"'Do it or we're done' is an ultimatum, not love; a yes under it isn't free.","relearn":"An ultimatum isn't love; a yes given under it isn't free."},
  {"id":"mt-1015","cat":"pressure-coercion","type":"branch","persona":"any","source":"wears-you-down","hook":"After an hour of 'please, please' you feel too tired to keep saying no.","options":[{"text":"Say 'me being worn out isn't a yes' and step away","consequence":"You name the tactic and protect your real answer.","outcome":"names-it","best":true},{"text":"Mumble 'fine' just to end it","consequence":"A worn-down 'fine' isn't consent; the hour of pushing is the problem."}],"debrief":"Being worn down until you cave is coercion; a tired 'fine' isn't a yes.","relearn":"Being worn down isn't a yes; name it and step away."},
  {"id":"mt-1016","cat":"pressure-coercion","type":"branch","persona":"any","source":"online-pressure","hook":"A person you chat with online keeps pushing for a video call you don't want.","options":[{"text":"Say a clear no once, then mute or block if it continues","consequence":"You hold the boundary without owing an explanation.","outcome":"safe","best":true},{"text":"Keep explaining why, hoping they'll finally accept it","consequence":"You owe no explanation; repeated pushing online is still pressure."}],"debrief":"Online pushing is still pressure; a clear no plus block is enough.","relearn":"A clear no online is enough; block if pushing continues."},
  {"id":"mt-1017","cat":"pressure-coercion","type":"branch","persona":"any","source":"after-yes-changed","hook":"You said yes earlier, but now you've changed your mind and want to stop.","options":[{"text":"Say 'I've changed my mind, let's stop' with no apology owed","consequence":"You use your right to stop; an earlier yes isn't ongoing.","outcome":"stops","best":true},{"text":"Carry on because you already agreed","consequence":"An earlier yes isn't binding; you can stop the moment you want to."}],"debrief":"An earlier yes isn't an ongoing yes; you can stop anytime, no apology owed.","relearn":"You can withdraw a yes anytime; an earlier yes isn't ongoing."},
  {"id":"mt-1018","cat":"pressure-coercion","type":"spot","persona":"any","source":"spot pressure lines","hook":"Spot the two lines that pressure, not respect.","scene":[{"id":"a","text":"\"Only if you actually want to\"","trick":false},{"id":"b","text":"\"Come on, don't be boring\"","trick":true},{"id":"c","text":"\"We can stop whenever you like\"","trick":false},{"id":"d","text":"\"You'll regret it if you don't\"","trick":true},{"id":"e","text":"\"No rush at all\"","trick":false}],"why":"'Don't be boring' and 'you'll regret it' are pressure; the rest leave you free.","relearn":"Spot pressure lines; respectful ones always leave the choice with you."},
  {"id":"mt-1019","cat":"pressure-coercion","type":"spot","persona":"any","source":"spot what cancels a yes","hook":"Spot the two things that make a 'yes' not count.","scene":[{"id":"a","text":"A relaxed, willing yes","trick":false},{"id":"b","text":"A yes given after a threat","trick":true},{"id":"c","text":"A yes you can take back anytime","trick":false},{"id":"d","text":"A 'yes' from someone too drunk to think","trick":true},{"id":"e","text":"A clear yes you both checked","trick":false}],"why":"Threats and being too drunk both cancel a yes; the others are real consent.","relearn":"Threats or incapacitation cancel a yes; a free, checked yes stands."},
  {"id":"mt-1020","cat":"pressure-coercion","type":"spot","persona":"Sneha","source":"spot guilt tactics","hook":"Spot the two guilt-trips hiding here.","scene":[{"id":"a","text":"\"If you loved me, you would\"","trick":true},{"id":"b","text":"\"Take all the time you need\"","trick":false},{"id":"c","text":"\"I'll be so hurt if you say no\"","trick":true},{"id":"d","text":"\"Your answer is totally fine\"","trick":false},{"id":"e","text":"\"Whatever you're comfy with\"","trick":false}],"why":"'If you loved me' and 'I'll be hurt' weaponise guilt; the rest respect your no.","relearn":"Spot guilt-trips; respect sounds like 'whatever you're comfortable with'."},
  {"id":"mt-1021","cat":"pressure-coercion","type":"spot","persona":"any","source":"spot the entitlement","hook":"Spot the two 'you owe me' lines.","scene":[{"id":"a","text":"\"I paid, so you should\"","trick":true},{"id":"b","text":"\"There's no pressure from me\"","trick":false},{"id":"c","text":"\"We're together, so it's expected\"","trick":true},{"id":"d","text":"\"It's completely your call\"","trick":false},{"id":"e","text":"\"Only if you're keen too\"","trick":false}],"why":"'I paid' and 'we're together so it's expected' assume a yes you never owe.","relearn":"Spot entitlement; nobody is owed intimacy for money or a relationship."},
  {"id":"mt-1022","cat":"pressure-coercion","type":"spot","persona":"Arjun","source":"spot the coercion","hook":"Spot the two coercive moves in this chat.","scene":[{"id":"a","text":"Asking once, then accepting the no","trick":false},{"id":"b","text":"Threatening to out them unless they agree","trick":true},{"id":"c","text":"Saying 'no worries' and changing the subject","trick":false},{"id":"d","text":"Repeating the ask till they're worn out","trick":true},{"id":"e","text":"Checking they're still comfortable","trick":false}],"why":"Outing-threats and wearing someone down are coercion; the rest respect a no.","relearn":"Spot coercion; respect means accepting a no the first time."},
  {"id":"mt-1023","cat":"pressure-coercion","type":"spot","persona":"any","source":"spot the red flags","hook":"Spot the two red flags in how they react to 'no'.","scene":[{"id":"a","text":"They say 'thanks for telling me'","trick":false},{"id":"b","text":"They sulk and ignore you for days","trick":true},{"id":"c","text":"They check in again later, kindly","trick":false},{"id":"d","text":"They say 'fine, but you'll be sorry'","trick":true},{"id":"e","text":"They drop it and move on","trick":false}],"why":"Sulking to punish and 'you'll be sorry' are red flags; the rest honour the no.","relearn":"Spot red flags; a healthy reaction to 'no' is to accept it warmly."},
  {"id":"mt-1024","cat":"pressure-coercion","type":"role-play","persona":"any","source":"refuse a threat","hook":"Refuse a threat in your own words.","setup":"Someone says they'll spread rumours unless you agree. Say:","yourLine":[{"text":"\"That's a threat, and threats don't get a yes from me.\"","best":true},{"text":"\"...okay, please don't, I'll do it.\""}],"relearn":"You can name a threat and refuse it flat out."},
  {"id":"mt-1025","cat":"pressure-coercion","type":"role-play","persona":"Sneha","source":"refuse guilt","hook":"Refuse a 'you owe me' guilt-trip.","setup":"A partner sighs 'after everything I do for you...'. Say:","yourLine":[{"text":"\"What you do for me isn't a bill, and my answer's still no.\"","best":true},{"text":"\"...fine, I don't want you upset.\""}],"relearn":"Favours aren't a debt; you can keep your no."},
  {"id":"mt-1026","cat":"pressure-coercion","type":"role-play","persona":"any","source":"stop midway","hook":"Say you want to stop, partway through.","setup":"You've changed your mind partway through. Say:","yourLine":[{"text":"\"I want to stop now, and that's okay to do.\"","best":true},{"text":"Stay quiet and just wait for it to be over"}],"relearn":"You can stop at any point; an earlier yes isn't ongoing."},
  {"id":"mt-1027","cat":"pressure-coercion","type":"role-play","persona":"Vijay","source":"name persistence","hook":"Name relentless asking as pressure.","setup":"They keep asking after a no. Name it. Say:","yourLine":[{"text":"\"Asking again and again isn't romantic, it's pressure. Still no.\"","best":true},{"text":"\"Maybe if you ask later...\""}],"relearn":"Naming 'persistence' as pressure takes its power away."},
  {"id":"mt-1028","cat":"pressure-coercion","type":"role-play","persona":"any","source":"refuse a gift-debt","hook":"Turn down a 'you owe me' gift line.","setup":"They say 'I spent so much on you tonight'. Say:","yourLine":[{"text":"\"Thank you, but a gift isn't something I owe you back.\"","best":true},{"text":"\"I guess I owe you then...\""}],"relearn":"A gift is a gift; you never owe intimacy in return."},
  {"id":"mt-1029","cat":"pressure-coercion","type":"role-play","persona":"Arjun","source":"decline outing-threat","hook":"Refuse an outing-threat and get help.","setup":"Someone hints they'll out you unless you agree. Say:","yourLine":[{"text":"\"That's blackmail. I'm not agreeing, and I'm telling someone.\"","best":true},{"text":"\"Please don't tell, I'll do whatever you want.\""}],"relearn":"Blackmail gets a refusal and a trusted person told."},
  {"id":"mt-1030","cat":"pressure-coercion","type":"reflect","persona":"any","source":"even-handed","hook":"Lensy: anyone, any gender, can be the one pressured or the one pressuring. Sit with that?","prompt":"What do you think?","options":["Yes","It cuts both ways","Good to remember"],"affirm":"Coercion isn't about gender; holding both keeps everyone safer. 💞","relearn":"Coercion isn't about gender; holding both keeps everyone safer."},
  {"id":"mt-1031","cat":"pressure-coercion","type":"reflect","persona":"any","source":"naming-defuses","hook":"Lensy: once you can name guilt, threats and 'persistence', they lose their grip. Feel that?","prompt":"What do you think?","options":["Yes","Naming helps","I can spot them now"],"affirm":"Named out loud, a coercion tactic stops working on you. 💞","relearn":"Named out loud, a coercion tactic stops working on you."},
  {"id":"mt-1032","cat":"pressure-coercion","type":"reflect","persona":"any","source":"never-your-fault","hook":"Lensy: if someone is worn down into a yes, the harm is on the one who pushed. True for you?","prompt":"What do you think?","options":["Yes","Never their fault","On the one who pushed"],"affirm":"Giving in under pressure is never your fault; it's on whoever ignored your no. 💞","relearn":"Giving in under pressure is never your fault; it's on whoever ignored your no."},
  {"id":"mt-1033","cat":"pressure-coercion","type":"reflect","persona":"Sneha","source":"worth-not-owed","hook":"Lensy: your worth in a relationship never depends on saying yes to intimacy. Sit with it?","prompt":"What do you think?","options":["Yes","I'm not owed-out","My worth isn't that"],"affirm":"You're never 'less' for holding a no; your worth isn't up for trade. 💞","relearn":"You're never 'less' for holding a no; your worth isn't up for trade."},
  {"id":"mt-1034","cat":"pressure-coercion","type":"reflect","persona":"any","source":"no-is-complete","hook":"Lensy: 'no' is a full sentence, no reasons owed. Does that land?","prompt":"What do you think?","options":["Yes","No reasons owed","A full answer"],"affirm":"A no needs no explanation; 'no, and that's enough' is complete. 💞","relearn":"A no needs no explanation; 'no, and that's enough' is complete."},
  {"id":"mt-1035","cat":"pressure-coercion","type":"reflect","persona":"any","source":"tired-yes","hook":"Lensy: a yes given just to end the pestering isn't really a yes. Recognise that?","prompt":"What do you think?","options":["Yes","Not a real yes","That's pressure"],"affirm":"A worn-out 'fine' isn't consent; the pestering is the problem, not you. 💞","relearn":"A worn-out 'fine' isn't consent; the pestering is the problem, not you."},
  {"id":"mt-1036","cat":"pressure-coercion","type":"sort","persona":"any","source":"free-vs-coerced","hook":"Sort: a free yes, or pressure?","items":[{"id":"a","text":"A relaxed, willing yes"},{"id":"b","text":"A yes after an hour of 'please'"},{"id":"c","text":"Both genuinely keen"},{"id":"d","text":"A yes to stop them sulking"},{"id":"e","text":"A yes you can take back anytime"},{"id":"f","text":"A yes given under a threat"}],"bins":[{"id":"free","label":"Free yes","valence":"pos"},{"id":"coerced","label":"Pressure","valence":"neg"}],"key":{"a":"free","b":"coerced","c":"free","d":"coerced","e":"free","f":"coerced"},"relearn":"Relaxed, mutual, reversible yeses are free; guilt, sulking or threats make it pressure."},
  {"id":"mt-1037","cat":"pressure-coercion","type":"sort","persona":"any","source":"tactic-vs-respect","hook":"Sort: a coercion tactic, or respect?","items":[{"id":"a","text":"\"If you loved me, you would\""},{"id":"b","text":"\"Only if you want to\""},{"id":"c","text":"\"Everyone does it\""},{"id":"d","text":"\"We can stop anytime\""},{"id":"e","text":"\"You'll regret saying no\""},{"id":"f","text":"\"No rush at all\""}],"bins":[{"id":"tactic","label":"Coercion tactic","valence":"neg"},{"id":"respect","label":"Respect","valence":"pos"}],"key":{"a":"tactic","b":"respect","c":"tactic","d":"respect","e":"tactic","f":"respect"},"relearn":"Guilt, peer pressure and 'you'll regret it' are tactics; respect leaves the choice with you."},
  {"id":"mt-1038","cat":"pressure-coercion","type":"sort","persona":"any","source":"yours-vs-theirs","hook":"Sort: whose job is it when 'no' is said?","items":[{"id":"a","text":"Accept the no the first time"},{"id":"b","text":"Keep your own boundary"},{"id":"c","text":"Don't sulk or punish"},{"id":"d","text":"Not over-explain your no"},{"id":"e","text":"Drop the topic"},{"id":"f","text":"Trust your own answer"}],"bins":[{"id":"yours","label":"Your part","valence":"pos"},{"id":"theirs","label":"Their part","valence":"pos"}],"key":{"a":"theirs","b":"yours","c":"theirs","d":"yours","e":"theirs","f":"yours"},"relearn":"You hold your boundary; they accept it without sulking. Both have a clear part."},
  {"id":"mt-1039","cat":"pressure-coercion","type":"sort","persona":"any","source":"valid-or-not","hook":"Sort: does this 'yes' count?","items":[{"id":"a","text":"A clear, willing yes"},{"id":"b","text":"A yes while very drunk"},{"id":"c","text":"A checked-in, happy yes"},{"id":"d","text":"A yes given under blackmail"},{"id":"e","text":"An enthusiastic yes"},{"id":"f","text":"A yes from someone half-asleep"}],"bins":[{"id":"counts","label":"Real yes","valence":"pos"},{"id":"void","label":"Not a yes","valence":"neg"}],"key":{"a":"counts","b":"void","c":"counts","d":"void","e":"counts","f":"void"},"relearn":"Willing, sober, checked yeses count; drink, blackmail or being half-asleep void it."},
  {"id":"mt-1040","cat":"pressure-coercion","type":"sort","persona":"any","source":"green-vs-red","hook":"Sort: green flag, or red flag?","items":[{"id":"a","text":"\"Tell me to stop anytime\""},{"id":"b","text":"\"Do it or we're over\""},{"id":"c","text":"\"Whatever you're comfy with\""},{"id":"d","text":"Sulking for days after a no"},{"id":"e","text":"Checking in midway"},{"id":"f","text":"Guilt-tripping for a yes"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Checking in and honouring a no are green; ultimatums, sulking and guilt are red."},
  {"id":"mt-1041","cat":"pressure-coercion","type":"sort","persona":"Counsellor","source":"speak-or-not","hook":"Sort: speak up, or your own call?","items":[{"id":"a","text":"A partner threatening to out you"},{"id":"b","text":"Choosing to wait till you're ready"},{"id":"c","text":"Being blackmailed for a photo"},{"id":"d","text":"Saying no without a reason"},{"id":"e","text":"Someone forcing a friend"},{"id":"f","text":"Pausing to check your own feelings"}],"bins":[{"id":"tell","label":"Tell someone","valence":"tell"},{"id":"own","label":"Your own call","valence":"neutral"}],"key":{"a":"tell","b":"own","c":"tell","d":"own","e":"tell","f":"own"},"relearn":"Threats, blackmail and force are things to tell a trusted adult about; your own pace is yours."},
  {"id":"mt-1042","cat":"pressure-coercion","type":"sort","persona":"any","source":"owes-or-not","hook":"Sort: does this create a debt of intimacy?","items":[{"id":"a","text":"They bought you dinner"},{"id":"b","text":"Nothing: it's always free"},{"id":"c","text":"You've been together months"},{"id":"d","text":"Intimacy is never owed"},{"id":"e","text":"They gave you a gift"},{"id":"f","text":"Only your real yes counts"}],"bins":[{"id":"no-debt","label":"Owes nothing","valence":"pos"},{"id":"free-truth","label":"Always free","valence":"pos"}],"key":{"a":"no-debt","b":"free-truth","c":"no-debt","d":"free-truth","e":"no-debt","f":"free-truth"},"relearn":"Gifts, dates and time owe you nothing; intimacy is always a free yes, never a debt."},
  {"id":"mt-1043","cat":"pressure-coercion","type":"match","persona":"any","source":"tactic-names","hook":"Match each pressure line to what it really is.","pairs":[{"left":"\"If you loved me, you would\"","right":"Guilt-trip"},{"left":"\"Everyone our age does it\"","right":"Peer pressure"},{"left":"\"Agree or I'll tell everyone\"","right":"Blackmail"},{"left":"\"You'll regret saying no\"","right":"A threat"},{"left":"Asking over and over till you cave","right":"Wearing you down"}],"relearn":"Name each tactic: guilt, peer pressure, blackmail, threats, wearing-down."},
  {"id":"mt-1044","cat":"pressure-coercion","type":"match","persona":"any","source":"refuse-lines","hook":"Match each pressure to a clean refusal.","pairs":[{"left":"A guilt-trip","right":"\"That's guilt, and my answer's still no\""},{"left":"A gift used as a debt","right":"\"A gift isn't something I owe back\""},{"left":"Relentless asking","right":"\"Asking again won't change my no\""},{"left":"A threat","right":"\"Threats don't get a yes from me\""},{"left":"Changed mind midway","right":"\"I want to stop now, and that's okay\""}],"relearn":"Every pressure has a clean, short refusal you're allowed to use."},
  {"id":"mt-1045","cat":"pressure-coercion","type":"match","persona":"Counsellor","source":"route-help","hook":"Match each situation to the right help route.","pairs":[{"left":"Anyone under 18 in danger","right":"Childline 1098"},{"left":"A woman facing pressure or abuse","right":"Women Helpline 181"},{"left":"An emergency happening now","right":"Emergency 112"},{"left":"A woman in distress, another line","right":"Women line 1091"},{"left":"Someone you trust, nearby","right":"A trusted adult"}],"relearn":"Disclosures route to real help: 1098, 181, 112, 1091, a trusted adult."},
  {"id":"mt-1046","cat":"pressure-coercion","type":"match","persona":"any","source":"green-red","hook":"Match each move to what it shows.","pairs":[{"left":"Checking in midway","right":"Green flag"},{"left":"Sulking after a no","right":"Red flag"},{"left":"Accepting a no the first time","right":"Honours the boundary"},{"left":"A 'do it or we're done' line","right":"An ultimatum"},{"left":"Saying 'no rush at all'","right":"Leaves you free"}],"relearn":"Green flags honour a no; red flags sulk, ultimatum, or push."},
  {"id":"mt-1047","cat":"pressure-coercion","type":"match","persona":"any","source":"fries-pressure","hook":"Match each pressure to the FRIES part it breaks.","pairs":[{"left":"A yes given under a threat","right":"Breaks 'freely given'"},{"left":"\"You already said yes once\"","right":"Breaks 'ongoing'"},{"left":"A 'yes' while drunk","right":"Breaks 'informed'"},{"left":"Going along with no real want","right":"Breaks 'enthusiastic'"},{"left":"\"Yes to this means yes to all\"","right":"Breaks 'specific'"}],"relearn":"Each kind of pressure breaks a part of a freely-given FRIES yes."},
  {"id":"mt-1048","cat":"pressure-coercion","type":"match","persona":"any","source":"whose-fault","hook":"Match each case to where the responsibility sits.","pairs":[{"left":"Someone worn down into a yes","right":"On the one who pushed"},{"left":"A boundary honoured kindly","right":"A shared, mutual moment"},{"left":"A yes taken from a drunk partner","right":"On the one who ignored consent"},{"left":"Believing a friend's disclosure","right":"The supportive response"},{"left":"A delayed disclosure","right":"Still never the survivor's fault"}],"relearn":"Harm is always on whoever ignored consent, never the survivor."},
  {"id":"mt-1049","cat":"pressure-coercion","type":"match","persona":"Sneha","source":"myth-truth","hook":"Match each pressure myth to the truth.","pairs":[{"left":"\"Persistence is romantic\"","right":"Wearing someone down is coercion"},{"left":"\"A partner owes you\"","right":"No one ever owes intimacy"},{"left":"\"Silence means yes\"","right":"Only a clear yes means yes"},{"left":"\"A gift earns a yes\"","right":"A gift is never a debt"},{"left":"\"You can't stop now\"","right":"You can stop at any point"}],"relearn":"Each pressure myth has a plain truth that cancels it."},
  {"id":"mt-1050","cat":"pressure-coercion","type":"match","persona":"any","source":"cue-response","hook":"Match each cue to the caring response.","pairs":[{"left":"A partner goes quiet","right":"Pause and check in"},{"left":"They say 'I'm not sure'","right":"Treat it as a no-for-now"},{"left":"They pull away","right":"Stop and give space"},{"left":"They say a clear 'no'","right":"Accept it the first time"},{"left":"They seem genuinely keen","right":"Stay checked-in and mutual"}],"relearn":"Read each cue and answer it with care: pause, stop, or stay mutual."},
  {"id":"mt-1080","cat":"reading-respecting","type":"spot","hook":"You're on a video call. Spot the two cues that mean stop and check in.","scene":[{"id":"a","text":"They keep glancing at the door, fidgeting","trick":true},{"id":"b","text":"They smile and say 'I'm so glad we're talking'","trick":false},{"id":"c","text":"One-word replies and a fixed, tight face","trick":true},{"id":"d","text":"They laugh easily and lean toward the camera","trick":false},{"id":"e","text":"They suggest the next thing themselves","trick":false}],"why":"Fidgeting toward the door and tight one-word replies signal discomfort: pause and ask.","relearn":"Non-verbal discomfort counts as much as words: pause and check in.","persona":"any","source":"reading cues"},
  {"id":"mt-1081","cat":"reading-respecting","type":"spot","hook":"At a friend's party. Spot the two moments that mean stop and ask.","scene":[{"id":"a","text":"They step back and cross their arms","trick":true},{"id":"b","text":"They hold your gaze and step closer","trick":false},{"id":"c","text":"A quiet 'maybe we shouldn't here'","trick":true},{"id":"d","text":"They say clearly, 'I'd love to'","trick":false},{"id":"e","text":"They take your hand without being asked","trick":false}],"why":"Stepping back, crossing arms, and 'maybe we shouldn't' mean stop and check in. Stepping closer, a clear 'I'd love to', and taking your hand are willingness.","relearn":"A reluctant 'maybe we shouldn't' means stop and check, not push.","persona":"any","source":"reading cues"},
  {"id":"mt-1082","cat":"reading-respecting","type":"spot","hook":"Spot the two texts that are NOT a clear, willing yes.","scene":[{"id":"a","text":"'idk maybe, if you really want'","trick":true},{"id":"b","text":"'yes! I've been wanting to'","trick":false},{"id":"c","text":"'…k.' after a long pause","trick":true},{"id":"d","text":"'absolutely, let's do it'","trick":false},{"id":"e","text":"'I'm in, this sounds great'","trick":false}],"why":"'if you really want' and a flat '…k.' are going-along, not a yes. Check in. The eager replies are real enthusiasm.","relearn":"A reluctant 'if you want' or a flat 'k' is not an enthusiastic yes.","persona":"any","source":"reading cues"},
  {"id":"mt-1083","cat":"reading-respecting","type":"spot","hook":"Spot the two things that quietly ignore a partner's cue.","scene":[{"id":"a","text":"Carrying on after they went silent","trick":true},{"id":"b","text":"Pausing the moment they tense up","trick":false},{"id":"c","text":"'You always do this' when they hesitate","trick":true},{"id":"d","text":"Asking 'you still good?' softly","trick":false},{"id":"e","text":"Slowing down when they look unsure","trick":false}],"why":"Carrying on through silence and guilt-tripping a hesitation ignore the cue. Pausing, asking, and slowing down read and respect it.","relearn":"Ignoring silence or guilting a hesitation overrides a real cue.","persona":"any","source":"respect"},
  {"id":"mt-1084","cat":"reading-respecting","type":"spot","hook":"Spot the two replies that pressure instead of respecting a 'not now'.","scene":[{"id":"a","text":"'Come on, just this once'","trick":true},{"id":"b","text":"'Okay, no worries at all'","trick":false},{"id":"c","text":"'Fine, but you're no fun'","trick":true},{"id":"d","text":"'Thanks for telling me'","trick":false},{"id":"e","text":"'We can just hang out then'","trick":false}],"why":"'Just this once' and 'you're no fun' push past the boundary. 'No worries', 'thanks for telling me', and 'let's just hang out' honour it.","relearn":"'Just this once' or sulking pressures a 'no' instead of honouring it.","persona":"any","source":"respect boundary"},
  {"id":"mt-1143","cat":"reading-respecting","type":"spot","hook":"During a close hug. Spot the two cues that mean ease off and check.","scene":[{"id":"a","text":"They go rigid and hold their breath","trick":true},{"id":"b","text":"They melt in and hug back warmly","trick":false},{"id":"c","text":"They give a quick pat that says 'okay, done'","trick":true},{"id":"d","text":"They sigh, relaxed, and stay close","trick":false},{"id":"e","text":"They murmur 'I needed this'","trick":false}],"why":"Going rigid and a quick 'done' pat mean ease off and check. Melting in, relaxing, and 'I needed this' are real ease.","relearn":"A stiffening body or a quick 'done' pat is a cue: ease off and check.","persona":"any","source":"reading cues"},
  {"id":"mt-1085","cat":"reading-respecting","type":"branch","hook":"They said yes earlier, but now they've gone quiet and tense.","options":[{"text":"Pause and gently ask if they still want to","consequence":"You catch the shift and give room to answer honestly.","outcome":"attuned","best":true},{"text":"Carry on: they already said yes","consequence":"An earlier yes isn't ongoing; a shift means pause and check."},{"text":"Ask why they're 'being weird'","consequence":"Blaming their cue shuts them down, not checks in."}],"debrief":"Willingness can change; a tense shift means pause and check.","relearn":"An earlier yes isn't ongoing. A tense shift means pause and check.","persona":"Vijay","source":"checking in"},
  {"id":"mt-1086","cat":"reading-respecting","type":"branch","hook":"Your partner laughs nervously and changes the subject when you lean in.","options":[{"text":"Ease off and ask if they're okay","consequence":"You read the deflection as a soft no and make it safe.","outcome":"reads-cue","best":true},{"text":"Lean in again: they're just shy","consequence":"Deflecting is a cue; 'shy' overrides it. Ask instead."},{"text":"Go quiet and act hurt","consequence":"Sulking pressures them; reading the cue means easing off."}],"debrief":"Nervous deflection is a cue: ease off and check, don't assume.","relearn":"A nervous laugh or topic-change can be a soft no: ease off and ask.","persona":"any","source":"reading cues"},
  {"id":"mt-1087","cat":"reading-respecting","type":"branch","hook":"You're unsure if they're into it or just being polite.","options":[{"text":"Ask plainly: 'Do you want this, or just being nice?'","consequence":"You invite an honest answer instead of guessing.","outcome":"checks-in","best":true},{"text":"Decide they're keen and keep going","consequence":"If unsure, ask: never read 'polite' as a real yes."},{"text":"Wait for them to object if they mind","consequence":"Absence of a 'no' isn't a yes; check for a real one."}],"debrief":"When unsure, ask for a real yes, not polite going-along.","relearn":"If you're unsure, pause and check in, never assume.","persona":"Arjun","source":"checking in"},
  {"id":"mt-1088","cat":"reading-respecting","type":"branch","hook":"They pull their hand back while you're holding it.","options":[{"text":"Let go at once and give them space","consequence":"You honour the boundary the instant you read it.","outcome":"respect","best":true},{"text":"Hold on a moment longer to be sure","consequence":"Pulling away is already clear; honour it immediately."},{"text":"Ask 'what's wrong with you?'","consequence":"That blames their cue; respecting it means letting go calmly."}],"debrief":"Pulling away is a clear cue: honour it the moment you feel it.","relearn":"Pulling away is a boundary: honour it immediately, no delay.","persona":"any","source":"respect boundary"},
  {"id":"mt-1089","cat":"reading-respecting","type":"branch","hook":"Mid-moment they say, 'Can we just slow down?'","options":[{"text":"Slow right down: 'Of course. Tell me what feels okay'","consequence":"You follow their pace and keep it mutual.","outcome":"attuned","best":true},{"text":"Slow for a second, then pick back up","consequence":"'Slow down' isn't 'in a minute'; follow their pace, not yours."},{"text":"Ask them to explain why first","consequence":"They owe no reason; honour 'slow down' without a debate."}],"debrief":"'Slow down' is honoured now and on their terms, no bargaining.","relearn":"'Slow down' is honoured immediately, on their pace, no reason owed.","persona":"any","source":"respect"},
  {"id":"mt-1090","cat":"reading-respecting","type":"branch","hook":"You notice your partner seems distracted and far away.","options":[{"text":"Stop and check: 'You seem far away, want to pause?'","consequence":"You name what you read and offer an easy out.","outcome":"reads-cue","best":true},{"text":"Try harder to get them in the mood","consequence":"Distracted isn't a yes; pushing ignores it. Pause and ask."},{"text":"Assume they're just tired and continue","consequence":"Don't guess it away: check what's actually going on."}],"debrief":"Distance is a cue worth naming: pause and offer an out.","relearn":"Distraction or distance isn't a yes: pause and check in gently.","persona":"any","source":"reading cues"},
  {"id":"mt-1091","cat":"reading-respecting","type":"branch","hook":"They said 'not tonight'. Part of you wants to ask again.","options":[{"text":"Drop it warmly and plan something else","consequence":"You honour the no and keep closeness easy.","outcome":"respect","best":true},{"text":"Ask once more in case they change","consequence":"Re-asking a clear 'not tonight' is pressure."},{"text":"Go cold for the evening","consequence":"Withdrawing punishes the no; let it stand."}],"debrief":"A clear 'not tonight' is honoured once, no re-asking, no sulking.","relearn":"Honour 'not tonight' the first time: re-asking is pressure.","persona":"any","source":"respect boundary"},
  {"id":"mt-1092","cat":"reading-respecting","type":"branch","hook":"They flinch slightly when you move closer.","options":[{"text":"Ease back and ask, 'Is this okay?'","consequence":"You catch the flinch and check before anything else.","outcome":"attuned","best":true},{"text":"Pretend you didn't notice and continue","consequence":"A flinch is a real cue; ignoring it overrides their comfort."},{"text":"Tell them they're 'overthinking it'","consequence":"That dismisses their body's no; honour it and check in."}],"debrief":"A flinch is the body saying wait: ease back and ask.","relearn":"A flinch is a real cue: ease back and check before moving closer.","persona":"any","source":"reading cues"},
  {"id":"mt-1093","cat":"reading-respecting","type":"branch","hook":"You both planned this, but tonight they seem hesitant.","options":[{"text":"Check in: 'Only if you still want to'","consequence":"You let the plan bend to how they feel now.","outcome":"checks-in","best":true},{"text":"Remind them you both agreed earlier","consequence":"A past plan isn't ongoing consent; now leads."},{"text":"Say you'll be 'so disappointed' otherwise","consequence":"Guilt is pressure; honour the hesitation instead."}],"debrief":"A plan never overrides how someone feels in the moment. Check in.","relearn":"A past plan isn't ongoing consent: honour today's hesitation.","persona":"Vijay","source":"checking in"},
  {"id":"mt-1094","cat":"reading-respecting","type":"branch","hook":"They say 'I'm okay' but their voice is flat and small.","options":[{"text":"Name it: 'You don't sound sure. We can stop'","consequence":"You trust the tone and make stopping easy.","outcome":"reads-cue","best":true},{"text":"Take the words at face value and go on","consequence":"A flat 'okay' can mask discomfort; check the tone."},{"text":"Ask them to 'just relax'","consequence":"That ignores the cue; offer a real out instead."}],"debrief":"When tone and words clash, trust the tone and check in.","relearn":"A flat 'I'm okay' can hide a no: trust the tone and offer a stop.","persona":"any","source":"reading cues"},
  {"id":"mt-1095","cat":"reading-respecting","type":"branch","hook":"Your partner goes still and stops responding mid-moment.","options":[{"text":"Stop and softly ask if they're alright","consequence":"You read the freeze as a stop and respond with care.","outcome":"attuned","best":true},{"text":"Keep going and hope they warm up","consequence":"Freezing is not a yes; stop and check, never wait it out."},{"text":"Ask why they 'always do this'","consequence":"Blaming the freeze shuts them down; meet it with care."}],"debrief":"Freezing means stop now: meet it with a calm, caring check-in.","relearn":"Going still and silent is not a yes: stop and check in calmly.","persona":"any","source":"reading cues"},
  {"id":"mt-1096","cat":"reading-respecting","type":"branch","hook":"They say yes, but won't meet your eyes and seem shrunken.","options":[{"text":"Pause: 'You can say no. I'd rather you be sure'","consequence":"You make 'no' safe so any yes is a real one.","outcome":"checks-in","best":true},{"text":"Accept the word 'yes' and move ahead","consequence":"A shrunken yes with no eye contact may not be free. Check."},{"text":"Tell them not to be 'so dramatic'","consequence":"That pressures them; reading cues means making no safe."}],"debrief":"A yes that looks small may not be free: make 'no' safe first.","relearn":"A shrunken 'yes' may not be free: make 'no' safe and re-check.","persona":"any","source":"checking in"},
  {"id":"mt-1097","cat":"reading-respecting","type":"branch","hook":"You read a cue wrong and your partner pulled back, upset.","options":[{"text":"Stop, own it simply, and ask what they need","consequence":"You repair with care and put them in control.","outcome":"repair","best":true},{"text":"Defend yourself: 'I thought you wanted to'","consequence":"Defending centres you; repair is stopping and listening."},{"text":"Act wounded so they comfort you","consequence":"Flipping it onto them isn't repair; check on them."}],"debrief":"Misreading happens: repair is stopping, owning it, and listening.","relearn":"If you misread a cue, stop, own it simply, and ask what they need.","persona":"Arjun","source":"repair"},
  {"id":"mt-1098","cat":"reading-respecting","type":"branch","hook":"They keep saying 'whatever you want' instead of what they want.","options":[{"text":"Slow down: 'I want to know what YOU want'","consequence":"You invite their real voice, not going-along.","outcome":"checks-in","best":true},{"text":"Take 'whatever you want' as a green light","consequence":"Deferring isn't enthusiasm; draw out a real yes."},{"text":"Decide for both of you to keep it simple","consequence":"Deciding for them removes their voice; ask first."}],"debrief":"'Whatever you want' isn't a yes: draw out their real preference.","relearn":"'Whatever you want' isn't enthusiasm: ask what they actually want.","persona":"Vijay","source":"checking in"},
  {"id":"mt-1099","cat":"reading-respecting","type":"branch","hook":"Their body is open and warm, and they say 'yes, definitely'.","options":[{"text":"Stay present and keep checking in","consequence":"You hold the yes as ongoing, not a one-time gate.","outcome":"attuned","best":true},{"text":"Treat that yes as settled all night","consequence":"Even a clear yes is ongoing; keep reading."},{"text":"Stop asking now they've said yes","consequence":"Dropping check-ins assumes nothing changes."}],"debrief":"Even an enthusiastic yes stays ongoing: keep reading and checking.","relearn":"A clear yes is still ongoing: keep reading cues and checking in.","persona":"any","source":"checking in"},
  {"id":"mt-1100","cat":"reading-respecting","type":"role-play","hook":"You want to check your partner is genuinely into it, not just going along.","setup":"Ask warmly and openly. Say:","yourLine":[{"text":"\"Are you into this, honestly? We can stop anytime.\"","best":true},{"text":"\"You're fine, right?\" (already moving on)"}],"relearn":"Ask for a real yes: 'we can stop anytime' makes honesty safe.","persona":"Vijay","source":"checking in"},
  {"id":"mt-1101","cat":"reading-respecting","type":"role-play","hook":"You sense your partner's mood shifted and want to name it kindly.","setup":"Name what you noticed, gently. Say:","yourLine":[{"text":"\"You got quiet, want to pause for a bit?\"","best":true},{"text":"Ignore it and keep going"}],"relearn":"Naming a cue softly, 'you got quiet, want to pause?' is caring.","persona":"any","source":"reading cues"},
  {"id":"mt-1102","cat":"reading-respecting","type":"role-play","hook":"You realise you misread a cue and your partner stiffened.","setup":"Repair it simply, no excuses. Say:","yourLine":[{"text":"\"Sorry, I misread that. Let's stop. You okay?\"","best":true},{"text":"\"You should've said something\""}],"relearn":"Repair is simple: 'I misread that, let's stop, you okay?' No blame.","persona":"Arjun","source":"repair"},
  {"id":"mt-1103","cat":"reading-respecting","type":"role-play","hook":"Your partner asks 'is this okay?' and you're genuinely unsure.","setup":"Answer honestly; unsure is a complete answer. Say:","yourLine":[{"text":"\"I'm not sure yet. Can we slow down?\"","best":true},{"text":"\"...yeah, it's fine\" (while uneasy)"}],"relearn":"'I'm not sure yet' is a full answer: you can ask to slow down.","persona":"any","source":"honesty"},
  {"id":"mt-1104","cat":"reading-respecting","type":"role-play","hook":"You want to make it easy for your partner to say no to you.","setup":"Open the door for a no. Say:","yourLine":[{"text":"\"A no from you is totally fine. I mean that.\"","best":true},{"text":"\"You wouldn't say no to me, right?\""}],"relearn":"Saying 'a no is totally fine' makes any yes a real, free one.","persona":"any","source":"checking in"},
  {"id":"mt-1105","cat":"reading-respecting","type":"role-play","hook":"Your partner has clearly said they want to stop.","setup":"Receive it warmly, no sulking. Say:","yourLine":[{"text":"\"Of course, thank you for telling me.\"","best":true},{"text":"\"Seriously? Right now?\""}],"relearn":"Receive a stop warmly: 'thank you for telling me', no sulking.","persona":"any","source":"respect boundary"},
  {"id":"mt-1106","cat":"reading-respecting","type":"role-play","hook":"You want to read your partner's pace instead of leading it.","setup":"Hand them the pace. Say:","yourLine":[{"text":"\"You set the pace. I'll follow what feels good to you.\"","best":true},{"text":"\"Just keep up with me\""}],"relearn":"Letting a partner set the pace keeps it mutual, not led by one.","persona":"any","source":"mutual"},
  {"id":"mt-1107","cat":"reading-respecting","type":"role-play","hook":"Your partner deferred with 'whatever you want'. You want their real voice.","setup":"Invite what they actually want. Say:","yourLine":[{"text":"\"I really want to know what YOU want here.\"","best":true},{"text":"\"Okay, I'll just decide then\""}],"relearn":"Inviting 'what do YOU want?' draws out a real yes, not going-along.","persona":"Vijay","source":"checking in"},
  {"id":"mt-1108","cat":"reading-respecting","type":"role-play","hook":"You noticed a flinch and want to check before doing anything more.","setup":"Pause on the flinch. Say:","yourLine":[{"text":"\"I felt you flinch. We can stop right here.\"","best":true},{"text":"\"You're overthinking it\""}],"relearn":"Naming a flinch and offering to stop reads the body's real cue.","persona":"any","source":"reading cues"},
  {"id":"mt-1109","cat":"reading-respecting","type":"role-play","hook":"You want to keep checking in even though things are going well.","setup":"Keep the yes ongoing. Say:","yourLine":[{"text":"\"Still good? Tell me the second it changes.\"","best":true},{"text":"Assume it's settled and stop asking"}],"relearn":"'Still good? tell me if it changes' keeps a yes ongoing and shared.","persona":"any","source":"checking in"},
  {"id":"mt-1110","cat":"reading-respecting","type":"role-play","hook":"Your partner seems to be forcing enthusiasm to please you.","setup":"Take the pressure off them. Say:","yourLine":[{"text":"\"You don't have to be into it for me, only for you.\"","best":true},{"text":"\"See, you're loving it\""}],"relearn":"Telling them they need not perform for you invites a real yes.","persona":"any","source":"checking in"},
  {"id":"mt-1111","cat":"reading-respecting","type":"role-play","hook":"You want to say you're not comfortable and have it land clearly.","setup":"Be clear and unapologetic. Say:","yourLine":[{"text":"\"I want to stop now. I'm not comfortable.\"","best":true},{"text":"Stay silent and wait for it to end"}],"relearn":"You can say 'I want to stop, I'm not comfortable': it must be heard.","persona":"Sneha","source":"voicing a boundary"},
  {"id":"mt-1112","cat":"reading-respecting","type":"role-play","hook":"Your partner pulled away and you want to reassure, not pursue.","setup":"Reassure and step back. Say:","yourLine":[{"text":"\"No pressure at all. We can just be close like this.\"","best":true},{"text":"\"What did I do wrong?\" (leaning back in)"}],"relearn":"Reassuring without pursuing, with a 'no pressure', respects the pull-away.","persona":"any","source":"respect"},
  {"id":"mt-1113","cat":"reading-respecting","type":"role-play","hook":"You want to thank your partner for telling you a boundary.","setup":"Welcome the boundary. Say:","yourLine":[{"text":"\"I'm glad you told me. That helps me get it right.\"","best":true},{"text":"\"Why are you making this a thing?\""}],"relearn":"Welcoming a boundary with 'glad you told me' makes honesty safe.","persona":"any","source":"respect boundary"},
  {"id":"mt-1114","cat":"reading-respecting","type":"role-play","hook":"You want to invite your partner to steer, not just react to you.","setup":"Hand over the lead. Say:","yourLine":[{"text":"\"What do you want? I'd love this to be your call too.\"","best":true},{"text":"\"Just go with whatever I do\""}],"relearn":"Inviting them to steer makes intimacy shared, not one-sided.","persona":"Arjun","source":"mutual"},
  {"id":"mt-1115","cat":"reading-respecting","type":"strike-rewrite","hook":"\"If they really wanted to stop, they'd say so out loud.\"","myth":{"un":"People always say 'stop' clearly if they mean it.","re":"Many people freeze or go quiet instead of saying stop; absence of a clear yes means stop.","why":"Discomfort often shows in the body before words: read cues, don't wait for a perfect 'no'."},"relearn":"People often freeze instead of saying stop: read cues, don't wait.","persona":"any","source":"reading cues"},
  {"id":"mt-1116","cat":"reading-respecting","type":"strike-rewrite","hook":"\"Checking in mid-way kills the mood.\"","myth":{"un":"Pausing to ask 'still good?' ruins the moment.","re":"A quick check-in makes both people feel safe and seen, which deepens the moment.","why":"Asking is part of intimacy, not an interruption to it."},"relearn":"A mid-way check-in deepens intimacy. It's part of it, not a break.","persona":"Vijay","source":"checking in"},
  {"id":"mt-1117","cat":"reading-respecting","type":"strike-rewrite","hook":"\"Going along quietly is the same as saying yes.\"","myth":{"un":"If they don't object, that counts as a yes.","re":"Silence or going along isn't consent; only a clear, willing yes is.","why":"People go quiet when unsure or uneasy. The absence of a no is never a yes."},"relearn":"Silence or going along isn't a yes: only a clear, willing yes is.","persona":"any","source":"reading cues"},
  {"id":"mt-1118","cat":"reading-respecting","type":"strike-rewrite","hook":"\"They said yes earlier, so I don't need to keep checking.\"","myth":{"un":"One yes covers the whole night.","re":"Willingness can change anytime; an earlier yes isn't an ongoing yes, so keep checking.","why":"Reading cues as you go is what keeps a yes real, moment to moment."},"relearn":"An earlier yes isn't ongoing: keep reading cues and checking in.","persona":"any","source":"checking in"},
  {"id":"mt-1119","cat":"reading-respecting","type":"strike-rewrite","hook":"\"A flinch or pulling away is just being shy, push gently through it.\"","myth":{"un":"Flinching means shy; ease them past it.","re":"A flinch or pull-away is a real cue to stop and check, not to push through.","why":"The body signals discomfort before words do: honour it instantly."},"relearn":"A flinch is a cue to stop and check, never to push through.","persona":"any","source":"reading cues"},
  {"id":"mt-1120","cat":"reading-respecting","type":"strike-rewrite","hook":"\"Asking what they want makes you look unsure and unromantic.\"","myth":{"un":"Asking what a partner wants seems weak.","re":"Asking what your partner wants is confident and caring; it makes intimacy mutual.","why":"Reading and honouring someone's wishes is the heart of real closeness."},"relearn":"Asking what a partner wants is confident and caring, never weak.","persona":"Arjun","source":"mutual"},
  {"id":"mt-1121","cat":"reading-respecting","type":"strike-rewrite","hook":"\"If you stop every time they hesitate, nothing will ever happen.\"","myth":{"un":"Honouring every hesitation means giving up.","re":"Stopping on a hesitation builds trust, so real, eager yeses come more easily over time.","why":"Feeling free to pause is exactly what lets someone relax into a true yes."},"relearn":"Stopping on a hesitation builds the trust that real yeses grow from.","persona":"any","source":"respect"},
  {"id":"mt-1122","cat":"reading-respecting","type":"sort","hook":"Sort each cue: a clear go-ahead, or a stop-and-check?","items":[{"id":"a","text":"Pulling you closer, smiling"},{"id":"b","text":"Tensing up and looking away"},{"id":"c","text":"An eager 'yes, I want to'"},{"id":"d","text":"A flat, reluctant 'I guess'"},{"id":"e","text":"Laughing and saying 'definitely'"},{"id":"f","text":"Going silent and still"}],"bins":[{"id":"go","label":"Clear go-ahead","valence":"pos"},{"id":"stop","label":"Stop and check","valence":"neg"}],"key":{"a":"go","b":"stop","c":"go","d":"stop","e":"go","f":"stop"},"relearn":"Pulling close and an eager yes are go; tensing, 'I guess', or silence mean stop and check.","persona":"any","source":"reading cues"},
  {"id":"mt-1123","cat":"reading-respecting","type":"sort","hook":"Sort each move: reads the cue, or ignores it?","items":[{"id":"a","text":"Pausing the moment they tense"},{"id":"b","text":"Carrying on through their silence"},{"id":"c","text":"Asking 'you still good?'"},{"id":"d","text":"Guilt-tripping a hesitation"},{"id":"e","text":"Slowing down when they look unsure"},{"id":"f","text":"Taking 'whatever you want' as a yes"}],"bins":[{"id":"reads","label":"Reads the cue","valence":"pos"},{"id":"ignores","label":"Ignores it","valence":"neg"}],"key":{"a":"reads","b":"ignores","c":"reads","d":"ignores","e":"reads","f":"ignores"},"relearn":"Pausing, asking, and slowing read the cue; pushing through or guilting ignores it.","persona":"any","source":"respect"},
  {"id":"mt-1124","cat":"reading-respecting","type":"sort","hook":"Sort each reply to a 'not now': honours it, or pressures it?","items":[{"id":"a","text":"'No worries, thanks for telling me'"},{"id":"b","text":"'Come on, just this once'"},{"id":"c","text":"'Okay, let's just hang out then'"},{"id":"d","text":"'Fine, but you're no fun'"},{"id":"e","text":"'Totally fine, your call'"},{"id":"f","text":"Going cold and silent"}],"bins":[{"id":"honours","label":"Honours the no","valence":"pos"},{"id":"pressures","label":"Pressures it","valence":"neg"}],"key":{"a":"honours","b":"pressures","c":"honours","d":"pressures","e":"honours","f":"pressures"},"relearn":"Warmth and 'your call' honour a no; 'just this once', sulking, or going cold pressure it.","persona":"any","source":"respect boundary"},
  {"id":"mt-1125","cat":"reading-respecting","type":"sort","hook":"Sort each signal: genuine enthusiasm, or reluctant going-along?","items":[{"id":"a","text":"'Yes! I've been wanting to'"},{"id":"b","text":"'…if you really want to'"},{"id":"c","text":"Leaning in, bright-eyed"},{"id":"d","text":"Stiff, with a fixed smile"},{"id":"e","text":"Suggesting the next thing"},{"id":"f","text":"A long pause, then 'k.'"}],"bins":[{"id":"keen","label":"Genuine enthusiasm","valence":"pos"},{"id":"reluctant","label":"Reluctant going-along","valence":"neg"}],"key":{"a":"keen","b":"reluctant","c":"keen","d":"reluctant","e":"keen","f":"reluctant"},"relearn":"Eager words, bright eyes, and initiating are keen; 'if you want', stiffness, or a flat 'k' are reluctant.","persona":"any","source":"reading cues"},
  {"id":"mt-1126","cat":"reading-respecting","type":"sort","hook":"Sort each line: makes a 'no' safe, or makes it hard?","items":[{"id":"a","text":"'A no from you is totally fine'"},{"id":"b","text":"'You wouldn't say no to me, right?'"},{"id":"c","text":"'Only if you really want to'"},{"id":"d","text":"'Don't make this awkward'"},{"id":"e","text":"'We can stop anytime, no reason needed'"},{"id":"f","text":"'Everyone else would say yes'"}],"bins":[{"id":"safe","label":"Makes 'no' safe","valence":"pos"},{"id":"hard","label":"Makes it hard","valence":"neg"}],"key":{"a":"safe","b":"hard","c":"safe","d":"hard","e":"safe","f":"hard"},"relearn":"Open lines make a no safe; guilt, comparisons, or 'don't be awkward' make it hard.","persona":"any","source":"checking in"},
  {"id":"mt-1144","cat":"reading-respecting","type":"sort","hook":"Sort each response when a partner asks to pause: caring, or dismissive?","items":[{"id":"a","text":"'Of course, take all the time you need'"},{"id":"b","text":"'Ugh, again?'"},{"id":"c","text":"'Thanks for telling me'"},{"id":"d","text":"'You're being so sensitive'"},{"id":"e","text":"'No rush at all'"},{"id":"f","text":"Sighing loudly and turning away"}],"bins":[{"id":"caring","label":"Caring","valence":"pos"},{"id":"dismissive","label":"Dismissive","valence":"neg"}],"key":{"a":"caring","b":"dismissive","c":"caring","d":"dismissive","e":"caring","f":"dismissive"},"relearn":"Welcoming a pause is caring; sighing, eye-rolling, or 'so sensitive' dismiss it.","persona":"any","source":"respect"},
  {"id":"mt-1127","cat":"reading-respecting","type":"reflect","hook":"Lensy: a smooth 'no problem' after a 'no', with no sulking, keeps a partner safe. Notice that?","prompt":"What do you think?","options":["Yes","No sulking","Keeps them safe"],"affirm":"Letting a 'no' land with zero guilt-trip is what tells a partner they're truly safe with you.","relearn":"Taking a 'no' gracefully, without sulking, is how you keep a partner safe.","persona":"any","source":"respect"},
  {"id":"mt-1128","cat":"reading-respecting","type":"reflect","hook":"Lensy: checking in mid-way can feel a little awkward at first. How does that sit with you?","prompt":"How do you feel about it?","options":["Worth it","A bit awkward","Gets easier"],"affirm":"Even if it feels new, a check-in is care made out loud, and it gets natural fast. 💞","relearn":"A mid-way check-in is care made out loud; it gets easier with practice.","persona":"any","source":"checking in"},
  {"id":"mt-1129","cat":"reading-respecting","type":"reflect","hook":"Lensy: reading a partner's body, not just their words, is part of really paying attention. See it?","prompt":"What do you think?","options":["Yes","Body talks too","Pay attention"],"affirm":"Tuning into a flinch, a pull-away, or a tense smile is part of truly seeing someone. 💞","relearn":"A partner's body speaks too: reading it is part of paying attention.","persona":"any","source":"reading cues"},
  {"id":"mt-1130","cat":"reading-respecting","type":"reflect","hook":"Lensy: there's real relief when a partner stops the moment you ask. Notice that?","prompt":"What do you think?","options":["Yes","Relief","Feels safe"],"affirm":"That relief is your sense of safety telling you this person can be trusted. 💞","relearn":"Relief when a partner stops on a 'no' is your trust growing.","persona":"any","source":"respect"},
  {"id":"mt-1131","cat":"reading-respecting","type":"reflect","hook":"Lensy: asking 'what do YOU want?' hands a partner the steering wheel. How does that feel?","prompt":"What do you think?","options":["Good","Shared","More mutual"],"affirm":"Inviting their wishes turns intimacy into something you steer together. 💞","relearn":"Asking 'what do YOU want?' makes intimacy something you steer together.","persona":"any","source":"mutual"},
  {"id":"mt-1132","cat":"reading-respecting","type":"reflect","hook":"Lensy: a tense smile can hide a 'not really'. Worth pausing for, would you say?","prompt":"What do you think?","options":["Yes","Worth pausing","Check first"],"affirm":"Pausing on a cue you're unsure of is never wrong. Checking in is always kind. 💞","relearn":"A tense smile can hide a 'not really': pausing to check is always kind.","persona":"any","source":"reading cues"},
  {"id":"mt-1133","cat":"reading-respecting","type":"reflect","hook":"Lensy: when you're unsure, slowing down costs nothing and protects everything. Sit right?","prompt":"What do you think?","options":["Yes","Worth it","Slow down"],"affirm":"Choosing to slow down when unsure is the most caring read you can make. 💞","relearn":"When unsure, slowing down costs nothing and keeps a partner safe.","persona":"any","source":"checking in"},
  {"id":"mt-1134","cat":"reading-respecting","type":"reflect","hook":"Lensy: an enthusiastic yes can still change later. Staying tuned keeps it real. Agree?","prompt":"What do you think?","options":["Yes","Stay tuned","Keep reading"],"affirm":"Holding a yes as ongoing, and staying tuned, is what keeps intimacy mutual. 💞","relearn":"Even an enthusiastic yes can change: staying tuned keeps it real.","persona":"any","source":"checking in"},
  {"id":"mt-1135","cat":"reading-respecting","type":"match","hook":"Match each cue you read to the caring response.","pairs":[{"left":"They pull their hand away","right":"Let go and give space"},{"left":"They go quiet and still","right":"Pause and softly check they're okay"},{"left":"They say 'can we slow down?'","right":"Follow their pace, no questions"},{"left":"They look unsure but say 'okay'","right":"Make it easy to say no instead"},{"left":"They lean in with a clear 'yes'","right":"Stay present and keep checking in"}],"relearn":"Each cue has a caring response: let go, pause, follow their pace, make no safe, stay present.","persona":"any","source":"reading cues"},
  {"id":"mt-1136","cat":"reading-respecting","type":"match","hook":"Match each cue to what it most likely means.","pairs":[{"left":"Tensing and looking away","right":"Discomfort: stop and check"},{"left":"Pulling you closer, smiling","right":"Genuine willingness"},{"left":"A flat 'I guess so'","right":"Going along, not a real yes"},{"left":"Suggesting the next step themselves","right":"Enthusiasm"},{"left":"Freezing mid-moment","right":"A freeze: stop now"}],"relearn":"Tensing or freezing means stop; pulling close or initiating is willingness; a flat 'I guess' is going-along.","persona":"any","source":"reading cues"},
  {"id":"mt-1137","cat":"reading-respecting","type":"match","hook":"Match each reply to a 'not tonight' with what it really is.","pairs":[{"left":"'No worries, thanks for saying'","right":"Respecting the no"},{"left":"'Come on, just once'","right":"Pressure"},{"left":"'Fine, you're no fun'","right":"Sulking as pressure"},{"left":"'Sure, let's just chill'","right":"Honouring it warmly"},{"left":"Going cold all evening","right":"Punishing the no"}],"relearn":"Warmth respects a no; 'just once', sulking, or going cold pressure or punish it.","persona":"any","source":"respect boundary"},
  {"id":"mt-1138","cat":"reading-respecting","type":"match","hook":"Match each thing you might say to what it does.","pairs":[{"left":"'A no is totally fine'","right":"Makes saying no safe"},{"left":"'You still good?'","right":"Keeps the yes ongoing"},{"left":"'What do YOU want?'","right":"Invites their real voice"},{"left":"'Sorry, I misread that'","right":"Repairs after a mistake"},{"left":"'You set the pace'","right":"Hands them the lead"}],"relearn":"Open lines make no safe, keep a yes ongoing, invite their voice, repair, and share the lead.","persona":"any","source":"checking in"},
  {"id":"mt-1139","cat":"reading-respecting","type":"match","hook":"Match each verbal cue to whether it's a real yes.","pairs":[{"left":"'Yes! I really want to'","right":"A clear, willing yes"},{"left":"'…if you want, I guess'","right":"Reluctant going-along"},{"left":"'Absolutely, let's do it'","right":"Enthusiastic yes"},{"left":"A long pause, then 'k.'","right":"Not a real yes"},{"left":"'Whatever you want'","right":"Deferring, not deciding"}],"relearn":"Eager words are a real yes; 'if you want', a flat 'k', or deferring are not.","persona":"any","source":"reading cues"},
  {"id":"mt-1140","cat":"reading-respecting","type":"match","hook":"Match each non-verbal cue to the right read.","pairs":[{"left":"Leaning in, relaxed","right":"At ease: keep checking in"},{"left":"Crossing arms, stepping back","right":"A boundary: ease off"},{"left":"A small flinch","right":"Stop and ask"},{"left":"Reaching for you first","right":"Willing and engaged"},{"left":"Shrinking, avoiding eyes","right":"May not be free: make no safe"}],"relearn":"Relaxed, reaching-in cues are willing; crossing arms, a flinch, or shrinking mean stop and check.","persona":"any","source":"reading cues"},
  {"id":"mt-1141","cat":"reading-respecting","type":"match","hook":"Match each scene to the right next move.","pairs":[{"left":"Partner seems far away","right":"Name it and offer to pause"},{"left":"Partner forces enthusiasm to please you","right":"Take the pressure off"},{"left":"Partner says yes but won't meet your eyes","right":"Make 'no' safe and re-check"},{"left":"Partner deflects with a nervous laugh","right":"Ease off and ask if they're okay"},{"left":"Partner clearly initiates","right":"Stay present, keep reading"}],"relearn":"Each scene has a caring read: name it, ease pressure, make no safe, or stay present.","persona":"any","source":"reading cues"},
  {"id":"mt-1142","cat":"reading-respecting","type":"match","hook":"Match each repair line to the moment it fits.","pairs":[{"left":"After you misread a cue","right":"'Sorry, let's stop. You okay?'"},{"left":"They pulled away","right":"'No pressure, we can just be close'"},{"left":"They told you a boundary","right":"'Glad you told me. That helps'"},{"left":"They asked to slow down","right":"'Of course. Tell me what feels okay'"},{"left":"They went quiet mid-moment","right":"'You got quiet, want to pause?'"}],"relearn":"Each moment has a repair line: stop and check, ease pressure, welcome the boundary, follow their pace.","persona":"any","source":"repair"},
  {"id":"mt-1170","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Saying yes earlier means you can't stop now.\"","myth":{"un":"Saying yes earlier means you can't stop now.","re":"An earlier yes is not an ongoing yes; either person can stop at any moment.","why":"The right to stop never expires, even after things start."},"relearn":"An earlier yes isn't a forever yes; you can stop at any moment.","persona":"any","source":"right to stop"},
  {"id":"mt-1171","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Being a couple means a standing yes to everything.\"","myth":{"un":"Being in a relationship is a standing yes to everything.","re":"A relationship is never standing consent; a fresh, willing yes is needed every time.","why":"Two people stay two people with separate choices, always."},"relearn":"A relationship isn't standing consent; consent is needed every single time.","persona":"any","source":"relationship not consent"},
  {"id":"mt-1172","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Marriage means a husband or wife can never refuse.\"","myth":{"un":"Once married, a spouse can never refuse.","re":"Marriage is not standing consent; either spouse can say no or stop, any time.","why":"A wedding does not hand away anyone's right over their own body."},"relearn":"Marriage is not standing consent; either spouse can say no, any time.","persona":"any","source":"marriage not consent"},
  {"id":"mt-1173","cat":"rights-and-law","type":"strike-rewrite","hook":"\"The age-of-consent rule is just red tape.\"","myth":{"un":"The age-of-consent rule is just red tape.","re":"In India the age of consent is 18; it shields young people from exploitation.","why":"It is a real protective law, not a formality to wave away."},"relearn":"India's age of consent is 18, a real protection, not red tape.","persona":"Counsellor","source":"POCSO age 18 (verified)"},
  {"id":"mt-1174","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Reporting only makes everything worse.\"","myth":{"un":"Reporting or telling someone only makes things worse.","re":"Telling a trusted adult or a helpline is how support and safety begin.","why":"Silence shields the person who caused harm, no one else."},"relearn":"Telling a trusted person starts support; silence only shields a wrongdoer.","persona":"any","source":"reporting helps"},
  {"id":"mt-1175","cat":"rights-and-law","type":"strike-rewrite","hook":"\"If you didn't fight back, it wasn't really wrong.\"","myth":{"un":"If you didn't fight or shout, it wasn't really wrong.","re":"Freezing or going quiet is a normal response and never means you agreed.","why":"Consent is a free yes, not the lack of a fight; harm is on the one who ignored it."},"relearn":"Freezing isn't agreeing; harm is on the one who ignored consent, never you.","persona":"any","source":"freezing / no blame"},
  {"id":"mt-1176","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Helplines will judge you or tell your family.\"","myth":{"un":"Helplines will judge you or report straight to your family.","re":"Helplines listen with care and are on your side; reaching out is strength.","why":"They exist to help you find safe options, at your pace."},"relearn":"Helplines are on your side; reaching out is strength, not shame.","persona":"Counsellor","source":"confidential help"},
  {"id":"mt-1177","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Being older or 'the man' gives you the final say.\"","myth":{"un":"Being older or the man of the house gives you the final say in intimacy.","re":"No status grants an automatic yes; both people hold equal rights, every time.","why":"Age, gender or money never out-rank another person's body and choice."},"relearn":"No status grants an automatic yes; both hold equal rights, every time.","persona":"any","source":"equal rights"},
  {"id":"mt-1178","cat":"rights-and-law","type":"strike-rewrite","hook":"\"You led them on, so part of it is on you.\"","myth":{"un":"You led them on, so part of the harm is on you.","re":"How you dressed, flirted or texted never makes harm partly your fault.","why":"Only the person who ignored a no or a stop is responsible for it."},"relearn":"Flirting or dressing a way never shares the blame; harm is on the one who ignored you.","persona":"any","source":"no victim-blaming"},
  {"id":"mt-1178b","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Once you accept gifts, you owe them.\"","myth":{"un":"Once you accept their gifts or dates, you owe them intimacy.","re":"No gift, meal or relationship ever creates a debt of intimacy.","why":"Intimacy is a free yes, never a payment owed for anything."},"relearn":"No gift or date is owed back as intimacy; it's always a free yes.","persona":"any","source":"no owes framing"},
  {"id":"mt-1179","cat":"rights-and-law","type":"strike-rewrite","hook":"\"It happened a while ago, so nothing can be done now.\"","myth":{"un":"It happened a while back, so it's too late to get any help.","re":"You can still reach a trusted adult or a helpline; support has no expiry.","why":"Your right to safety and support doesn't run out with time."},"relearn":"It's never too late to reach help; support has no expiry date.","persona":"Counsellor","source":"help any time"},
  {"id":"mt-1180","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Survivors who 'overreact' aren't believed anyway.\"","myth":{"un":"People who report just overreact and won't be believed.","re":"You deserve to be believed and supported; a disclosure is always taken seriously.","why":"It is never the survivor's fault, and their account matters."},"relearn":"You deserve to be believed; a disclosure is taken seriously, never dismissed.","persona":"Sneha","source":"believe survivors"},
  {"id":"mt-1181","cat":"rights-and-law","type":"strike-rewrite","hook":"\"Knowing the law is only for adults and lawyers.\"","myth":{"un":"Knowing your rights and the law is only for adults and lawyers.","re":"Knowing your rights and the helplines is for you, now; it keeps you and friends safe.","why":"Rights protect you most when you actually know them."},"relearn":"Knowing your rights and the helplines now keeps you and friends safe.","persona":"Vijay","source":"know your rights"},
  {"id":"mt-1182","cat":"rights-and-law","type":"strike-rewrite","hook":"\"A boy can't be pressured or harmed, so the law isn't for him.\"","myth":{"un":"A boy can't really be pressured or harmed, so these rights aren't for him.","re":"Anyone of any gender can be pressured or harmed, and the same rights protect them.","why":"Consent and these protections are even-handed, for everyone."},"relearn":"Anyone of any gender can be harmed; the same rights protect everyone.","persona":"Arjun","source":"even-handed rights"},
  {"id":"mt-1183","cat":"rights-and-law","type":"reflect","hook":"Lensy: you hold the right to stop at any moment, and so does your partner. Sit with that?","prompt":"What do you think?","options":["Yes","Always mine","Theirs too"],"affirm":"That right is yours and theirs, permanently, with no exceptions.","relearn":"You and your partner both always hold the right to stop, any time.","persona":"any","source":"right to stop"},
  {"id":"mt-1184","cat":"rights-and-law","type":"reflect","hook":"Lensy: what someone wore or drank never shifts the blame onto them. Stand by that?","prompt":"What do you think?","options":["Yes","Not their clothes","I stand by it"],"affirm":"Clothing, drinks, or location never move responsibility; it sits only with the person who ignored a 'no'.","relearn":"Clothes, drink, or place never shift blame onto a survivor.","persona":"any","source":"no victim-blaming"},
  {"id":"mt-1185","cat":"rights-and-law","type":"reflect","hook":"Lensy: reaching a helpline or trusted adult is a brave, strong step, not a shameful one. Agree?","prompt":"What do you think?","options":["Yes","It's strength","I'd reach out"],"affirm":"Reaching out is strength; helplines are on your side.","relearn":"Reaching a helpline or trusted adult is strength, not shame.","persona":"any","source":"reaching out is strength"},
  {"id":"mt-1186","cat":"rights-and-law","type":"reflect","hook":"Lensy: no relationship or marriage is a standing yes, consent is needed each time. Clear?","prompt":"What do you think?","options":["Yes","Each time","Clear"],"affirm":"Right, a relationship or marriage is never standing consent; ask each time.","relearn":"No relationship or marriage is standing consent; ask each time.","persona":"any","source":"relationship not consent"},
  {"id":"mt-1187","cat":"rights-and-law","type":"reflect","hook":"Lensy: both partners hold equal rights, no one's age or status grants a final say. Feel right?","prompt":"What do you think?","options":["Yes","Equal","No final say"],"affirm":"Both hold equal rights; no status hands anyone a final say over the other.","relearn":"Both partners hold equal rights; no status grants a final say.","persona":"any","source":"equal rights"},
  {"id":"mt-1188","cat":"rights-and-law","type":"reflect","hook":"Lensy: knowing 181, 1091, 112 and 1098 means you can help yourself or a friend fast. Feel readier?","prompt":"What do you think?","options":["Yes","Readier","I know who to call"],"affirm":"Knowing the helplines is exactly what readiness to stay safe looks like.","relearn":"Knowing 181, 1091, 112 and 1098 helps you act fast for yourself or a friend.","persona":"any","source":"helplines (verified)"},
  {"id":"mt-1189","cat":"rights-and-law","type":"reflect","hook":"Lensy: if a friend ever discloses harm to you, believing them is the first gift you give. See that?","prompt":"What do you think?","options":["Yes","I'd believe them","First gift"],"affirm":"Believing a friend is the first, biggest thing; then help them reach support.","relearn":"If a friend discloses harm, believe them first, then help them get support.","persona":"any","source":"believe + support"},
  {"id":"mt-1190","cat":"rights-and-law","type":"reflect","hook":"Lensy: your right to say no doesn't shrink because you're young, in love, or far from home. True?","prompt":"What do you think?","options":["Yes","Doesn't shrink","Still mine"],"affirm":"Your right to say no holds fully, whatever your age, feelings or place.","relearn":"Your right to say no doesn't shrink with age, love, or distance from home.","persona":"any","source":"right holds"},
  {"id":"mt-1191","cat":"rights-and-law","type":"reflect","hook":"Lensy: help goes at your pace, and they explain each next step before it happens. Reassuring?","prompt":"What do you think?","options":["Yes","My pace","I decide"],"affirm":"Help goes at your pace and they explain each step; if you're under 18 and being hurt, they act to keep you safe.","relearn":"Help goes at your pace; they explain each step and act to keep under-18s safe.","persona":"any","source":"confidential, your pace"},
  {"id":"mt-1192","cat":"rights-and-law","type":"reflect","hook":"Lensy: an older person pursuing someone under 18 is the law's concern, not the young person's fault. Clear?","prompt":"What do you think?","options":["Yes","Not their fault","The law steps in"],"affirm":"Right, that's a protection law at work; the young person carries no blame.","relearn":"An older person pursuing an under-18 is the law's concern, never the teen's fault.","persona":"Counsellor","source":"protection not blame"},
  {"id":"mt-1193","cat":"rights-and-law","type":"reflect","hook":"Lensy: pressing 'Get help' is allowed for a friend's situation too, not just your own. Good to know?","prompt":"What do you think?","options":["Yes","For a friend too","Good to know"],"affirm":"Yes, reaching help for a friend in trouble is allowed and kind.","relearn":"You can reach help for a friend's situation, not only your own.","persona":"any","source":"help for friends"},
  {"id":"mt-1194","cat":"rights-and-law","type":"reflect","hook":"Lensy: the same consent rule applies whether you're 16 or 60. Does that land?","prompt":"What do you think?","options":["Yes","Same at any age","It lands"],"affirm":"Consent doesn't change shape with age; the same clear 'yes' is the rule across your whole life.","relearn":"The consent rule stays the same at every age, from teen to adult.","persona":"any","source":"consent at any age"},
  {"id":"mt-1195","cat":"rights-and-law","type":"reflect","hook":"Lensy: no one can sign away your right to stop, not a partner, not a promise, not a screenshot. True?","prompt":"What do you think?","options":["Yes","Can't be signed away","Still mine"],"affirm":"True, no promise, message or partner can sign away your right to stop.","relearn":"No partner, promise, or message can sign away your right to stop.","persona":"any","source":"right unsignable"},
  {"id":"mt-1196","cat":"rights-and-law","type":"reflect","hook":"Lensy: 'It was never your fault' is true the first time you hear it and every time after. Let it land?","prompt":"What do you think?","options":["Yes","Every time","Let it land"],"affirm":"It stays true every time; the fault sits only with whoever ignored consent.","relearn":"'It was never your fault' stays true every time you need to hear it.","persona":"any","source":"no blame"},
  {"id":"mt-1197","cat":"rights-and-law","type":"reflect","hook":"Lensy: a real partner welcomes your right to stop, they don't argue you out of it. Recognise that?","prompt":"What do you think?","options":["Yes","Welcomes it","No arguing"],"affirm":"A real partner honours your right to stop without arguing it away.","relearn":"A real partner welcomes your right to stop, not argues you out of it.","persona":"any","source":"honoured no"},
  {"id":"mt-1198","cat":"rights-and-law","type":"reflect","hook":"Lensy: knowing your rights protects you most when you're tired, scared or unsure. Hold onto that?","prompt":"What do you think?","options":["Yes","Especially then","Hold it"],"affirm":"Your rights hold fully even when you're tired, scared or unsure; lean on them.","relearn":"Your rights protect you most when you're tired, scared, or unsure.","persona":"any","source":"rights hold under stress"},
  {"id":"mt-1199","cat":"rights-and-law","type":"reflect","hook":"Lensy: you don't owe anyone an explanation for stopping, 'I want to stop' is reason enough. Agree?","prompt":"What do you think?","options":["Yes","Reason enough","No explaining"],"affirm":"Agreed, 'I want to stop' is a complete reason; no explanation is owed.","relearn":"You owe no explanation for stopping; 'I want to stop' is enough.","persona":"any","source":"no explanation owed"},
  {"id":"mt-1200","cat":"rights-and-law","type":"reflect","hook":"Lensy: the same respect and rights apply whoever you love, of any gender. Feel included?","prompt":"What do you think?","options":["Yes","Whoever I love","Included"],"affirm":"The same rights and respect apply to everyone, of any gender or orientation.","relearn":"The same rights and respect apply whoever you love, of any gender.","persona":"Arjun","source":"inclusive rights"},
  {"id":"mt-1201","cat":"rights-and-law","type":"branch","persona":"Sneha","source":"disclosure / no blame","hook":"A friend discloses an assault and begs you to tell no one.","options":[{"text":"Believe them, say it's not their fault, help them reach 181 or 1098","consequence":"They feel safe and supported.","outcome":"supported","best":true},{"text":"Promise silence, do nothing","consequence":"Gently guide them to help instead."},{"text":"Ask what they did to cause it","consequence":"Never question a survivor; believe them."}],"debrief":"Belief, no blame, and a route to 181 / 1098 is right.","relearn":"Believe a survivor, say it's not their fault, help them reach 181 or 1098."},
  {"id":"mt-1202","cat":"rights-and-law","type":"branch","persona":"Counsellor","source":"helplines (verified)","hook":"Something serious happened to you and you don't know where to turn.","options":[{"text":"Reach a trusted adult or a helpline (181 / 1091 / 112 / 1098)","consequence":"You get support and real options.","outcome":"help","best":true},{"text":"Carry it alone in silence","consequence":"You don't have to; a helpline can help."},{"text":"Tell yourself it was your fault","consequence":"It was never your fault; reaching help is right."}],"debrief":"Help exists (181 / 1091 / 112 / 1098); reaching it is brave.","relearn":"For assault or coercion, reach a trusted adult or 181 / 1091 / 112 / 1098."},
  {"id":"mt-1203","cat":"rights-and-law","type":"branch","persona":"Counsellor","source":"POCSO (verified)","hook":"You're under 18 and an adult is pursuing a sexual relationship.","options":[{"text":"Step back and tell a trusted adult; the law protects you","consequence":"You stay safe and supported.","outcome":"protected","best":true},{"text":"Go along to seem grown-up","consequence":"This is a protection matter; tell an adult."},{"text":"Keep it secret as asked","consequence":"Secrecy keeps you at risk; an adult can help."}],"debrief":"An adult pursuing an under-18 is a protection matter.","relearn":"Under 18, the law protects you; tell a trusted adult about an older pursuer."},
  {"id":"mt-1204","cat":"rights-and-law","type":"branch","persona":"any","source":"relationship not consent","hook":"Your partner says 'we're together now, so you can't ever say no.'","options":[{"text":"Say a relationship isn't a standing yes; you both ask each time","consequence":"You hold your right.","outcome":"right held","best":true},{"text":"Accept it to avoid a fight","consequence":"A relationship is never standing consent."},{"text":"Believe you owe them now","consequence":"You owe no one intimacy; being together cancels nothing."}],"debrief":"A relationship is not standing consent; the right to say no never expires.","relearn":"A relationship isn't a standing yes; you both keep the right to say no."},
  {"id":"mt-1205","cat":"rights-and-law","type":"branch","persona":"Vijay","source":"right to stop","hook":"You want to stop midway and worry it's 'too late' to.","options":[{"text":"Say 'I want to stop' and stop; there's no point too late","consequence":"Your boundary is honoured.","outcome":"stopped safely","best":true},{"text":"Push through because you started","consequence":"There's no 'too late'; you can stop at any point."},{"text":"Wait for them to decide for you","consequence":"The choice is yours; either can stop anytime."}],"debrief":"There is no 'too late to stop'; either person can stop at any point.","relearn":"You can stop at any point; 'I want to stop' is always reason enough."},
  {"id":"mt-1206","cat":"rights-and-law","type":"branch","persona":"Counsellor","source":"blackmail / help (verified)","hook":"A friend is blackmailed with private photos to stay in a relationship.","options":[{"text":"Say it's not their fault; help them reach a trusted adult or 1098 / 112","consequence":"They get support.","outcome":"supported","best":true},{"text":"Tell them to give in to stay safe","consequence":"Giving in to a threat isn't consent."},{"text":"Say they shouldn't have sent photos","consequence":"Fault is on the one threatening, not them."}],"debrief":"Blackmail makes any 'yes' not consent; route to a trusted adult or 1098 / 112.","relearn":"Blackmail isn't consent; help a friend reach a trusted adult or 1098 / 112."},
  {"id":"mt-1207","cat":"rights-and-law","type":"branch","persona":"any","source":"bystander / help (verified)","hook":"You see a classmate being coerced at a party and freeze.","options":[{"text":"Step in safely, check on them, help them reach an adult or 112","consequence":"They aren't left alone.","outcome":"helped","best":true},{"text":"Look away; not your business","consequence":"A safe check-in matters; help or fetch an adult."},{"text":"Film it instead of helping","consequence":"Filming harms them; offer help or reach 112."}],"debrief":"A safe check-in or fetching an adult (or 112) can change everything.","relearn":"If you see coercion, check in safely and help them reach an adult or 112."},
  {"id":"mt-1208","cat":"rights-and-law","type":"branch","persona":"Sneha","source":"coercion / right to refuse","hook":"Your partner threatens 'I'll break up and tell everyone' unless you go further.","options":[{"text":"Name it as a threat, hold your no, step away","consequence":"You refuse a 'yes' built on fear.","outcome":"refused safely","best":true},{"text":"Give in so they don't leave","consequence":"A yes under threat isn't consent."},{"text":"Believe you owe them","consequence":"Threats make any 'yes' not consent."}],"debrief":"A threat to leave or expose you makes any 'yes' not consent.","relearn":"A 'yes' given under threat isn't consent; naming the threat is allowed."},
  {"id":"mt-1209","cat":"rights-and-law","type":"branch","persona":"Counsellor","source":"disclosure / confidential help","hook":"A relative tells you to keep quiet, 'for the family's honour.'","options":[{"text":"Reach a trusted adult or helpline anyway; safety before silence","consequence":"You get support.","outcome":"supported","best":true},{"text":"Stay silent for the family name","consequence":"Silence shields only the wrongdoer."},{"text":"Decide it was your fault","consequence":"It's never your fault; help can support you."}],"debrief":"Your safety comes before silence; help (181 / 1098) is on your side.","relearn":"Your safety comes before 'honour'; reach a trusted adult or 181 / 1098."},
  {"id":"mt-1210","cat":"rights-and-law","type":"branch","persona":"any","source":"help any time","hook":"You realise something from a year ago wasn't okay, and wonder if it's too late.","options":[{"text":"Reach a counsellor or helpline now; support has no expiry","consequence":"You can get support.","outcome":"supported","best":true},{"text":"Decide it's too late, bury it","consequence":"It's never too late; help is still there."},{"text":"Blame yourself for not seeing sooner","consequence":"Recognising it now is strength."}],"debrief":"Support has no expiry; reaching a counsellor or helpline is always allowed.","relearn":"It's never too late to reach a counsellor or helpline; support has no expiry."},
  {"id":"mt-1211","cat":"rights-and-law","type":"branch","persona":"Vijay","source":"ongoing consent","hook":"A partner insists 'real couples don't need to ask each time.'","options":[{"text":"Say checking in each time is what respect looks like","consequence":"You keep consent ongoing and caring.","outcome":"mutual","best":true},{"text":"Drop checking in to seem like a 'real couple'","consequence":"Consent is needed every time; checking in is care."},{"text":"Assume a past yes covers today","consequence":"An earlier yes isn't today's yes; ask each time."}],"debrief":"Consent is needed every time; checking in is respect, not distrust.","relearn":"Real couples still ask each time; consent is ongoing, not assumed."},
  {"id":"mt-1212","cat":"rights-and-law","type":"branch","persona":"Counsellor","source":"online grooming / Childline (verified)","hook":"A younger sibling is being pressured online by an adult stranger.","options":[{"text":"Tell a trusted adult and reach Childline 1098; keep the chats","consequence":"Your sibling is protected.","outcome":"protected","best":true},{"text":"Tell them to just block, say nothing","consequence":"An adult and 1098 should also know."},{"text":"Handle it yourself in secret","consequence":"This needs adults; reach Childline 1098."}],"debrief":"An adult pressuring a minor online is a protection matter; reach Childline 1098.","relearn":"An adult pressuring a minor online: tell a trusted adult and reach Childline 1098."},
  {"id":"mt-1213","cat":"rights-and-law","type":"branch","persona":"any","source":"no owes framing","hook":"After a stop, your partner sulks: 'fine, but you owe me later.'","options":[{"text":"Say you owe nothing for stopping; a stop is always allowed","consequence":"Your boundary holds.","outcome":"boundary held","best":true},{"text":"Agree to make up for it later","consequence":"You owe nothing for stopping; a 'debt' isn't consent."},{"text":"Feel guilty and apologise","consequence":"Stopping needs no apology; the sulking is the red flag."}],"debrief":"Stopping creates no debt; 'you owe me later' is pressure, not consent.","relearn":"You owe nothing for stopping; 'you owe me later' is pressure, not consent."},
  {"id":"mt-1214","cat":"rights-and-law","type":"branch","persona":"Sneha","source":"support to disclose","hook":"A friend was hurt but feels too ashamed to use a helpline.","options":[{"text":"Say it's not their fault and offer to reach 181 / 1098 together","consequence":"They feel less alone.","outcome":"supported","best":true},{"text":"Tell them to forget it","consequence":"They deserve support; offer to go together."},{"text":"Agree helplines are embarrassing","consequence":"Reaching out is strength; help is on your side."}],"debrief":"Company plus 'it's not your fault' makes reaching 181 / 1098 feel possible.","relearn":"Offer to reach 181 / 1098 together; reaching out is strength, not shame."},
  {"id":"mt-1215","cat":"rights-and-law","type":"match","hook":"Match each need to the right India helpline.","pairs":[{"left":"A woman needing help or in distress","right":"Women Helpline 181"},{"left":"An emergency happening right now","right":"Emergency 112"},{"left":"Anyone under 18 facing harm","right":"Childline 1098"},{"left":"A woman in distress, alternate line","right":"Women in distress 1091"},{"left":"Someone to confide in safely","right":"A trusted adult or counsellor"}],"relearn":"India: 181 / 1091 (women), 112 (emergency), 1098 (under 18), plus a trusted adult.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"mt-1216","cat":"rights-and-law","type":"match","hook":"Match each right to what it really means.","pairs":[{"left":"Reversible","right":"You can stop at any moment"},{"left":"Specific","right":"Yes to one thing isn't yes to all"},{"left":"Ongoing","right":"Willingness can change anytime"},{"left":"Equal","right":"No one holds the final say"},{"left":"Yours and theirs","right":"Both always hold the right to say no"}],"relearn":"Your rights: reversible, specific, ongoing, equal, and held by both of you.","persona":"any","source":"rights meanings"},
  {"id":"mt-1217","cat":"rights-and-law","type":"match","hook":"Match the situation to the right first response.","pairs":[{"left":"A friend discloses harm","right":"Believe them, no blame"},{"left":"You don't know where to turn","right":"Reach a trusted adult or helpline"},{"left":"An adult pursues an under-18","right":"It's a protection matter; tell an adult"},{"left":"A partner says no relationship needs asking","right":"Ask each time anyway"},{"left":"Someone says it's too late to stop","right":"Stop; there's no point too late"}],"relearn":"Right first moves: believe, route to help, treat under-18 as protected, keep asking.","persona":"Counsellor","source":"first responses"},
  {"id":"mt-1218","cat":"rights-and-law","type":"match","hook":"Match each phrase to the right or myth it names.","pairs":[{"left":"\"You can stop at any moment\"","right":"A real right: to stop"},{"left":"\"Together means a standing yes\"","right":"A myth about relationships"},{"left":"\"Your right to say no never expires\"","right":"A real right: a lasting no"},{"left":"\"You owe it once you start\"","right":"A myth about owing"},{"left":"\"Help is on your side\"","right":"A real right: to seek help"}],"relearn":"Stopping, a lasting no and help on your side are real rights; 'standing yes' and 'owe it' are myths.","persona":"any","source":"rights vs myths"},
  {"id":"mt-1219","cat":"rights-and-law","type":"match","hook":"Match each person to who can help them in India.","pairs":[{"left":"A 16-year-old facing abuse","right":"Childline 1098"},{"left":"A young woman being coerced","right":"Women Helpline 181"},{"left":"Anyone in immediate danger","right":"Emergency 112"},{"left":"A woman in distress at night","right":"Women in distress 1091"},{"left":"Someone needing to talk it through","right":"A school counsellor"}],"relearn":"Under 18: 1098; women: 181 / 1091; danger now: 112; to talk: a counsellor.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"mt-1220","cat":"rights-and-law","type":"match","hook":"Match each true statement to the right it protects.","pairs":[{"left":"\"I can change my mind\"","right":"The right to stop"},{"left":"\"My family's honour isn't worth my silence\"","right":"The right to seek help"},{"left":"\"We decide together\"","right":"The right to equal say"},{"left":"\"A past yes isn't today's yes\"","right":"The right to ongoing consent"},{"left":"\"It was never my fault\"","right":"The right to no blame"}],"relearn":"Each truth names a right: to stop, to seek help, to equal say, to ongoing consent.","persona":"any","source":"truths to rights"},
  {"id":"mt-1221","cat":"rights-and-law","type":"match","hook":"Match each myth to the truth that strikes it down.","pairs":[{"left":"\"Once it starts, you can't stop\"","right":"You can stop at any moment"},{"left":"\"Reporting never helps\"","right":"Telling a trusted person starts support"},{"left":"\"Marriage means you can't refuse\"","right":"Either spouse can say no, any time"},{"left":"\"You led them on\"","right":"Harm is on the one who ignored you"},{"left":"\"It's too late to get help\"","right":"Support has no expiry"}],"relearn":"Every myth here has a truth: stop anytime, telling helps, refuse anytime, no blame.","persona":"any","source":"myth to truth"},
  {"id":"mt-1222","cat":"rights-and-law","type":"sort","hook":"Sort each line: a real right you always hold, or a myth?","items":[{"id":"a","text":"To stop at any moment"},{"id":"b","text":"\"You owe it once you start\""},{"id":"c","text":"To change your mind anytime"},{"id":"d","text":"\"A relationship means a standing yes\""},{"id":"e","text":"To reach help safely"},{"id":"f","text":"\"Once married, you can never refuse\""}],"bins":[{"id":"right","label":"A real right","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"right","b":"myth","c":"right","d":"myth","e":"right","f":"myth"},"relearn":"Stopping, changing your mind and reaching help are rights; 'owe it' lines are myths.","persona":"any","source":"rights vs myths"},
  {"id":"mt-1223","cat":"rights-and-law","type":"sort","hook":"Sort each response to a friend's disclosure: helpful or harmful?","items":[{"id":"a","text":"\"I believe you, it's not your fault\""},{"id":"b","text":"\"What were you wearing?\""},{"id":"c","text":"\"Let's reach a helpline together\""},{"id":"d","text":"\"You probably led them on\""},{"id":"e","text":"\"I'm here, at your pace\""},{"id":"f","text":"\"Just forget it ever happened\""}],"bins":[{"id":"helpful","label":"Helpful","valence":"pos"},{"id":"harmful","label":"Harmful","valence":"neg"}],"key":{"a":"helpful","b":"harmful","c":"helpful","d":"harmful","e":"helpful","f":"harmful"},"relearn":"Believe, no blame, route to help, go at their pace; never question or dismiss them.","persona":"Sneha","source":"disclosure responses"},
  {"id":"mt-1224","cat":"rights-and-law","type":"sort","hook":"Sort each: a verified India helpline, or not a real route?","items":[{"id":"a","text":"Women Helpline 181"},{"id":"b","text":"\"Just post about it online\""},{"id":"c","text":"Childline 1098"},{"id":"d","text":"\"Handle it alone in secret\""},{"id":"e","text":"Emergency 112"},{"id":"f","text":"\"Wait and hope it stops\""}],"bins":[{"id":"real","label":"A real route","valence":"pos"},{"id":"not","label":"Not a real route","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"},"relearn":"181, 1098 and 112 are real routes; posting, secrecy and waiting are not.","persona":"Counsellor","source":"helplines (verified)"},
  {"id":"mt-1225","cat":"rights-and-law","type":"sort","hook":"Sort each line into a green right or a red-flag claim.","items":[{"id":"a","text":"\"We both decide together\""},{"id":"b","text":"\"As the elder, I have the final say\""},{"id":"c","text":"\"You can stop and I'll respect it\""},{"id":"d","text":"\"You can't say no to me now\""},{"id":"e","text":"\"Asking each time is care\""},{"id":"f","text":"\"You owe me for the gifts\""}],"bins":[{"id":"green","label":"Green right","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Equal say, respecting a stop and asking each time are green; final-say and 'owe me' are red.","persona":"any","source":"green vs red rights"},
  {"id":"mt-1226","cat":"rights-and-law","type":"sort","hook":"Sort each statement about the law as true or false.","items":[{"id":"a","text":"India's age of consent is 18"},{"id":"b","text":"\"Marriage cancels the right to refuse\""},{"id":"c","text":"Disclosures route to real help"},{"id":"d","text":"\"The age law is just a formality\""},{"id":"e","text":"A survivor is never to blame"},{"id":"f","text":"\"No help once time passes\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"Age of consent 18, real help and no blame are true; the rest are false.","persona":"Counsellor","source":"law true/false (verified)"},
  {"id":"mt-1227","cat":"rights-and-law","type":"sort","hook":"Sort who can help in India by who they're for.","items":[{"id":"a","text":"Anyone under 18"},{"id":"b","text":"A woman needing help"},{"id":"c","text":"An emergency right now"},{"id":"d","text":"A woman in distress, second line"},{"id":"e","text":"Someone to confide in"},{"id":"f","text":"A serious, non-urgent worry"}],"bins":[{"id":"helpline","label":"A helpline","valence":"neutral"},{"id":"person","label":"A trusted person","valence":"pos"}],"key":{"a":"helpline","b":"helpline","c":"helpline","d":"helpline","e":"person","f":"person"},"relearn":"181 / 1091, 112 and 1098 are helplines; a counsellor or trusted adult is a person.","persona":"Counsellor","source":"helplines vs people (verified)"},
  {"id":"mt-1228","cat":"rights-and-law","type":"spot","hook":"Spot the two lines that deny someone their rights (the red flags).","scene":[{"id":"a","text":"\"You can stop whenever you want.\"","trick":false},{"id":"b","text":"\"We're together, so you can't refuse anymore.\"","trick":true},{"id":"c","text":"\"It's okay, we'll check in as we go.\"","trick":false},{"id":"d","text":"\"You started it, so it's too late to stop.\"","trick":true},{"id":"e","text":"\"Your no is fine with me, always.\"","trick":false}],"why":"'You can't refuse' and 'too late to stop' both deny a right that never expires.","persona":"any","source":"rights-denying lines","relearn":"'You can't refuse' and 'too late to stop' are red flags; your right to stop never expires."},
  {"id":"mt-1229","cat":"rights-and-law","type":"spot","hook":"Spot the two responses that blame a survivor (the red flags).","scene":[{"id":"a","text":"\"I believe you, and it's not your fault.\"","trick":false},{"id":"b","text":"\"What were you even wearing?\"","trick":true},{"id":"c","text":"\"Let's reach a helpline together.\"","trick":false},{"id":"d","text":"\"You must have led them on.\"","trick":true},{"id":"e","text":"\"I'm here for you, at your pace.\"","trick":false}],"why":"'What were you wearing' and 'you led them on' both wrongly shift blame to the survivor.","persona":"Sneha","source":"victim-blaming lines","relearn":"'What were you wearing' and 'you led them on' blame a survivor; harm is never their fault."},
  {"id":"mt-1230","cat":"rights-and-law","type":"spot","hook":"Spot the two false claims about the law (the red flags).","scene":[{"id":"a","text":"India's age of consent is 18.","trick":false},{"id":"b","text":"\"Marriage means you can never say no.\"","trick":true},{"id":"c","text":"A disclosure routes to real help.","trick":false},{"id":"d","text":"\"After time passes, no help is possible.\"","trick":true},{"id":"e","text":"A survivor is never to blame.","trick":false}],"why":"'Marriage means never saying no' and 'no help after time' are false.","persona":"Counsellor","source":"law true/false (verified)","relearn":"'Marriage means no refusing' and 'no help later' are false; age of consent is 18."},
  {"id":"mt-1231","cat":"rights-and-law","type":"spot","hook":"Spot the two 'help' suggestions that aren't real safe routes (the red flags).","scene":[{"id":"a","text":"\"Tell a trusted adult.\"","trick":false},{"id":"b","text":"\"Just post it on social media for revenge.\"","trick":true},{"id":"c","text":"\"Reach Childline 1098.\"","trick":false},{"id":"d","text":"\"Keep it a total secret and handle it alone.\"","trick":true},{"id":"e","text":"\"Call Women Helpline 181.\"","trick":false}],"why":"Posting for revenge and staying silent alone aren't safe routes; the real ones are 1098 / 181 / a trusted adult.","persona":"Counsellor","source":"real vs fake routes (verified)","relearn":"Posting for revenge or staying silent aren't safe routes; reach 1098, 181, or a trusted adult."},
  {"id":"mt-1232","cat":"rights-and-law","type":"spot","hook":"Spot the two lines that treat a relationship as a standing yes (the red flags).","scene":[{"id":"a","text":"\"Let's both check we're up for it.\"","trick":false},{"id":"b","text":"\"We're dating, so I don't need to ask.\"","trick":true},{"id":"c","text":"\"You can change your mind anytime.\"","trick":false},{"id":"d","text":"\"You already said yes once, so it's settled.\"","trick":true},{"id":"e","text":"\"I'll always respect a no.\"","trick":false}],"why":"'I don't need to ask' and 'you said yes once' both wrongly treat a relationship as a standing yes.","persona":"any","source":"standing-yes lines","relearn":"'I don't need to ask' and 'you said yes once' wrongly treat a relationship as a standing yes."},
  {"id":"mt-1233","cat":"rights-and-law","type":"spot","hook":"Spot the two lines that misuse 'the law' to pressure someone (the red flags).","scene":[{"id":"a","text":"\"The law protects you, so tell someone.\"","trick":false},{"id":"b","text":"\"No one will believe you, so don't bother.\"","trick":true},{"id":"c","text":"\"Helplines are on your side.\"","trick":false},{"id":"d","text":"\"Report me and you'll be in trouble too.\"","trick":true},{"id":"e","text":"\"You have every right to get help.\"","trick":false}],"why":"'No one will believe you' and 'you'll be in trouble too' are threats to silence you.","persona":"Counsellor","source":"silencing threats","relearn":"'No one will believe you' and 'you'll be in trouble too' are threats to silence you."},
  {"id":"mt-1234","cat":"rights-and-law","type":"spot","hook":"Spot the two 'owe me' lines that fake an obligation (the red flags).","scene":[{"id":"a","text":"\"There's no debt; you can always stop.\"","trick":false},{"id":"b","text":"\"After all I spent on you, you owe me.\"","trick":true},{"id":"c","text":"\"We only go on if we both want to.\"","trick":false},{"id":"d","text":"\"You said yes before, so you owe me now.\"","trick":true},{"id":"e","text":"\"Your choice matters every single time.\"","trick":false}],"why":"'You owe me' for spending and for a past yes both fake an obligation; intimacy is never owed.","persona":"any","source":"owes-framing lines","relearn":"'You owe me' for spending or a past yes fakes an obligation; intimacy is never owed."},
  {"id":"mt-1235","cat":"rights-and-law","type":"spot","hook":"Spot the two lines that pressure an under-18 instead of protecting them (the red flags).","scene":[{"id":"a","text":"\"You're under 18, let's tell a trusted adult.\"","trick":false},{"id":"b","text":"\"Age is just a number, no one needs to know.\"","trick":true},{"id":"c","text":"\"The law is here to keep you safe.\"","trick":false},{"id":"d","text":"\"Prove you're grown-up; keep it secret.\"","trick":true},{"id":"e","text":"\"You can step back and get help anytime.\"","trick":false}],"why":"'Age is just a number' and 'prove you're grown-up, keep it secret' pressure a minor.","persona":"Counsellor","source":"under-18 pressure lines","relearn":"Those two lines pressure a minor; under 18, tell a trusted adult and get help."},
  {"id":"mt-1236","cat":"rights-and-law","type":"role-play","hook":"Say it: your partner claims that once things start, you can't back out.","setup":"They say, 'You already started, you can't stop now.' What do you say?","yourLine":[{"text":"\"I can stop at any moment, and I'm stopping now.\"","best":true},{"text":"\"I guess... if you say I have to keep going.\""}],"persona":"any","source":"right to stop","relearn":"You can stop at any moment; 'I'm stopping now' is always reason enough."},
  {"id":"mt-1237","cat":"rights-and-law","type":"role-play","hook":"Say it: a partner insists being together cancels your right to say no.","setup":"They say, 'We're together, so you can't refuse me.' What do you say?","yourLine":[{"text":"\"Being together doesn't cancel my no; I still choose, every time.\"","best":true},{"text":"\"Maybe you're right that I can't say no anymore.\""}],"persona":"any","source":"relationship not consent","relearn":"Being together never cancels your no; you choose every time."},
  {"id":"mt-1238","cat":"rights-and-law","type":"role-play","hook":"Say it: a friend whispers a disclosure and waits for your reaction.","setup":"Your friend says, 'Something happened to me and I feel like it's my fault.' What do you say?","yourLine":[{"text":"\"I believe you, it's not your fault, and we can get help together.\"","best":true},{"text":"\"Are you sure you didn't do something to cause it?\""}],"persona":"Sneha","source":"disclosure / no blame","relearn":"Believe a friend, say it's not their fault, and help them get support."},
  {"id":"mt-1239","cat":"rights-and-law","type":"role-play","hook":"Say it: someone older is pressuring you, an under-18, to keep a secret.","setup":"They say, 'Don't tell anyone, this stays between us.' What do you say?","yourLine":[{"text":"\"No, I'm telling a trusted adult; the law protects me here.\"","best":true},{"text":"\"Okay, I won't tell anyone about it.\""}],"persona":"Vijay","source":"POCSO / tell an adult (verified)","relearn":"Under 18, the law protects you; tell a trusted adult instead of keeping a secret."},
  {"id":"mt-1240","cat":"rights-and-law","type":"role-play","hook":"Say it: a partner sulks and says stopping means you owe them.","setup":"They say, 'Fine, but you owe me for stopping.' What do you say?","yourLine":[{"text":"\"I owe nothing for stopping; my no isn't a debt.\"","best":true},{"text":"\"Sorry, I'll make it up to you somehow.\""}],"persona":"any","source":"no owes framing","relearn":"You owe nothing for stopping; your no is never a debt."},
  {"id":"mt-1241","cat":"rights-and-law","type":"role-play","hook":"Say it: you want to reach a helpline but feel embarrassed.","setup":"Your friend asks, 'Are you really going to call a helpline?' What do you say?","yourLine":[{"text":"\"Yes, reaching out is strength, and they're on your side.\"","best":true},{"text":"\"No, it's probably too embarrassing to call.\""}],"persona":"any","source":"reaching out is strength","relearn":"Reaching a helpline is strength, not embarrassment; they're on your side."},
  {"id":"mt-1242","cat":"rights-and-law","type":"role-play","hook":"Say it: a partner threatens to expose you unless you go further.","setup":"They say, 'Do this or I'll tell everyone.' What do you say?","yourLine":[{"text":"\"That's a threat, not love; my answer is still no.\"","best":true},{"text":"\"Please don't tell anyone, I'll do what you want.\""}],"persona":"Sneha","source":"coercion / refuse","relearn":"A threat to expose you isn't love; your no still stands."},
  {"id":"mt-1243","cat":"rights-and-law","type":"role-play","hook":"Say it: a partner says couples never need to ask each time.","setup":"They say, 'Real couples don't check in, just go for it.' What do you say?","yourLine":[{"text":"\"Checking in each time is how I show respect; let's keep doing it.\"","best":true},{"text":"\"Okay, I'll stop asking if that's what couples do.\""}],"persona":"Vijay","source":"ongoing consent","relearn":"Real couples still check in each time; consent is ongoing, not assumed."},
  {"id":"mt-1244","cat":"rights-and-law","type":"sort","hook":"Sort each: does consent still need to be asked, or is it a 'no need' myth?","items":[{"id":"a","text":"Long-term partners, tonight"},{"id":"b","text":"\"We're engaged, so it's automatic\""},{"id":"c","text":"A married couple, every time"},{"id":"d","text":"\"We did it before, so always yes\""},{"id":"e","text":"After a yes, when one goes quiet"},{"id":"f","text":"\"We're dating, asking is silly\""}],"bins":[{"id":"ask","label":"Still ask","valence":"pos"},{"id":"myth","label":"A 'no need' myth","valence":"neg"}],"key":{"a":"ask","b":"myth","c":"ask","d":"myth","e":"ask","f":"myth"},"relearn":"No status, engaged, married or dating, is standing consent; ask each time.","persona":"any","source":"no status is consent"},
  {"id":"mt-1260","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You're both into it, but you realise you've never actually checked in out loud.","options":[{"text":"Pause and ask warmly if they're still happy with this","consequence":"You turn a guess into a shared, spoken yes.","outcome":"mutual","best":true},{"text":"Stay quiet and read their face only","consequence":"Faces can be misread; a spoken check-in makes it truly mutual."}],"debrief":"A mutual yes is one you can both hear, not one you assume.","relearn":"A spoken check-in turns a guess into a real, shared yes.","persona":"Vijay","source":"check in out loud"},
  {"id":"mt-1261","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. Your partner says 'maybe later, not right now.'","options":[{"text":"Say 'totally fine' and let it go fully","consequence":"You honour 'not now' as a complete answer.","outcome":"respected","best":true},{"text":"Ask again in five minutes to see if they changed","consequence":"'Not now' is a full answer; re-asking is pressure, not patience."}],"debrief":"'Not now' is a whole answer, not a countdown to yes.","relearn":"'Not now' is a complete answer; re-asking turns waiting into pressure.","persona":"any","source":"not now is an answer"},
  {"id":"mt-1262","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You're keen but genuinely can't tell if they are too.","options":[{"text":"Stop and ask how they're feeling about this","consequence":"Unsure means pause; you find out instead of guessing.","outcome":"clear","best":true},{"text":"Carry on and hope they'd speak up if unhappy","consequence":"Unsure means stop and ask; hoping isn't a shared yes."}],"debrief":"When you can't tell, the answer is ask, not assume.","relearn":"If you can't tell they're keen, stop and ask, never assume.","persona":"any","source":"unsure means ask"},
  {"id":"mt-1263","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. They said yes earlier, but now they've gone quiet and still.","options":[{"text":"Pause and gently check if they still want to","consequence":"You catch the change; an earlier yes isn't a now-yes.","outcome":"attuned","best":true},{"text":"Keep going because they already agreed","consequence":"Willingness can change; quiet and still means pause and check."}],"debrief":"An earlier yes never locks the present in place.","relearn":"An earlier yes isn't a now-yes; quiet and still means pause and check.","persona":"any","source":"earlier yes not ongoing"},
  {"id":"mt-1264","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You're really keen; your partner seems only mildly so.","options":[{"text":"Wait until you're both genuinely keen, or not at all","consequence":"You hold out for a real mutual yes, no rush.","outcome":"patient","best":true},{"text":"Treat mild interest as close enough","consequence":"Mild isn't the bar; wait for genuine shared enthusiasm."}],"debrief":"Half-keen isn't the bar; mutual enthusiasm is.","relearn":"Mild interest isn't enough; wait for genuine shared enthusiasm.","persona":"any","source":"half willing isnt the bar"},
  {"id":"mt-1265","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. Mid-way, you yourself stop feeling sure about this.","options":[{"text":"Say you'd like to slow down or stop for now","consequence":"You honour your own change; you owe no explanation.","outcome":"self-true","best":true},{"text":"Push through so you don't seem to flip-flop","consequence":"Your willingness can change too; you can pause anytime, no reason owed."}],"debrief":"Your own yes is reversible just as much as theirs.","relearn":"You can pause or stop anytime; your willingness can change too.","persona":"any","source":"your yes reversible too"},
  {"id":"mt-1266","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You like them a lot and want it to be a good first time for both.","options":[{"text":"Agree to go slow and keep checking with each other","consequence":"You build a shared pace you both actually want.","outcome":"shared","best":true},{"text":"Plan it all out to impress them, no check-ins","consequence":"A good time is shared and checked, not performed at someone."}],"debrief":"Good intimacy is co-created, not performed.","relearn":"A good time is built together with check-ins, not staged for one.","persona":"Arjun","source":"co-create not perform"},
  {"id":"mt-1267","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. They look unsure, then say 'okay, fine' in a flat voice.","options":[{"text":"Pause; 'okay fine' flatly isn't an eager yes","consequence":"You read past the word to the real feeling.","outcome":"attuned","best":true},{"text":"Take the word 'okay' at face value","consequence":"A flat 'fine' is going-along; check what they actually want."}],"debrief":"The word matters less than whether they mean it.","relearn":"A flat 'okay fine' is going-along, not an eager yes; pause and check.","persona":"any","source":"flat yes isnt enthusiasm"},
  {"id":"mt-1268","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You're enjoying it; you wonder if it's worth interrupting to check in.","options":[{"text":"Check in briefly; it keeps things mutual and warm","consequence":"A quick 'this good?' deepens trust, doesn't break it.","outcome":"mutual","best":true},{"text":"Stay silent so you don't break the flow","consequence":"Checking in is caring, not a mood-killer; it keeps it shared."}],"debrief":"Asking is part of intimacy, not an interruption to it.","relearn":"A quick mid-way check-in is caring and keeps it mutual, not awkward.","persona":"any","source":"checking in is caring"},
  {"id":"mt-1269","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. Things have started, and your partner says 'wait, can we stop?'","options":[{"text":"Stop right away and check they're okay","consequence":"You honour stop instantly; there's no 'too late'.","outcome":"respected","best":true},{"text":"Say you're nearly done, so finish first","consequence":"There's no point too late to stop; honour it the moment it's said."}],"debrief":"Either person can stop at any point, full stop.","relearn":"There's no 'too late to stop'; honour a stop the instant it's said.","persona":"any","source":"no too late to stop"},
  {"id":"mt-1270","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You both planned tonight, but they now seem tired and distracted.","options":[{"text":"Say there's no pressure and you're happy to just rest","consequence":"A plan isn't a promise; you keep it mutual.","outcome":"shared","best":true},{"text":"Remind them you both agreed earlier","consequence":"A plan isn't a debt; if they're not into it now, it waits."}],"debrief":"A plan to be intimate is never a binding promise.","relearn":"A plan isn't a promise; if they're not into it now, it can wait.","persona":"any","source":"plan isnt a promise"},
  {"id":"mt-1271","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You're long-distance and finally together; you've imagined this for months.","options":[{"text":"Check you're both still genuinely keen, here and now","consequence":"You let the real moment lead, not the fantasy.","outcome":"mutual","best":true},{"text":"Assume the build-up means you both must want it","consequence":"Waiting and wanting aren't the same; check the real here-and-now."}],"debrief":"Anticipation isn't agreement; the present moment decides.","relearn":"Build-up isn't a yes; check you're both genuinely keen right now.","persona":"any","source":"anticipation isnt agreement"},
  {"id":"mt-1272","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. They're keen but mention they're a little nervous about it.","options":[{"text":"Slow down and say there's all the time in the world","consequence":"You make room for nerves so the yes stays real.","outcome":"attuned","best":true},{"text":"Reassure once then keep the pace going","consequence":"Nerves need space, not a pep talk; slow down and keep checking."}],"debrief":"Keen and nervous together means go gently and keep checking.","relearn":"Make space for nerves; a real yes needs no rush.","persona":"Vijay","source":"keen but nervous"},
  {"id":"mt-1273","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You realise you assumed a yes for the next step without checking.","options":[{"text":"Pause and ask before moving to anything new","consequence":"You keep it specific; each step gets its own yes.","outcome":"clear","best":true},{"text":"Keep going since the earlier step was a yes","consequence":"A yes to one step isn't yes to the next; ask before each."}],"debrief":"Each new step needs its own willing yes.","relearn":"Yes to one step isn't yes to the next; check before each new thing.","persona":"any","source":"specific each step"},
  {"id":"mt-1274","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. Your friends keep asking if you two have 'done it' yet.","options":[{"text":"Decide together at your own pace, ignore the scoreboard","consequence":"You let your shared comfort lead, not peer pressure.","outcome":"shared","best":true},{"text":"Hurry things along so you have something to say","consequence":"A real yes is set by you both, never by friends' timelines."}],"debrief":"Your pace is yours and your partner's, no one else's.","relearn":"Set your own shared pace; peer pressure never decides intimacy.","persona":"any","source":"ignore the scoreboard"},
  {"id":"mt-1275","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You'd love to, but sense your partner is just trying to please you.","options":[{"text":"Say you only want it if they truly do, no pressure","consequence":"You free them to be honest; that protects the mutual yes.","outcome":"mutual","best":true},{"text":"Accept their yes since they did say it","consequence":"A yes to please isn't a real yes; invite them to be honest."}],"debrief":"You can protect their honesty as much as your own.","relearn":"A yes to please isn't real; invite them to be honest, no pressure.","persona":"Arjun","source":"yes to please isnt real"},
  {"id":"mt-1276","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. Halfway, you both start laughing because something felt awkward.","options":[{"text":"Laugh together, check you're both still good, carry on","consequence":"You keep it light and shared; awkward is normal.","outcome":"warm","best":true},{"text":"Get embarrassed and rush to seem smooth","consequence":"Awkward moments are normal; checking in together keeps it mutual."}],"debrief":"Real intimacy has awkward bits; warmth carries them.","relearn":"Awkward moments are normal; laughing and checking in keeps it mutual.","persona":"any","source":"awkward is normal"},
  {"id":"mt-1277","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. They say 'I'm not sure, let me think.' You're already keen.","options":[{"text":"Say take all the time you need, no rush at all","consequence":"You let their 'thinking' be real, not a polite no to override.","outcome":"respected","best":true},{"text":"Gently nudge them toward deciding now","consequence":"'Let me think' deserves space, not a nudge; wait for a free yes."}],"debrief":"Space to think is part of a freely given yes.","relearn":"'Let me think' deserves real space; never nudge toward a quick yes.","persona":"any","source":"space to think"},
  {"id":"mt-1278","cat":"the-mutual-zone","type":"branch","hook":"The Mutual Zone. You stop mid-way to check, and they smile and say 'yes, definitely.'","options":[{"text":"Smile back and carry on with that clear yes","consequence":"You acted on a real, enthusiastic, ongoing yes.","outcome":"mutual","best":true},{"text":"Feel silly for having paused to ask","consequence":"Pausing to confirm is the right move; never feel silly for it."}],"debrief":"A check-in that gets an eager yes is intimacy at its best.","relearn":"Pausing to confirm is the right move; an eager yes is the green light.","persona":"any","source":"the win is a shared yes"},
  {"id":"mt-1279","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. You want to invite a genuine, pressure-free yes.","setup":"Make honesty easy. Say:","yourLine":[{"text":"\"I'd love to, but only if you're really feeling it too.\"","best":true},{"text":"\"So... are we doing this or not?\""}],"relearn":"'Only if you're feeling it too' keeps the yes free and mutual.","persona":"Vijay","source":"invite a free yes"},
  {"id":"mt-1280","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. You sense your partner slowing down and want to check in.","setup":"Be gentle and open. Say:","yourLine":[{"text":"\"Want to slow down or take a break? I'm happy either way.\"","best":true},{"text":"\"You okay? We can keep going.\""}],"relearn":"Offering to slow down, happy either way, keeps it truly mutual.","persona":"any","source":"offer to slow down"},
  {"id":"mt-1281","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. Your partner checks in on you and you want to answer honestly.","setup":"Tell the truth, kindly. Say:","yourLine":[{"text":"\"Honestly I'd rather just cuddle tonight, if that's okay.\"","best":true},{"text":"\"It's fine, let's just keep going.\""}],"relearn":"An honest 'I'd rather not tonight' is yours to say, anytime.","persona":"any","source":"answer honestly"},
  {"id":"mt-1282","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. You want to confirm before moving to a new step.","setup":"Ask clearly and warmly. Say:","yourLine":[{"text":"\"Is this okay? We only go further if you want to.\"","best":true},{"text":"\"You'd tell me to stop, right?\""}],"relearn":"'We only go further if you want to' keeps each step a shared yes.","persona":"Arjun","source":"confirm each step"},
  {"id":"mt-1283","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. They paused to ask if you're sure, and you genuinely are.","setup":"Give a clear, warm yes. Say:","yourLine":[{"text":"\"Yes, I really want this, and thanks for checking.\"","best":true},{"text":"\"I mean, I guess so.\""}],"relearn":"A clear 'yes, I really want this' is what an enthusiastic yes sounds like.","persona":"any","source":"a clear enthusiastic yes"},
  {"id":"mt-1284","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. You want to make stopping feel safe at any point.","setup":"Set the tone early. Say:","yourLine":[{"text":"\"At any point, if either of us wants to stop, we just stop.\"","best":true},{"text":"\"Let's just see how far we get.\""}],"relearn":"Naming that either can stop anytime makes the whole thing safer.","persona":"any","source":"either can stop anytime"},
  {"id":"mt-1285","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. Your partner seemed a bit off, and you want to open the door.","setup":"Check in without pressure. Say:","yourLine":[{"text":"\"You seem a little quiet, want to pause? No pressure.\"","best":true},{"text":"\"You're fine, right? Let's carry on.\""}],"relearn":"Noticing 'you seem quiet' and offering a pause reads cues with care.","persona":"any","source":"read and check"},
  {"id":"mt-1286","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. You realise you'd rather wait, and want to say so kindly.","setup":"Be honest and warm. Say:","yourLine":[{"text":"\"I'm really into you, I'd just like to wait a bit longer.\"","best":true},{"text":"\"Maybe, I don't know, whatever you want.\""}],"relearn":"'I'm into you and I'd like to wait' is a kind, clear boundary.","persona":"Sneha","source":"say you want to wait"},
  {"id":"mt-1287","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. You want to thank a partner for keeping it mutual.","setup":"Affirm the dynamic. Say:","yourLine":[{"text":"\"I love that we keep checking with each other, it feels good.\"","best":true},{"text":"\"You don't have to keep asking, you know.\""}],"relearn":"Naming that mutual check-ins feel good reinforces a healthy dynamic.","persona":"any","source":"thank the dynamic"},
  {"id":"mt-1288","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. Your partner says they're nervous; you want to reassure honestly.","setup":"Make room for the nerves. Say:","yourLine":[{"text":"\"We don't have to do anything, let's go at your pace.\"","best":true},{"text":"\"Don't be nervous, you'll be fine.\""}],"relearn":"'We don't have to, let's go at your pace' makes a yes truly free.","persona":"Vijay","source":"make room for nerves"},
  {"id":"mt-1289","cat":"the-mutual-zone","type":"role-play","hook":"The Mutual Zone. You want to reciprocate a clear yes your partner just gave.","setup":"Match their clarity. Say:","yourLine":[{"text":"\"I really want to too, and we can stop whenever.\"","best":true},{"text":"\"Cool, let's go then.\""}],"relearn":"Matching a clear yes, with a stop always open, makes it fully mutual.","persona":"any","source":"reciprocate clearly"},
  {"id":"mt-1290","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: in the Mutual Zone, the goal is never to talk someone into it, it's to find a yes you both already feel. Notice that?","prompt":"What do you think?","options":["Yes","Found, not made","Big shift"],"affirm":"A mutual yes is one you both already feel, never one you talk into being.","relearn":"The goal is a yes you both already feel, never one you persuade.","persona":"any","source":"found not made"},
  {"id":"mt-1291","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: how does it feel to know you can pause at any second and your partner would be glad you spoke up?","prompt":"What do you think?","options":["Safer","Freeing","Closer"],"affirm":"That freedom to pause anytime is exactly what lets both of you relax into it.","relearn":"Knowing you can pause anytime, welcomed, is what makes it feel safe.","persona":"any","source":"freedom to pause"},
  {"id":"mt-1292","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: checking in mid-way might feel awkward at first, but does it actually make intimacy better?","prompt":"What do you think?","options":["Yes","Better and warmer","I'd try it"],"affirm":"Checking in is caring, and care is exactly what makes intimacy good, not just safe.","relearn":"Mid-way check-ins make intimacy better and warmer, never worse.","persona":"any","source":"check in makes it better"},
  {"id":"mt-1293","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: if only one of you is really keen, what does the Mutual Zone say the answer is?","prompt":"What do you think?","options":["Wait","Stop, don't convince","Both or neither"],"affirm":"If only one is keen, the answer is wait or stop, never convince. Mutual or nothing.","relearn":"If only one is keen, the answer is wait or stop, never persuade.","persona":"any","source":"one keen means wait"},
  {"id":"mt-1294","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: an earlier yes isn't a forever yes. How does it feel knowing you can both change your mind anytime?","prompt":"What do you think?","options":["Reassuring","Honest","Free"],"affirm":"Either of you can change your mind anytime; that's not a problem, it's the whole point.","relearn":"An earlier yes isn't forever; you can both change your mind anytime.","persona":"any","source":"change your mind anytime"},
  {"id":"mt-1295","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: there's a real difference between someone going along with it and someone genuinely wanting it. Can you feel that difference?","prompt":"What do you think?","options":["Yes","Clearly","Worth watching for"],"affirm":"Going along and genuinely wanting feel different, and the mutual zone waits for the wanting.","relearn":"Going along isn't wanting; the mutual zone waits for genuine wanting.","persona":"any","source":"going along vs wanting"},
  {"id":"mt-1296","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: a partner who's glad to hear your 'not tonight' is showing you something. What is it?","prompt":"What do you think?","options":["Respect","Care","A good sign"],"affirm":"A partner glad to hear your 'not tonight' is showing real respect, and that's worth a lot.","relearn":"A partner who welcomes your 'no' is showing real respect.","persona":"Sneha","source":"welcomes your no"},
  {"id":"mt-1297","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: nervous and excited can sit together. Does naming your nerves to a partner make it easier?","prompt":"What do you think?","options":["Yes","It would help","Honesty helps"],"affirm":"Naming your nerves lets a good partner slow down with you, and that makes the yes more real.","relearn":"Naming nerves lets a good partner slow down; honesty makes the yes real.","persona":"any","source":"name your nerves"},
  {"id":"mt-1298","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: a quick 'still good?' mid-moment keeps both of you on the same page. See the value?","prompt":"What do you think?","options":["Yes","Same page","Quick check"],"affirm":"A light 'still good?' mid-moment is how two people stay tuned in to each other, not guessing.","relearn":"A quick mid-moment check keeps both partners on the same page.","persona":"any","source":"check in mid-way"},
  {"id":"mt-1299","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: there's no rush and no scoreboard. How does it feel to let your own pace decide?","prompt":"What do you think?","options":["Calmer","Freeing","Right"],"affirm":"Letting your own shared pace decide, with no rush or scoreboard, is how it should feel.","relearn":"No rush, no scoreboard; your own shared pace decides.","persona":"any","source":"no scoreboard"},
  {"id":"mt-1300","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: the best moments are the ones you both choose, freely, again and again. Sit with that.","prompt":"What do you think?","options":["Yes","Both, freely","Love that"],"affirm":"The best intimacy is chosen by both, freely and again and again, never won or assumed.","relearn":"The best moments are freely chosen by both, again and again.","persona":"any","source":"both choose freely"},
  {"id":"mt-1301","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: asking 'is this good?' isn't a sign something's wrong, it's a sign you care. Agree?","prompt":"What do you think?","options":["Agree","Care, not worry","Makes sense"],"affirm":"'Is this good?' isn't worry, it's care, and care is what keeps intimacy mutual.","relearn":"Asking 'is this good?' is a sign of care, not of something wrong.","persona":"any","source":"asking is care"},
  {"id":"mt-1302","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: you never owe a yes for the next time just because there was one last time. How's that land?","prompt":"What do you think?","options":["True","Each time is new","Reassuring"],"affirm":"Last time never books this time; every time gets its own free, mutual yes.","relearn":"A yes last time never owes a yes this time; each time is new.","persona":"any","source":"each time is new"},
  {"id":"mt-1303","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: when you both feel free to stop, you're both freer to enjoy. Does that ring true?","prompt":"What do you think?","options":["Yes","Free to stop, free to enjoy","Rings true"],"affirm":"Being free to stop is what makes you free to enjoy; the two go together.","relearn":"Being free to stop is what lets both of you actually relax and enjoy.","persona":"any","source":"free to stop free to enjoy"},
  {"id":"mt-1304","cat":"the-mutual-zone","type":"reflect","hook":"Lensy: a quiet 'are you sure?' from your partner is a gift, not a doubt. How do you see it?","prompt":"What do you think?","options":["A gift","Caring","I'd welcome it"],"affirm":"A partner's 'are you sure?' is care for you, a gift that keeps the yes honest.","relearn":"A partner's 'are you sure?' is care, not doubt; welcome it.","persona":"any","source":"are you sure is a gift"},
  {"id":"mt-1305","cat":"the-mutual-zone","type":"sort","hook":"Sort: a genuine Mutual-Zone move, or not?","items":[{"id":"a","text":"Checking you're both still keen mid-way"},{"id":"b","text":"Talking a reluctant partner round"},{"id":"c","text":"Stopping the second they ask"},{"id":"d","text":"Treating one yes as a yes forever"},{"id":"e","text":"Going slow because they're nervous"},{"id":"f","text":"Taking a flat 'fine' as enthusiasm"}],"bins":[{"id":"mutual","label":"Mutual move","valence":"pos"},{"id":"no","label":"Not mutual","valence":"neg"}],"key":{"a":"mutual","b":"no","c":"mutual","d":"no","e":"mutual","f":"no"},"relearn":"Checking, stopping and going slow are mutual; persuading or 'yes forever' aren't.","persona":"any","source":"mutual move or not"},
  {"id":"mt-1306","cat":"the-mutual-zone","type":"sort","hook":"Sort each into who keeps the yes mutual, or who breaks it.","items":[{"id":"a","text":"'Only if you want to as well'"},{"id":"b","text":"'You said yes already, no take-backs'"},{"id":"c","text":"'We can stop whenever'"},{"id":"d","text":"'Come on, don't make it weird'"},{"id":"e","text":"'How are you feeling about this?'"},{"id":"f","text":"'Just relax, you'll enjoy it'"}],"bins":[{"id":"keeps","label":"Keeps it mutual","valence":"pos"},{"id":"breaks","label":"Breaks it","valence":"neg"}],"key":{"a":"keeps","b":"breaks","c":"keeps","d":"breaks","e":"keeps","f":"breaks"},"relearn":"Lines that invite and check keep it mutual; lines that push or dismiss break it.","persona":"any","source":"lines that keep or break"},
  {"id":"mt-1307","cat":"the-mutual-zone","type":"sort","hook":"Sort: is this a green-light moment, or a pause-and-check one?","items":[{"id":"a","text":"Both grinning and leaning in"},{"id":"b","text":"One has gone quiet and stiff"},{"id":"c","text":"A warm, clear 'yes, definitely'"},{"id":"d","text":"A flat 'I guess we can'"},{"id":"e","text":"Both relaxed and laughing together"},{"id":"f","text":"One keeps glancing at the door"}],"bins":[{"id":"go","label":"Green light","valence":"pos"},{"id":"pause","label":"Pause and check","valence":"uhoh"}],"key":{"a":"go","b":"pause","c":"go","d":"pause","e":"go","f":"pause"},"relearn":"Shared warmth and a clear yes are green; quiet, flat or distracted means pause.","persona":"any","source":"green or pause"},
  {"id":"mt-1308","cat":"the-mutual-zone","type":"sort","hook":"Sort what makes a yes mutual vs what makes it hollow.","items":[{"id":"a","text":"Both freely choosing it"},{"id":"b","text":"Said just to avoid an argument"},{"id":"c","text":"Both actively wanting it"},{"id":"d","text":"Given to keep them happy"},{"id":"e","text":"Checked again partway through"},{"id":"f","text":"Assumed from last time"}],"bins":[{"id":"real","label":"Truly mutual","valence":"pos"},{"id":"hollow","label":"Hollow yes","valence":"neg"}],"key":{"a":"real","b":"hollow","c":"real","d":"hollow","e":"real","f":"hollow"},"relearn":"Freely chosen, wanted and re-checked is mutual; said to please or assumed is hollow.","persona":"any","source":"mutual vs hollow"},
  {"id":"mt-1309","cat":"the-mutual-zone","type":"sort","hook":"Sort each response to 'I'd like to wait' as respecting it or overriding it.","items":[{"id":"a","text":"'Of course, no rush at all'"},{"id":"b","text":"'But we already planned this'"},{"id":"c","text":"'Thanks for telling me'"},{"id":"d","text":"'You're such a tease'"},{"id":"e","text":"'I'm glad you said so'"},{"id":"f","text":"'Just this once, then'"}],"bins":[{"id":"respect","label":"Respects it","valence":"pos"},{"id":"override","label":"Overrides it","valence":"neg"}],"key":{"a":"respect","b":"override","c":"respect","d":"override","e":"respect","f":"override"},"relearn":"Welcoming a 'wait' respects it; guilt, teasing or 'just once' overrides it.","persona":"any","source":"respond to a wait"},
  {"id":"mt-1310","cat":"the-mutual-zone","type":"sort","hook":"Sort: ongoing consent, or treating one yes as the whole night?","items":[{"id":"a","text":"Asking again before a new step"},{"id":"b","text":"'You agreed at the start'"},{"id":"c","text":"Noticing they've gone quiet and pausing"},{"id":"d","text":"Carrying on through their hesitation"},{"id":"e","text":"'Still good?' partway through"},{"id":"f","text":"Assuming the first yes covers everything"}],"bins":[{"id":"ongoing","label":"Ongoing","valence":"pos"},{"id":"once","label":"One-and-done","valence":"neg"}],"key":{"a":"ongoing","b":"once","c":"ongoing","d":"once","e":"ongoing","f":"once"},"relearn":"Re-asking and pausing keep consent ongoing; 'you already agreed' treats it as one-and-done.","persona":"any","source":"ongoing vs once"},
  {"id":"mt-1311","cat":"the-mutual-zone","type":"sort","hook":"Sort each into a shared yes or a one-sided push.","items":[{"id":"a","text":"Both deciding the pace together"},{"id":"b","text":"One steering the whole thing"},{"id":"c","text":"Pausing the moment one isn't sure"},{"id":"d","text":"Ignoring the other's hesitation"},{"id":"e","text":"Both free to say stop"},{"id":"f","text":"Only one allowed to set limits"}],"bins":[{"id":"shared","label":"Shared yes","valence":"pos"},{"id":"push","label":"One-sided push","valence":"neg"}],"key":{"a":"shared","b":"push","c":"shared","d":"push","e":"shared","f":"push"},"relearn":"Deciding together and both free to stop is shared; one steering or ignoring is a push.","persona":"any","source":"shared vs one-sided"},
  {"id":"mt-1312","cat":"the-mutual-zone","type":"spot","hook":"Spot the two lines that push instead of keeping it mutual.","scene":[{"id":"a","text":"'Only if you're feeling it too'","trick":false},{"id":"b","text":"'Don't make it weird, just go with it'","trick":true},{"id":"c","text":"'We can stop anytime, no problem'","trick":false},{"id":"d","text":"'You owe me after the date I planned'","trick":true},{"id":"e","text":"'How are you feeling right now?'","trick":false}],"why":"'Don't make it weird' and 'you owe me' are pressure; the others invite a free, mutual yes.","relearn":"Lines that guilt or pressure break the mutual zone; check-ins and offers to stop keep it.","persona":"any","source":"spot the push"},
  {"id":"mt-1313","cat":"the-mutual-zone","type":"spot","hook":"Spot the two moves that treat an earlier yes as forever.","scene":[{"id":"a","text":"Checking in again partway through","trick":false},{"id":"b","text":"'You said yes, so no stopping now'","trick":true},{"id":"c","text":"Pausing when they go quiet","trick":false},{"id":"d","text":"Carrying on after they pulled back","trick":true},{"id":"e","text":"Asking before each new step","trick":false}],"why":"'No stopping now' and carrying on after they pulled back ignore that a yes is reversible.","relearn":"An earlier yes is reversible; re-checking and pausing keep it ongoing.","persona":"any","source":"spot the forever-yes"},
  {"id":"mt-1314","cat":"the-mutual-zone","type":"spot","hook":"Spot the two signs this yes isn't really mutual.","scene":[{"id":"a","text":"Both grinning and relaxed","trick":false},{"id":"b","text":"A flat 'fine, whatever'","trick":true},{"id":"c","text":"A warm 'yes, I want to'","trick":false},{"id":"d","text":"Going along while glancing away","trick":true},{"id":"e","text":"Both leaning in together","trick":false}],"why":"A flat 'whatever' and going-along while looking away are reluctance, not a mutual yes.","relearn":"Read for genuine, shared enthusiasm; flat or going-along means pause and check.","persona":"any","source":"spot the not-mutual"},
  {"id":"mt-1315","cat":"the-mutual-zone","type":"spot","hook":"Spot the two responses that don't honour 'can we slow down?'","scene":[{"id":"a","text":"'Of course, let's slow right down'","trick":false},{"id":"b","text":"'We're nearly there though'","trick":true},{"id":"c","text":"'Thanks for saying, no rush'","trick":false},{"id":"d","text":"'Come on, don't stop now'","trick":true},{"id":"e","text":"'Want to take a break?'","trick":false}],"why":"'We're nearly there' and 'don't stop now' override a slow-down; the rest honour it instantly.","relearn":"A 'slow down' is honoured the moment it's said, never bargained with.","persona":"any","source":"spot the override"},
  {"id":"mt-1316","cat":"the-mutual-zone","type":"spot","hook":"Spot the two lines that try to win a yes rather than share one.","scene":[{"id":"a","text":"'I only want to if you do'","trick":false},{"id":"b","text":"'Everyone our age has by now'","trick":true},{"id":"c","text":"'No pressure either way'","trick":false},{"id":"d","text":"'If you cared, you'd want to'","trick":true},{"id":"e","text":"'We can take this as slow as you like'","trick":false}],"why":"'Everyone has' and 'if you cared you'd want to' are pressure to win a yes, not share one.","relearn":"The win is a shared yes; comparison and guilt are attempts to manufacture one.","persona":"any","source":"spot the won-yes"},
  {"id":"mt-1317","cat":"the-mutual-zone","type":"spot","hook":"Spot the two moments where the right move is to pause and check.","scene":[{"id":"a","text":"Both laughing and leaning in","trick":false},{"id":"b","text":"They suddenly go tense and silent","trick":true},{"id":"c","text":"A clear, eager 'yes' from both","trick":false},{"id":"d","text":"They say 'I guess' and look away","trick":true},{"id":"e","text":"Both relaxed and checking in","trick":false}],"why":"Going tense and silent, or a reluctant 'I guess', are cues to pause and check, not push on.","relearn":"Tensing up or a reluctant 'I guess' means pause and check; shared ease is a green light.","persona":"any","source":"spot the pause cue"},
  {"id":"mt-1318","cat":"the-mutual-zone","type":"spot","hook":"Spot the two things that mean the moment isn't shared yet.","scene":[{"id":"a","text":"Both clearly into it","trick":false},{"id":"b","text":"Only one is keen, the other unsure","trick":true},{"id":"c","text":"Both checking with each other","trick":false},{"id":"d","text":"One pushing past the other's hesitation","trick":true},{"id":"e","text":"Both free to stop anytime","trick":false}],"why":"Only one keen, or one pushing past hesitation, means it's not shared; wait, don't convince.","relearn":"If only one is keen, the answer is wait or stop, never convince.","persona":"any","source":"spot the not-shared"},
  {"id":"mt-1319","cat":"the-mutual-zone","type":"strike-rewrite","hook":"\"In the Mutual Zone, the goal is to get them to a yes.\"","myth":{"un":"The goal is to bring your partner round to a yes.","re":"The goal is a yes you both already feel; intimacy is shared, never won.","why":"A yes you steer toward isn't freely given."},"relearn":"The win is a shared yes you both feel, never a yes you steer toward.","persona":"any","source":"shared not won"},
  {"id":"mt-1320","cat":"the-mutual-zone","type":"strike-rewrite","hook":"\"Once things are going well, you don't need to keep checking.\"","myth":{"un":"If it's going well, checking in is unnecessary.","re":"Mutual consent is ongoing; willingness can change, so keep checking in.","why":"A good start doesn't guarantee a good middle."},"relearn":"Mutual consent is ongoing; keep checking in even when it's going well.","persona":"any","source":"keep checking in"},
  {"id":"mt-1321","cat":"the-mutual-zone","type":"strike-rewrite","hook":"\"If they're a bit unsure, you just need to reassure them into it.\"","myth":{"un":"An unsure partner just needs reassuring until they agree.","re":"If they're unsure, the move is to wait, not to talk them into it.","why":"Talking someone past their doubt removes the free part of the yes."},"relearn":"An unsure partner means wait, not persuade; reassuring-into-it isn't consent.","persona":"any","source":"unsure means wait"},
  {"id":"mt-1334","cat":"the-mutual-zone","type":"strike-rewrite","hook":"\"Stopping partway makes you a tease, so you should finish what you started.\"","myth":{"un":"Stopping partway makes you a tease; you should finish.","re":"Either person can stop at any point with no explanation owed; there's no 'too late'.","why":"A reversible yes means stopping is always allowed."},"relearn":"You can stop at any point, no explanation owed; there's no 'too late to stop'.","persona":"Sneha","source":"no too late"},
  {"id":"mt-1322","cat":"the-mutual-zone","type":"strike-rewrite","hook":"\"Half-willing is basically willing, so it's fine to go ahead.\"","myth":{"un":"Half-willing is close enough to willing.","re":"Half-willing isn't the bar; wait for genuine, mutual enthusiasm.","why":"'Going along' isn't the same as wanting."},"relearn":"Half-willing isn't the bar; wait for genuine, mutual enthusiasm.","persona":"any","source":"half willing isnt the bar"},
  {"id":"mt-1323","cat":"the-mutual-zone","type":"strike-rewrite","hook":"\"Pausing to ask 'is this okay?' kills the moment.\"","myth":{"un":"Pausing to check in kills the moment.","re":"Checking in mid-way is caring, not awkward; it makes the moment better.","why":"Care deepens intimacy rather than interrupting it."},"relearn":"Checking in mid-way is caring, not a mood-killer; it makes it better.","persona":"any","source":"check in doesnt kill the mood"},
  {"id":"mt-1324","cat":"the-mutual-zone","type":"strike-rewrite","hook":"\"A yes last time means a yes this time.\"","myth":{"un":"Last time's yes carries over to this time.","re":"Each time needs its own willing yes; an earlier yes isn't an ongoing one.","why":"Willingness can change between any two moments."},"relearn":"Each time needs its own yes; last time's yes never books this time.","persona":"any","source":"each time its own yes"},
  {"id":"mt-1325","cat":"the-mutual-zone","type":"strike-rewrite","hook":"\"If you've gone this far, it's too late to stop.\"","myth":{"un":"Once you're far in, it's too late to stop.","re":"There is no point too late to stop; either person can stop at any moment.","why":"Consent stays reversible right to the end."},"relearn":"There's no 'too late to stop'; either person can stop at any moment.","persona":"any","source":"never too late"},
  {"id":"mt-1326","cat":"the-mutual-zone","type":"match","hook":"Match each Mutual-Zone move to what it sounds like.","pairs":[{"left":"Inviting a free yes","right":"'Only if you want to as well'"},{"left":"Checking in mid-way","right":"'Still good? We can pause'"},{"left":"Honouring a slow-down","right":"'Of course, no rush at all'"},{"left":"Naming the right to stop","right":"'Either of us can stop anytime'"},{"left":"Reciprocating a yes","right":"'I really want to too'"}],"relearn":"Mutual moves sound like invitations, check-ins and offers to stop, never pressure.","persona":"any","source":"move to its words"},
  {"id":"mt-1327","cat":"the-mutual-zone","type":"match","hook":"Match each FRIES quality to the Mutual-Zone habit that lives it out.","pairs":[{"left":"Enthusiastic","right":"Wait for both to genuinely want it"},{"left":"Reversible","right":"Stop the moment either says so"},{"left":"Ongoing","right":"Keep checking in throughout"},{"left":"Specific","right":"Ask again before a new step"},{"left":"Freely given","right":"Invite a yes with zero pressure"}],"relearn":"Each FRIES quality shows up as a real Mutual-Zone habit you can practise.","persona":"any","source":"fries to habit"},
  {"id":"mt-1328","cat":"the-mutual-zone","type":"match","hook":"Match each pushy line to the mutual line that replaces it.","pairs":[{"left":"'Don't make it weird'","right":"'No pressure either way'"},{"left":"'You owe me after tonight'","right":"'You never owe me anything'"},{"left":"'Everyone's done it by now'","right":"'We go at our own pace'"},{"left":"'You said yes already'","right":"'You can change your mind anytime'"},{"left":"'If you cared, you would'","right":"'I care however you feel'"}],"relearn":"Every pushy line has a mutual replacement that keeps the yes free.","persona":"any","source":"push to mutual swap"},
  {"id":"mt-1329","cat":"the-mutual-zone","type":"match","hook":"Match each cue you might notice to the caring response.","pairs":[{"left":"They've gone quiet","right":"'Want to pause for a sec?'"},{"left":"They seem nervous","right":"'We can go as slow as you like'"},{"left":"They give a clear, eager yes","right":"'I'm right there with you'"},{"left":"They say 'maybe later'","right":"'Totally fine, no rush'"},{"left":"They start to pull back","right":"'Let's stop, you okay?'"}],"relearn":"Reading a cue means meeting it with care, a pause, or a stop, never a push.","persona":"any","source":"cue to caring response"},
  {"id":"mt-1330","cat":"the-mutual-zone","type":"match","hook":"Match each phase of being together to the mutual habit that fits it.","pairs":[{"left":"Before anything starts","right":"Check you both actually want to"},{"left":"At each new step","right":"Ask before moving further"},{"left":"Partway through","right":"Notice cues and check in"},{"left":"If enthusiasm drops","right":"Pause and ask, no pressure"},{"left":"At any point at all","right":"Either can stop, no reason owed"}],"relearn":"A mutual yes is tended at every phase, from before it starts to the very end.","persona":"any","source":"phase to habit"},
  {"id":"mt-1331","cat":"the-mutual-zone","type":"match","hook":"Match each feeling to what it's telling you in the moment.","pairs":[{"left":"Both relaxed and grinning","right":"Green light, stay checked-in"},{"left":"A knot of 'I'm not sure'","right":"Pause and say so, no rush"},{"left":"Sensing they've gone tense","right":"Stop and gently check on them"},{"left":"Genuine, shared excitement","right":"A real, mutual yes"},{"left":"A quiet 'only to please them'","right":"Not mutual yet, slow down"}],"relearn":"Feelings are data; shared ease means go, any 'not sure' means pause and check.","persona":"any","source":"feeling to message"},
  {"id":"mt-1332","cat":"the-mutual-zone","type":"match","hook":"Match each myth about the Mutual Zone to the truth that corrects it.","pairs":[{"left":"'Get them to a yes'","right":"Find a yes you both already feel"},{"left":"'One yes covers the night'","right":"Keep checking; willingness can change"},{"left":"'Too far in to stop'","right":"Either can stop at any moment"},{"left":"'Half-willing is fine'","right":"Wait for genuine mutual enthusiasm"},{"left":"'Checking in kills the mood'","right":"Checking in is caring and warm"}],"relearn":"Every Mutual-Zone myth has a calmer, truer version that keeps consent shared.","persona":"any","source":"myth to truth"},
  {"id":"mt-1333","cat":"the-mutual-zone","type":"match","hook":"Match each shared moment to the habit that makes it mutual.","pairs":[{"left":"You're both keen but quiet","right":"Say it out loud so it's shared"},{"left":"They look a little nervous","right":"Slow down and make space"},{"left":"You're unsure how they feel","right":"Stop and ask, never guess"},{"left":"They give an eager yes","right":"Reciprocate clearly and warmly"},{"left":"One of you wants to stop","right":"Stop at once, no reason needed"}],"relearn":"Each shared moment has a mutual habit: speak it, slow it, ask it, match it, or stop it.","persona":"any","source":"moment to habit"},
  {"id":"mt-1350","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Being in a relationship means you've already consented.\"","myth":{"un":"Once you're together, consent is automatic.","re":"A relationship isn't standing consent; each time still needs a willing yes.","why":"Being a couple never replaces an actual yes."},"relearn":"A relationship is never automatic consent; each time needs a yes.","persona":"any","source":"FRIES / specific"},
  {"id":"mt-1351","cat":"what-consent-is","type":"strike-rewrite","hook":"\"If they don't push you away, that's a yes.\"","myth":{"un":"No resistance means they agreed.","re":"Consent is a clear willing yes, not the absence of resistance.","why":"People often freeze; not resisting isn't agreeing."},"relearn":"Not pushing away isn't a yes; only a willing yes is.","persona":"any","source":"FRIES / presence of yes"},
  {"id":"mt-1352","cat":"what-consent-is","type":"strike-rewrite","hook":"\"A yes over text means yes when you meet.\"","myth":{"un":"Agreeing earlier locks in a yes for later.","re":"Consent is ongoing; an earlier yes isn't a yes for the moment itself.","why":"Willingness can change between then and now."},"relearn":"An earlier yes isn't ongoing; check again in the moment.","persona":"Vijay","source":"FRIES / ongoing"},
  {"id":"mt-1353","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Flirting all evening counts as saying yes.\"","myth":{"un":"Flirting is the same as consenting.","re":"Flirting isn't consent; only a clear yes to the actual thing is.","why":"Enjoying someone's company isn't agreeing to anything more."},"relearn":"Flirting isn't consent; the real yes is to the actual thing.","persona":"any","source":"FRIES / specific"},
  {"id":"mt-1354","cat":"what-consent-is","type":"strike-rewrite","hook":"\"You can't withdraw consent once things have started.\"","myth":{"un":"Once it's begun, you can't change your mind.","re":"Consent is reversible at any point; you can stop after starting.","why":"There's no point where stopping stops being allowed."},"relearn":"You can withdraw consent anytime, even after things start.","persona":"Sneha","source":"FRIES / reversible"},
  {"id":"mt-1355","cat":"what-consent-is","type":"strike-rewrite","hook":"\"A sleepy or half-asleep yes is still a yes.\"","myth":{"un":"A drowsy yes still counts.","re":"Someone asleep or barely awake can't consent; wait for a clear, awake yes.","why":"Consent needs a clear, aware mind."},"relearn":"A half-asleep yes isn't consent; wait for a clear, awake one.","persona":"Counsellor","source":"incapacitation"},
  {"id":"mt-1356","cat":"what-consent-is","type":"strike-rewrite","hook":"\"If they agreed last time, they've agreed this time.\"","myth":{"un":"A yes last time carries over to today.","re":"Consent is needed every time; a past yes isn't this moment's yes.","why":"Each time is its own decision."},"relearn":"A past yes isn't this time's yes; consent is needed each time.","persona":"any","source":"FRIES / ongoing"},
  {"id":"mt-1357","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Lying to get a yes still gets you a real yes.\"","myth":{"un":"A yes you tricked out of someone still counts.","re":"Consent is informed; a yes built on a lie isn't real consent.","why":"You can only agree to what you actually know is true."},"relearn":"A yes won by lying isn't consent; honesty is part of it.","persona":"any","source":"FRIES / informed"},
  {"id":"mt-1358","cat":"what-consent-is","type":"strike-rewrite","hook":"\"A nervous, mumbled 'I guess' is good enough.\"","myth":{"un":"A hesitant 'I guess' counts as yes.","re":"A reluctant, unsure answer isn't enthusiastic consent; pause and check in.","why":"Hesitation is a sign to slow down, not go ahead."},"relearn":"A mumbled 'I guess' isn't a real yes; pause and check in.","persona":"any","source":"FRIES / enthusiastic"},
  {"id":"mt-1359","cat":"what-consent-is","type":"strike-rewrite","hook":"\"If they don't say the word 'no', it's allowed.\"","myth":{"un":"Without the word 'no', you're free to continue.","re":"Consent is a present yes; the missing word 'no' is never a green light.","why":"You wait for a yes, you don't proceed on a missing no."},"relearn":"A missing 'no' isn't a yes; wait for a real yes.","persona":"any","source":"FRIES / presence of yes"},
  {"id":"mt-1360","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Buying gifts or dinner earns a yes.\"","myth":{"un":"Spending on someone means they owe a yes.","re":"No gift or favour buys consent; only a free, willing yes is consent.","why":"Intimacy is never owed in return for anything."},"relearn":"Nothing buys a yes; consent is freely given, never owed.","persona":"any","source":"FRIES / freely given"},
  {"id":"mt-1361","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Marriage means consent is permanent.\"","myth":{"un":"Marriage is a standing yes forever.","re":"Marriage isn't standing consent; a willing yes is needed every time.","why":"No relationship status removes the right to say no."},"relearn":"Marriage isn't a permanent yes; each time still needs consent.","persona":"Counsellor","source":"FRIES / ongoing"},
  {"id":"mt-1362","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Yes to kissing is yes to anything after.\"","myth":{"un":"Agreeing to one step means agreeing to the next.","re":"Consent is specific; a yes to one thing isn't a yes to what follows.","why":"Each new step needs its own willing yes."},"relearn":"A yes to one step isn't a yes to the next; ask again.","persona":"any","source":"FRIES / specific"},
  {"id":"mt-1363","cat":"what-consent-is","type":"strike-rewrite","hook":"\"They were laughing, so they must be into it.\"","myth":{"un":"A smile or laugh proves they consent.","re":"A laugh isn't a yes; people smile when nervous too. Check with words.","why":"Only a clear, willing answer tells you for sure."},"relearn":"A laugh isn't consent; ask for a clear, willing yes.","persona":"any","source":"FRIES / enthusiastic"},
  {"id":"mt-1364","cat":"what-consent-is","type":"strike-rewrite","hook":"\"If you don't ask, you can't be blamed.\"","myth":{"un":"Not asking keeps you in the clear.","re":"Not asking isn't safe; without a clear yes, you don't have consent.","why":"The yes has to be there, not just the absence of a question."},"relearn":"Skipping the question doesn't make it okay; you need a yes.","persona":"Arjun","source":"FRIES / presence of yes"},
  {"id":"mt-1365","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Once you're both excited, asking is pointless.\"","myth":{"un":"At a certain point you don't need to check.","re":"There's no point where checking stops mattering; consent is ongoing.","why":"Either person can change their mind at any moment."},"relearn":"Checking in never stops mattering; consent is ongoing.","persona":"Vijay","source":"FRIES / ongoing"},
  {"id":"mt-1366","cat":"what-consent-is","type":"strike-rewrite","hook":"\"A yes given just to end the nagging counts.\"","myth":{"un":"A 'fine, okay' to stop the pestering is consent.","re":"A worn-down yes isn't freely given, so it isn't real consent.","why":"Agreeing to make pressure stop isn't actually wanting it."},"relearn":"A yes given to end nagging isn't freely given consent.","persona":"any","source":"FRIES / freely given"},
  {"id":"mt-1367","cat":"what-consent-is","type":"strike-rewrite","hook":"\"You can read a yes from body language alone.\"","myth":{"un":"Body language alone tells you it's a yes.","re":"When unsure, you ask; a guessed yes from cues alone isn't consent.","why":"Cues can be misread, so check with words."},"relearn":"Don't guess a yes from cues; ask and get a clear answer.","persona":"any","source":"FRIES / enthusiastic"},
  {"id":"mt-1368","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Being a bit tipsy doesn't change anything.\"","myth":{"un":"A little drunk still means a valid yes.","re":"The more someone's judgment is impaired, the less a yes can be trusted; when unsure, wait.","why":"Consent needs a clear, capable mind."},"relearn":"When someone's impaired and you're unsure, wait, don't assume a yes.","persona":"Counsellor","source":"incapacitation"},
  {"id":"mt-1369","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Saying yes to someone older means it's all fine.\"","myth":{"un":"If they said yes, the age gap doesn't matter.","re":"A yes still has to be free and informed; a big power gap can make it not truly free.","why":"Real consent needs equal footing, not pressure from above."},"relearn":"A yes under a big power gap may not be truly free consent.","persona":"any","source":"freely given / power"},
  {"id":"mt-1370","cat":"what-consent-is","type":"strike-rewrite","hook":"\"Going quiet means they're enjoying it.\"","myth":{"un":"Silence means they're comfortable.","re":"Silence isn't a yes; going quiet can mean unsure or uncomfortable, so check in.","why":"Absence of a clear yes means stop and ask."},"relearn":"Silence isn't comfort or consent; pause and check in.","persona":"any","source":"FRIES / presence of yes"},
  {"id":"mt-1371","cat":"what-consent-is","type":"sort","hook":"Sort: a real, willing yes, or not?","items":[{"id":"a","text":"\"Yes, I'd love to\" said brightly"},{"id":"b","text":"A long pause then \"...okay, fine\""},{"id":"c","text":"Both checking in and grinning"},{"id":"d","text":"A yes to stop the asking"},{"id":"e","text":"A calm, sure \"yes, I want this\""},{"id":"f","text":"Looking away and saying nothing"}],"bins":[{"id":"yes","label":"Real yes","valence":"pos"},{"id":"no","label":"Not a yes","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"},"relearn":"A free, willing yes counts; a worn-down, reluctant or silent one doesn't.","persona":"any","source":"presence of yes"},
  {"id":"mt-1372","cat":"what-consent-is","type":"sort","hook":"Sort: meets the FRIES standard, or fails it?","items":[{"id":"a","text":"No pressure, totally free choice"},{"id":"b","text":"A yes based on a lie"},{"id":"c","text":"Both can stop anytime"},{"id":"d","text":"Yes to one step taken as yes to all"},{"id":"e","text":"Both genuinely keen and happy"},{"id":"f","text":"A yes after threats to break up"}],"bins":[{"id":"meets","label":"Meets it","valence":"pos"},{"id":"fails","label":"Fails it","valence":"neg"}],"key":{"a":"meets","b":"fails","c":"meets","d":"fails","e":"meets","f":"fails"},"relearn":"Free, reversible and enthusiastic meet FRIES; lies, threats and over-reach fail.","persona":"any","source":"FRIES"},
  {"id":"mt-1373","cat":"what-consent-is","type":"sort","hook":"Sort: can this person consent right now, or not?","items":[{"id":"a","text":"Awake, sober, clear-headed"},{"id":"b","text":"Passed out asleep"},{"id":"c","text":"Calm and fully alert"},{"id":"d","text":"Too drunk to stand"},{"id":"e","text":"Wide awake and keen"},{"id":"f","text":"Barely conscious"}],"bins":[{"id":"can","label":"Can consent","valence":"pos"},{"id":"cant","label":"Cannot now","valence":"neg"}],"key":{"a":"can","b":"cant","c":"can","d":"cant","e":"can","f":"cant"},"relearn":"A clear, awake mind can consent; someone incapacitated cannot, full stop.","persona":"Counsellor","source":"incapacitation"},
  {"id":"mt-1374","cat":"what-consent-is","type":"sort","hook":"Sort: is this an ongoing yes, or an expired one?","items":[{"id":"a","text":"Checking in again right now"},{"id":"b","text":"\"You agreed last week\""},{"id":"c","text":"Both still keen this moment"},{"id":"d","text":"\"You texted yes earlier\""},{"id":"e","text":"Asking warmly each new step"},{"id":"f","text":"\"We did it before, so it's fine\""}],"bins":[{"id":"now","label":"Yes, right now","valence":"pos"},{"id":"stale","label":"Not now","valence":"neg"}],"key":{"a":"now","b":"stale","c":"now","d":"stale","e":"now","f":"stale"},"relearn":"Consent is ongoing; only a yes in this moment counts, not an old one.","persona":"any","source":"FRIES / ongoing"},
  {"id":"mt-1375","cat":"what-consent-is","type":"sort","hook":"Sort: freely given, or under pressure?","items":[{"id":"a","text":"A relaxed, happy yes"},{"id":"b","text":"\"Fine, if you'll stop sulking\""},{"id":"c","text":"\"Yes, I really want to\""},{"id":"d","text":"A yes after being guilt-tripped"},{"id":"e","text":"An easy, no-pressure yes"},{"id":"f","text":"A yes once threats started"}],"bins":[{"id":"free","label":"Freely given","valence":"pos"},{"id":"forced","label":"Under pressure","valence":"neg"}],"key":{"a":"free","b":"forced","c":"free","d":"forced","e":"free","f":"forced"},"relearn":"A free, easy yes is consent; a guilt-tripped or threatened one isn't.","persona":"any","source":"FRIES / freely given"},
  {"id":"mt-1376","cat":"what-consent-is","type":"sort","hook":"Sort: is this consent, or just going along with it?","items":[{"id":"a","text":"Actively pulling them closer, keen"},{"id":"b","text":"Lying still, hoping it ends"},{"id":"c","text":"\"I've been wanting this\""},{"id":"d","text":"Agreeing to avoid an argument"},{"id":"e","text":"Both leaning in, smiling"},{"id":"f","text":"A flat \"whatever, sure\""}],"bins":[{"id":"want","label":"Really wants it","valence":"pos"},{"id":"along","label":"Just going along","valence":"neg"}],"key":{"a":"want","b":"along","c":"want","d":"along","e":"want","f":"along"},"relearn":"Genuine wanting is consent; lying still or 'whatever' is going along, not yes.","persona":"any","source":"FRIES / enthusiastic"},
  {"id":"mt-1377","cat":"what-consent-is","type":"sort","hook":"Sort: a yes to this exact thing, or a stretch beyond it?","items":[{"id":"a","text":"\"Yes\" to holding hands, for that"},{"id":"b","text":"\"Yes to a hug\" taken as more"},{"id":"c","text":"\"Yes to a kiss\", just a kiss"},{"id":"d","text":"One yes used for everything"},{"id":"e","text":"\"Yes to this\", clearly named"},{"id":"f","text":"A yes assumed to cover all"}],"bins":[{"id":"specific","label":"Specific yes","valence":"pos"},{"id":"overreach","label":"Over-reach","valence":"neg"}],"key":{"a":"specific","b":"overreach","c":"specific","d":"overreach","e":"specific","f":"overreach"},"relearn":"Consent is specific; a yes to one thing is never a yes to everything.","persona":"any","source":"FRIES / specific"},
  {"id":"mt-1378","cat":"what-consent-is","type":"sort","hook":"Sort: counts as informed consent, or a yes built on a lie?","items":[{"id":"a","text":"Both honest about the situation"},{"id":"b","text":"A yes after a removed-condom trick"},{"id":"c","text":"Nothing hidden, full picture"},{"id":"d","text":"Lying about being single"},{"id":"e","text":"Truthful, so the yes is real"},{"id":"f","text":"Faking facts to get a yes"}],"bins":[{"id":"informed","label":"Informed yes","valence":"pos"},{"id":"deceived","label":"Built on a lie","valence":"neg"}],"key":{"a":"informed","b":"deceived","c":"informed","d":"deceived","e":"informed","f":"deceived"},"relearn":"A yes needs the real picture; one secured by a lie isn't consent.","persona":"any","source":"FRIES / informed"},
  {"id":"mt-1379","cat":"what-consent-is","type":"sort","hook":"Sort: respects the right to stop, or ignores it?","items":[{"id":"a","text":"Stopping the instant they pause"},{"id":"b","text":"\"You can't stop now\""},{"id":"c","text":"\"Of course, let's stop\""},{"id":"d","text":"Carrying on after a \"wait\""},{"id":"e","text":"Checking they still want to"},{"id":"f","text":"Guilt-tripping them to keep going"}],"bins":[{"id":"respects","label":"Respects it","valence":"pos"},{"id":"ignores","label":"Ignores it","valence":"neg"}],"key":{"a":"respects","b":"ignores","c":"respects","d":"ignores","e":"respects","f":"ignores"},"relearn":"Consent is reversible; stopping when asked respects it, pushing on ignores it.","persona":"any","source":"FRIES / reversible"},
  {"id":"mt-1380","cat":"what-consent-is","type":"sort","hook":"Sort: is this a clear yes, or a hopeful guess?","items":[{"id":"a","text":"\"Yes, I want to\" in words"},{"id":"b","text":"\"They didn't stop me\""},{"id":"c","text":"A spoken, certain yes"},{"id":"d","text":"\"They seemed into it, probably\""},{"id":"e","text":"Asking and hearing a clear yes"},{"id":"f","text":"\"I just assumed it was fine\""}],"bins":[{"id":"clear","label":"Clear yes","valence":"pos"},{"id":"guess","label":"Just a guess","valence":"neg"}],"key":{"a":"clear","b":"guess","c":"clear","d":"guess","e":"clear","f":"guess"},"relearn":"Consent is a clear, spoken yes, never an assumption or a hopeful guess.","persona":"any","source":"presence of yes"},
  {"id":"mt-1381","cat":"what-consent-is","type":"match","hook":"Match each consent quality to a true example of it.","pairs":[{"left":"Freely given","right":"A yes with no pressure behind it"},{"left":"Reversible","right":"\"Actually, let's stop\" is honoured"},{"left":"Informed","right":"Both know the honest situation"},{"left":"Enthusiastic","right":"Both clearly want it, not tolerate it"},{"left":"Specific","right":"A yes to this, not to everything"}],"relearn":"FRIES describes a yes that's free, reversible, informed, enthusiastic and specific.","persona":"any","source":"FRIES"},
  {"id":"mt-1382","cat":"what-consent-is","type":"match","hook":"Match the unsure signal to the right response.","pairs":[{"left":"A long, quiet pause","right":"Pause and gently check in"},{"left":"\"I'm not sure...\"","right":"Take it as a no for now"},{"left":"They pull back a little","right":"Stop and ask if they're okay"},{"left":"A reluctant \"I guess\"","right":"Slow down, don't push ahead"},{"left":"A bright, clear \"yes!\"","right":"A green light to go on together"}],"relearn":"Anything short of a clear yes means pause and check; only a real yes is a go.","persona":"any","source":"reading consent"},
  {"id":"mt-1383","cat":"what-consent-is","type":"match","hook":"Match the myth to what's actually true.","pairs":[{"left":"\"Silence means yes\"","right":"Only a clear yes means yes"},{"left":"\"Yes once means yes always\"","right":"Consent is needed every time"},{"left":"\"A relationship is a yes\"","right":"Each time still needs a willing yes"},{"left":"\"Can't stop once started\"","right":"You can stop at any moment"},{"left":"\"A drunk yes counts\"","right":"Incapacitated means can't consent"}],"relearn":"Each consent myth has a simple truth: a free, ongoing, capable yes is the bar.","persona":"any","source":"myths vs truth"},
  {"id":"mt-1384","cat":"what-consent-is","type":"match","hook":"Match the FRIES word to what breaks it.","pairs":[{"left":"Freely given","right":"Broken by threats or guilt-trips"},{"left":"Reversible","right":"Broken by \"too late to stop\""},{"left":"Informed","right":"Broken by lying for a yes"},{"left":"Enthusiastic","right":"Broken by a worn-down \"fine\""},{"left":"Specific","right":"Broken by assuming one yes covers all"}],"relearn":"Pressure, lies, 'too late', a worn-down yes or over-reach each break the standard.","persona":"any","source":"FRIES"},
  {"id":"mt-1385","cat":"what-consent-is","type":"match","hook":"Match the situation to whether it's consent.","pairs":[{"left":"Both checking in, both keen","right":"Real, mutual consent"},{"left":"A yes won by wearing them down","right":"Not consent, it was coerced"},{"left":"A yes while barely awake","right":"Not consent, they can't agree now"},{"left":"\"Yes, I want this\", clearly","right":"A genuine, willing yes"},{"left":"Going along to avoid a row","right":"Not consent, just enduring it"}],"relearn":"Only a free, willing, capable yes is consent; coerced, drowsy or endured isn't.","persona":"any","source":"standard"},
  {"id":"mt-1386","cat":"what-consent-is","type":"match","hook":"Match the consent fact to why it matters.","pairs":[{"left":"A yes, not a missing no","right":"So we never proceed on guesswork"},{"left":"Reversible anytime","right":"So no one is trapped after starting"},{"left":"Specific to each thing","right":"So one yes can't be stretched"},{"left":"Needs a clear mind","right":"So no one is taken advantage of"},{"left":"Ongoing, every time","right":"So willingness is always current"}],"relearn":"Each part of consent exists to keep intimacy safe, current and truly mutual.","persona":"any","source":"standard"},
  {"id":"mt-1387","cat":"what-consent-is","type":"match","hook":"Match what someone says to what it really means.","pairs":[{"left":"\"...I guess so\"","right":"Unsure, so pause and check in"},{"left":"\"Yes, definitely!\"","right":"A clear, willing yes"},{"left":"\"Can we slow down?\"","right":"A boundary to honour right away"},{"left":"\"Whatever you want\"","right":"Not their own yes, so check"},{"left":"\"I really want this\"","right":"Genuine, enthusiastic consent"}],"relearn":"Listen for a clear 'I want to'; anything vague means pause and check, not go.","persona":"any","source":"reading consent"},
  {"id":"mt-1388","cat":"what-consent-is","type":"reflect","hook":"Lensy: which part of 'a yes, not a non-no' lands hardest for you?","prompt":"Pick one.","options":["You wait for a real yes","Silence isn't agreement","Guessing is never enough"],"affirm":"Whichever you picked, you've got the core of it: proceed on a yes, never a maybe.","relearn":"Consent is the presence of a clear yes, never the absence of a no.","persona":"any","source":"presence of yes"},
  {"id":"mt-1389","cat":"what-consent-is","type":"reflect","hook":"Lensy: 'either of us can stop, anytime'. How does that land?","prompt":"What do you think?","options":["Reassuring","That's only fair","Both of us free"],"affirm":"That freedom to stop is what makes a yes trustworthy in the first place.","relearn":"Consent is reversible; the right to stop never expires.","persona":"any","source":"FRIES / reversible"},
  {"id":"mt-1390","cat":"what-consent-is","type":"reflect","hook":"Lensy: which FRIES quality do you think gets ignored most?","prompt":"Pick one.","options":["Freely given","Enthusiastic","Ongoing"],"affirm":"Naming the one that gets skipped is the first step to never skipping it yourself.","relearn":"FRIES holds only when every part is present, not just convenient ones.","persona":"any","source":"FRIES"},
  {"id":"mt-1391","cat":"what-consent-is","type":"reflect","hook":"Lensy: 'enthusiastic, not just allowed'. Does raising the bar there feel right?","prompt":"What do you think?","options":["Yes","Tolerating isn't enough","Both should want it"],"affirm":"Wanting it, not just permitting it, is what makes intimacy good, not only okay.","relearn":"Consent is enthusiastic; both actively want it, not merely tolerate it.","persona":"any","source":"FRIES / enthusiastic"},
  {"id":"mt-1392","cat":"what-consent-is","type":"reflect","hook":"Lensy: what would you want a younger friend to know about consent?","prompt":"Pick one to pass on.","options":["A yes, every time","You can always stop","No one owes anyone"],"affirm":"Passing on any of those is a real gift; you're already thinking the right way.","relearn":"Consent is a free, ongoing yes; no one ever owes anyone intimacy.","persona":"Sneha","source":"standard"},
  {"id":"mt-1393","cat":"what-consent-is","type":"reflect","hook":"Lensy: does 'checking in is part of intimacy, not a mood-killer' ring true?","prompt":"What do you think?","options":["Yes","It's caring","Makes it better"],"affirm":"Asking 'is this okay?' is warm, not awkward; it's how trust gets built.","relearn":"Checking in is normal and caring, part of intimacy, not a mood-killer.","persona":"any","source":"checking in"},
  {"id":"mt-1394","cat":"what-consent-is","type":"reflect","hook":"Lensy: 'no relationship is automatic consent'. Sit with that for a second.","prompt":"What do you think?","options":["Makes sense","Each time matters","Fair to both"],"affirm":"Being a couple means trust and asking, never an assumed yes; you've got it.","relearn":"A relationship is never standing consent; each time needs a willing yes.","persona":"any","source":"FRIES / ongoing"},
  {"id":"mt-1395","cat":"what-consent-is","type":"reflect","hook":"Lensy: which feels more true to you, consent as a rule, or as care?","prompt":"There's no wrong answer.","options":["A rule that protects","A way of caring","Honestly, both"],"affirm":"Held either way, it leads to the same place: a yes that's real and mutual.","relearn":"Consent is both a clear standard and a way of caring for each other.","persona":"any","source":"positive standard"},
  {"id":"mt-1396","cat":"what-consent-is","type":"reflect","hook":"Lensy: 'someone too out of it can't consent'. Why does that one matter so much?","prompt":"Pick what resonates.","options":["It protects people","A clear mind is needed","No grey area there"],"affirm":"Holding that line, no grey area, keeps people safe when they can't speak for themselves.","relearn":"Someone incapacitated cannot consent, full stop; there's no grey area.","persona":"Counsellor","source":"incapacitation"},
  {"id":"mt-1397","cat":"what-consent-is","type":"reflect","hook":"Lensy: 'mutual or nothing' as a life rule, not just for now. Does it fit?","prompt":"What do you think?","options":["Yes, for life","A keeper","Always mutual"],"affirm":"This standard carries into every adult relationship; you're keeping it for good.","relearn":"Mutual, enthusiastic consent is a lifelong principle, not a one-time lesson.","persona":"any","source":"core idea"},
  {"id":"mt-1398","cat":"what-consent-is","type":"spot","hook":"Spot the two lines that aren't real consent.","scene":[{"id":"a","text":"\"Yes, I really want to,\" said clearly","trick":false},{"id":"b","text":"A worn-down \"fine, okay then\"","trick":true},{"id":"c","text":"Both checking in and keen","trick":false},{"id":"d","text":"Silence and looking away","trick":true},{"id":"e","text":"A bright, easy \"yes, let's\"","trick":false}],"why":"A worn-down 'fine' and silence aren't consent; only a free, willing yes is.","relearn":"Consent is a clear, free yes, never a worn-down 'fine' or silence.","persona":"any","source":"presence of yes"},
  {"id":"mt-1399","cat":"what-consent-is","type":"spot","hook":"Spot the two situations where someone can't truly consent.","scene":[{"id":"a","text":"Awake, sober, clearly keen","trick":false},{"id":"b","text":"Half-asleep and mumbling","trick":true},{"id":"c","text":"Alert and saying \"yes, I want this\"","trick":false},{"id":"d","text":"Too drunk to stand up","trick":true},{"id":"e","text":"Calm, clear-headed and willing","trick":false}],"why":"Someone half-asleep or very drunk can't consent; a clear, awake mind can.","relearn":"A person who's incapacitated can't consent; consent needs a clear mind.","persona":"Counsellor","source":"incapacitation"},
  {"id":"mt-1400","cat":"what-consent-is","type":"spot","hook":"Spot the two lines that assume a yes was given.","scene":[{"id":"a","text":"\"Is this okay? We can stop anytime.\"","trick":false},{"id":"b","text":"\"You didn't say no, so it's fine.\"","trick":true},{"id":"c","text":"\"Tell me if you want to slow down.\"","trick":false},{"id":"d","text":"\"We're together, so I don't need to ask.\"","trick":true},{"id":"e","text":"\"Are you sure? Only if you want to.\"","trick":false}],"why":"A missing no and 'being together' aren't a yes; you ask and wait for a real one.","relearn":"Consent is asked for and given, never assumed from silence or a relationship.","persona":"any","source":"presence of yes"},
  {"id":"mt-1401","cat":"what-consent-is","type":"spot","hook":"Spot the two yeses that aren't freely given.","scene":[{"id":"a","text":"\"Yes, I'd love to\" with a grin","trick":false},{"id":"b","text":"\"Okay, just stop guilt-tripping me\"","trick":true},{"id":"c","text":"A relaxed, no-pressure \"yes\"","trick":false},{"id":"d","text":"\"Fine, or you'll tell everyone\"","trick":true},{"id":"e","text":"\"Yes, I really want this\"","trick":false}],"why":"A yes to stop guilt or under a threat isn't free, so it isn't real consent.","relearn":"Consent is freely given; a guilt-tripped or threatened yes doesn't count.","persona":"any","source":"FRIES / freely given"},
  {"id":"mt-1402","cat":"what-consent-is","type":"spot","hook":"Spot the two yeses that stretch one consent too far.","scene":[{"id":"a","text":"\"Yes to a kiss\", just the kiss","trick":false},{"id":"b","text":"\"You said yes once, so anything goes\"","trick":true},{"id":"c","text":"Asking again before the next step","trick":false},{"id":"d","text":"Treating a hug yes as more","trick":true},{"id":"e","text":"\"Yes to this exact thing\"","trick":false}],"why":"A yes to one thing isn't a yes to all; stretching it ignores that it's specific.","relearn":"Consent is specific; one yes never covers everything that follows.","persona":"any","source":"FRIES / specific"},
  {"id":"mt-1403","cat":"what-consent-is","type":"spot","hook":"Spot the two lines that ignore the right to stop.","scene":[{"id":"a","text":"\"Of course, let's stop now.\"","trick":false},{"id":"b","text":"\"You can't change your mind now.\"","trick":true},{"id":"c","text":"\"Tell me anytime and we'll pause.\"","trick":false},{"id":"d","text":"\"We already started, too late.\"","trick":true},{"id":"e","text":"Stopping the moment they pull back","trick":false}],"why":"Consent is reversible; 'can't change your mind' and 'too late' ignore that.","relearn":"You can stop at any moment; an earlier yes is never a trap.","persona":"any","source":"FRIES / reversible"},
  {"id":"mt-1404","cat":"what-consent-is","type":"spot","hook":"Spot the two yeses built on a lie or a trick.","scene":[{"id":"a","text":"Both honest about everything","trick":false},{"id":"b","text":"A yes after lying about being single","trick":true},{"id":"c","text":"Nothing hidden, full picture shared","trick":false},{"id":"d","text":"A yes, then secretly removing protection","trick":true},{"id":"e","text":"Truthful, so the yes is real","trick":false}],"why":"A yes secured by a lie or a hidden trick isn't informed, so it isn't consent.","relearn":"Consent is informed; a yes won by deception isn't real consent.","persona":"any","source":"FRIES / informed"},
  {"id":"mt-1405","cat":"what-consent-is","type":"role-play","hook":"Things are moving fast and you want to make sure you're both in.","setup":"Check in warmly. Say:","yourLine":[{"text":"\"Hey, are you happy with this? We can slow down anytime.\"","best":true},{"text":"Stay quiet and just assume it's fine"}],"relearn":"Asking 'are you happy with this?' makes consent clear and shared.","persona":"Vijay","source":"checking in"},
  {"id":"mt-1406","cat":"what-consent-is","type":"role-play","hook":"You said yes earlier but now you're not feeling it.","setup":"You're allowed to change your mind. Say:","yourLine":[{"text":"\"I know I said yes, but I want to stop now.\"","best":true},{"text":"Go along with it so you don't seem difficult"}],"relearn":"An earlier yes isn't binding; you can say 'I want to stop now' anytime.","persona":"Sneha","source":"FRIES / reversible"},
  {"id":"mt-1407","cat":"what-consent-is","type":"role-play","hook":"Your partner says a clear, happy yes and you want to honour that it's specific.","setup":"Keep checking as things move. Say:","yourLine":[{"text":"\"Is this okay too? Only if you want.\"","best":true},{"text":"Assume their first yes covers everything"}],"relearn":"Each new step needs its own yes; asking again keeps consent specific.","persona":"any","source":"FRIES / specific"},
  {"id":"mt-1408","cat":"what-consent-is","type":"role-play","hook":"You can't tell if your partner actually wants to or is just going along.","setup":"Make space for an honest answer. Say:","yourLine":[{"text":"\"I want you to really want this too, no pressure either way.\"","best":true},{"text":"Take their quiet as a yes and carry on"}],"relearn":"You want genuine enthusiasm, not going-along; saying so makes that safe.","persona":"any","source":"FRIES / enthusiastic"},
  {"id":"mt-1409","cat":"what-consent-is","type":"role-play","hook":"A partner asks if you want to and you genuinely don't know yet.","setup":"'Not sure yet' is a full answer. Say:","yourLine":[{"text":"\"I'm not sure yet, can we just slow down?\"","best":true},{"text":"Say \"yes\" to avoid the awkwardness"}],"relearn":"'I'm not sure yet' is a complete answer; you never owe a rushed yes.","persona":"any","source":"honesty"},
  {"id":"mt-1410","cat":"what-consent-is","type":"role-play","hook":"Your partner has had a few drinks and you're not sure they can really decide.","setup":"When in doubt, wait. Say:","yourLine":[{"text":"\"Let's wait till we're both clear-headed, no rush.\"","best":true},{"text":"Take their tipsy \"yeah, sure\" as a real yes"}],"relearn":"When someone's impaired, a clear mind comes first; waiting is the caring move.","persona":"Arjun","source":"incapacitation"},
  {"id":"mt-1411","cat":"what-consent-is","type":"role-play","hook":"You want to set the tone that a 'no' is always completely fine.","setup":"Say it out loud so they know. Say:","yourLine":[{"text":"\"Whatever you say, even no, is totally okay with me.\"","best":true},{"text":"Hint that a no would disappoint you"}],"relearn":"Saying 'a no is okay' makes a yes free and real, not pressured.","persona":"any","source":"freely given"},
  {"id":"mt-1412","cat":"what-consent-is","type":"role-play","hook":"A partner asks you to do something and you only half-want to.","setup":"Half-willing isn't the bar. Say:","yourLine":[{"text":"\"I'm only half into it, so let's not right now.\"","best":true},{"text":"Do it anyway so they're not let down"}],"relearn":"Half-willing isn't a yes; you can wait until you genuinely want to.","persona":"any","source":"FRIES / enthusiastic"},
  {"id":"mt-1413","cat":"what-consent-is","type":"branch","hook":"Your partner gave a quiet, unsure \"...okay\". What's the real consent move?","options":[{"text":"Pause and ask if they actually want to","consequence":"You give them room for an honest yes or no.","outcome":"checks-in","best":true},{"text":"Take the \"okay\" and keep going","consequence":"An unsure 'okay' isn't a yes; pause and check first."}],"debrief":"A hesitant 'okay' is a cue to check in, not a green light.","relearn":"An unsure 'okay' isn't consent; pause and ask for a real yes.","persona":"any","source":"FRIES / enthusiastic"},
  {"id":"mt-1414","cat":"what-consent-is","type":"branch","hook":"You're keen but you can't read whether your partner is. What now?","options":[{"text":"Ask plainly: \"Do you want this? Honestly?\"","consequence":"You get a clear answer instead of guessing.","outcome":"asks","best":true},{"text":"Assume their silence means yes","consequence":"Silence isn't a yes; ask and wait for a clear answer."}],"debrief":"When you can't read it, you ask; you never proceed on a guess.","relearn":"Consent is a clear yes; when unsure, ask rather than assume.","persona":"Vijay","source":"presence of yes"},
  {"id":"mt-1415","cat":"what-consent-is","type":"branch","hook":"Midway, your partner goes still and quiet. What do you do?","options":[{"text":"Stop and gently check they're still okay","consequence":"You catch a change in willingness early and honour it.","outcome":"checks-in","best":true},{"text":"Carry on since they said yes before","consequence":"An earlier yes isn't ongoing; a change means pause and check."}],"debrief":"Willingness can change anytime; going quiet is a cue to pause, not push.","relearn":"Consent is ongoing; if willingness drops, pause and check in.","persona":"any","source":"FRIES / ongoing"},
  {"id":"mt-1416","cat":"what-consent-is","type":"branch","hook":"Your partner said yes but had several drinks. What's the right call?","options":[{"text":"Wait until you're both sober and sure","consequence":"You make sure any yes is clear-headed and real.","outcome":"waits","best":true},{"text":"Go ahead since they technically said yes","consequence":"A yes from someone too impaired to decide isn't real consent."}],"debrief":"When someone may be incapacitated, the safe and caring choice is to wait.","relearn":"Someone too impaired to decide can't truly consent; wait until clear.","persona":"Counsellor","source":"incapacitation"},
  {"id":"mt-1417","cat":"what-consent-is","type":"branch","hook":"Your partner happily said yes to kissing. You want to go further. What now?","options":[{"text":"Ask first: \"Is this okay too?\"","consequence":"You keep each step its own clear, willing yes.","outcome":"asks","best":true},{"text":"Treat the kiss yes as a yes to more","consequence":"A yes to one thing isn't a yes to the next; ask again."}],"debrief":"Consent is specific; a yes to one step never covers the next.","relearn":"Each new step needs its own yes; one yes isn't a yes to all.","persona":"any","source":"FRIES / specific"},
  {"id":"mt-1418","cat":"what-consent-is","type":"branch","hook":"You said yes earlier, but now you'd rather stop. What do you do?","options":[{"text":"Say so: \"I've changed my mind, let's stop.\"","consequence":"Your partner respects it; you were never locked in.","outcome":"stops","best":true},{"text":"Push through because you already agreed","consequence":"An earlier yes isn't binding; you can stop at any moment."}],"debrief":"Consent is reversible; changing your mind is always allowed, no reason owed.","relearn":"You can withdraw a yes anytime; an earlier yes never traps you.","persona":"Sneha","source":"FRIES / reversible"},
  {"id":"mt-1419","cat":"what-consent-is","type":"branch","hook":"A friend says \"we're dating, so I don't really need to ask each time.\" What do you say?","options":[{"text":"\"You do, though, dating isn't a standing yes.\"","consequence":"You set them straight that consent is needed every time.","outcome":"corrects","best":true},{"text":"\"Yeah, I guess once you're together it's fine\"","consequence":"A relationship is never automatic consent; a yes is needed each time."}],"debrief":"No relationship status replaces a clear, willing yes for each time.","relearn":"Dating isn't standing consent; each time still needs a real yes.","persona":"Arjun","source":"FRIES / ongoing"},
  {"id":"mt-1420","cat":"what-consent-is","type":"branch","hook":"Your partner says \"only if you really want to, no pressure.\" How do you take it?","options":[{"text":"As genuine care, and answer honestly","consequence":"You both get a yes that's real because it's truly free.","outcome":"honest","best":true},{"text":"As a hint you should just say yes","consequence":"'No pressure' means exactly that; answer for yourself, freely."}],"debrief":"A real 'no pressure' frees you to give an honest yes or no; that's the point.","relearn":"Consent is freely given; 'no pressure' means your honest answer is welcome.","persona":"any","source":"FRIES / freely given"},
];

